INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C1','math',5,2,'u2',2,'같은 수를 여러 번 더하기 — 분모가 같은 분수의 덧셈·뺄셈과 약분(기약분수)을 되짚고, 같은 분수를 여러 번 더하는 자리를 (분수)×(자연수)로 적으면 몇 번을 더하든 한 줄로 끝남을 알기',ARRAY['6수01-08']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C2','math',5,2,'u2',2,'(진분수)×(자연수) — 수직선에서 같은 분수씩 뛰어 세어 보고, 분모는 그대로 두고 분자와 자연수를 곱하며(한 칸의 크기는 그대로, 칸의 수만 늘어남) 약분은 곱하기 전·중·후 언제 해도 값이 같음을 알기',ARRAY['6수01-08']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C3','math',5,2,'u2',3,'(대분수)×(자연수) — 대분수를 자연수 부분과 진분수 부분으로 갈라 각각 곱해 더하거나, 가분수로 고쳐 분자와 자연수를 곱하고, 가분수로 고치기 전에 약분하면 자연수 부분이 빠져 틀림을 알기',ARRAY['6수01-08']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C4','math',5,2,'u2',4,'(자연수)×(진분수) — 「6의 ⟨2/3⟩」처럼 전체를 분모만큼 똑같이 나눈 것 중의 분자만큼을 구하는 곱셈임을 알고, 분모는 그대로 두고 자연수와 분자를 곱하며 ⟨3/5⟩ × 2와 2 × ⟨3/5⟩은 뜻은 달라도 값은 같음을 알기',ARRAY['6수01-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C5','math',5,2,'u2',5,'(자연수)×(대분수) — 직사각형을 둘로 갈라 더하거나 가분수로 고쳐 계산하고, 곱하는 수가 1보다 작으면 결과가 작아지고 1이면 그대로, 1보다 커야 커짐을 계산 전에 어림하기',ARRAY['6수01-08']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C6','math',5,2,'u2',6,'(진분수)×(진분수) — 전체를 가로·세로로 잘라 (분모×분모) 칸 가운데 (분자×분자) 칸임을 그림으로 알고, 분모는 분모끼리·분자는 분자끼리 곱하며 약분은 분자와 분모 사이에서만 함을 알기',ARRAY['6수01-08']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C7','math',5,2,'u2',7,'대분수끼리·세 분수의 곱셈 — 대분수는 가분수로 고치고 자연수는 분모가 1인 분수로 보아 분수가 몇 개든 분모끼리·분자끼리 곱하는 한 규칙으로 계산하고, 곱하는 순서를 바꾸어도 값이 같음을 알기',ARRAY['6수01-08']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C8','math',5,2,'u2',8,'문제 해결 — 「전체의 몇 분의 몇 이상」 문제에서 없는 정보(전체 수)를 먼저 찾고, 최소로 필요한 수를 곱셈으로 구한 뒤 지금까지의 수를 빼서 더 필요한 수를 구하기',ARRAY['6수01-08']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X01','math',5,'u2',ARRAY['M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C4','M5-2-u2-C5']::text[],'(분수)×(자연수)에서 분모에도 자연수를 곱한다(⟨2/5⟩ × 4를 ⟨8/20⟩으로)','분모는 그대로 — 한 칸 크기는 안 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X02','math',5,'u2',ARRAY['M5-2-u2-C2','M5-2-u2-C4']::text[],'자연수를 분자가 아니라 분모에 곱한다(⟨2/5⟩ × 4를 ⟨2/20⟩으로)','자연수는 분자와 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X03','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2']::text[],'같은 분수를 여러 번 더할 때 분모끼리도 더한다(⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩을 ⟨9/30⟩으로)','분모가 같으면 분자끼리만 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X04','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C5','M5-2-u2-C7']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 곱하고 분모를 곱하지 않는다)','자연수 × 분모 + 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X05','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C5']::text[],'대분수와 자연수를 곱할 때 자연수 부분에만 또는 분수 부분에만 곱한다(⟨1 1/4⟩ × 3을 ⟨3 1/4⟩이나 ⟨1 3/4⟩으로)','자연수 부분도 분수 부분도 모두 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X06','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C7']::text[],'대분수를 가분수로 고치지 않고 먼저 약분해 자연수 부분이 약분에서 빠진다','약분은 가분수로 고친 뒤에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X07','math',5,'u2',ARRAY['M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C8']::text[],'「전체의 몇 분의 몇」을 구할 때 분모로 나누기만 하거나 분자만 곱한다(6의 ⟨2/3⟩을 2나 12로)','분모만큼 나눈 것 중의 분자만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X08','math',5,'u2',ARRAY['M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C6']::text[],'곱하면 언제나 커진다고 여긴다(1보다 작은 수를 곱해도 커진다고 본다)','1보다 작은 수를 곱하면 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X09','math',5,'u2',ARRAY['M5-2-u2-C6','M5-2-u2-C7']::text[],'(분수)×(분수)에서 분모는 그대로 두고 분자끼리만 곱한다(⟨4/5⟩ × ⟨2/3⟩을 ⟨8/5⟩로)','분모도 분모끼리 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X10','math',5,'u2',ARRAY['M5-2-u2-C6','M5-2-u2-C7']::text[],'분수끼리 곱할 때 분모와 분자를 엇갈려 곱하거나 분모·분자끼리 더한다','분모는 분모끼리, 분자는 분자끼리 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X11','math',5,'u2',ARRAY['M5-2-u2-C7']::text[],'대분수끼리 곱할 때 자연수 부분끼리, 분수 부분끼리 따로 곱한다(⟨3 1/2⟩ × ⟨1 4/5⟩를 ⟨3 4/10⟩으로)','대분수는 둘 다 가분수로 고쳐서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X12','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C5','M5-2-u2-C6','M5-2-u2-C7']::text[],'계산 마무리 실수 — 약분하지 않거나 기약분수가 아닌데 멈추거나, 가분수·대분수를 잘못 고친다','끝까지 약분하고 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X13','math',5,'u2',ARRAY['M5-2-u2-C2','M5-2-u2-C6','M5-2-u2-C7']::text[],'약분을 분자끼리 또는 분모끼리 한다(같은 쪽끼리 약분한다)','약분은 분자와 분모 사이에서만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X14','math',5,'u2',ARRAY['M5-2-u2-C7']::text[],'자연수를 분수로 볼 때 분모가 1인 분수로 보지 못한다(2를 ⟨2/2⟩로 본다)','자연수 2 = ⟨2/1⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X15','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C6','M5-2-u2-C7']::text[],'문장에서 곱셈식을 세우지 못하고 덧셈 등 다른 연산을 쓴다','「몇 번」「몇 분의 몇」은 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X16','math',5,'u2',ARRAY['M5-2-u2-C8']::text[],'문제 해결에서 필요한 정보(전체 수)를 놓치거나, 최소로 필요한 수를 구한 뒤 빼지 않는다(순서를 거꾸로 한다)','① 최소 수 구하기 → ② 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X17','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C6','M5-2-u2-C7','M5-2-u2-C8']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔알맞은, 큰↔작은, 분자↔분모·자연수 부분','물음의 「잘못·가장·분모」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#1','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨3/10⟩ × 3","correct":true},{"t":"⟨3/10⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨3/10⟩ + 3","mis":"M5-2-u2-X15"},{"t":"3 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨3/10⟩을 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨3/10⟩ × 3이에요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩ + ⟨2/7⟩ + ⟨2/7⟩ + ⟨2/7⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨2/7⟩ × 4","correct":true},{"t":"⟨2/7⟩ × 5","mis":"M5-2-u2-X17"},{"t":"⟨2/7⟩ + 4","mis":"M5-2-u2-X15"},{"t":"2 × 4","mis":"M5-2-u2-X15"}],"explanation":["⟨2/7⟩를 4번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨2/7⟩ + ⟨2/7⟩ + ⟨2/7⟩ + ⟨2/7⟩ = ⟨2/7⟩ × 4예요."]},{"stem":"⟨4/9⟩ + ⟨4/9⟩ + ⟨4/9⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨4/9⟩ × 3","correct":true},{"t":"⟨4/9⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨4/9⟩ + 3","mis":"M5-2-u2-X15"},{"t":"4 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨4/9⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨4/9⟩ + ⟨4/9⟩ + ⟨4/9⟩ = ⟨4/9⟩ × 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#2','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":2,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/1⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","5와 30을 모두 5로 나눌 수 있어요 — 5 ÷ 5 = 1, 30 ÷ 5 = 6.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨5/30⟩ = ⟨1/6⟩."],"variant_rule":{"alt":[{"stem":"⟨6/27⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨9/2⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/5⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","6과 27을 모두 3으로 나눌 수 있어요 — 6 ÷ 3 = 2, 27 ÷ 3 = 9.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨6/27⟩ = ⟨2/9⟩."]},{"stem":"⟨8/36⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨9/2⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/5⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","8과 36을 모두 4로 나눌 수 있어요 — 8 ÷ 4 = 2, 36 ÷ 4 = 9.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨8/36⟩ = ⟨2/9⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#3','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','⟨3/7⟩ + ⟨6/7⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12']::text[],true,'{"seq":3,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨3/7⟩ + ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨9/14⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 3/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨2 2/7⟩","mis":"M5-2-u2-X12"}],"explanation":["분모가 같은 분수의 덧셈은 분모를 그대로 두고 분자끼리 더해요.","⟨3/7⟩ + ⟨6/7⟩ = ⟨9/7⟩예요.","가분수를 대분수로 고치면 ⟨9/7⟩ = ⟨1 2/7⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩ + ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/8⟩","correct":true},{"t":"⟨9/16⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 1/4⟩","mis":"M5-2-u2-X12"},{"t":"⟨2 1/8⟩","mis":"M5-2-u2-X12"}],"explanation":["분모가 같은 분수의 덧셈은 분모를 그대로 두고 분자끼리 더해요.","⟨4/8⟩ + ⟨5/8⟩ = ⟨9/8⟩예요.","가분수를 대분수로 고치면 ⟨9/8⟩ = ⟨1 1/8⟩이에요."]},{"stem":"⟨2/6⟩ + ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/6⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 1/3⟩","mis":"M5-2-u2-X12"},{"t":"⟨2 1/6⟩","mis":"M5-2-u2-X12"}],"explanation":["분모가 같은 분수의 덧셈은 분모를 그대로 두고 분자끼리 더해요.","⟨2/6⟩ + ⟨5/6⟩ = ⟨7/6⟩이에요.","가분수를 대분수로 고치면 ⟨7/6⟩ = ⟨1 1/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#4','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',1,'sa','auto','⟨1/4⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C2","difficulty":1,"kind":"sa","stem":"⟨1/4⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 1 × 3 = 3이에요.","⟨1/4⟩ × 3 = ⟨3/4⟩이에요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨2/9⟩ × 4를 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 2 × 4 = 8이에요.","⟨2/9⟩ × 4 = ⟨8/9⟩이에요."]},{"stem":"⟨3/11⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 3 × 3 = 9예요.","⟨3/11⟩ × 3 = ⟨9/11⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#5','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',2,'mc','auto','여울, 순달과 달곰이 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유는 모두 몇 L인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":5,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"여울, 순달과 달곰이 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유는 모두 몇 L인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨9/30⟩","mis":"M5-2-u2-X03"},{"t":"⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X15"}],"explanation":["3명이 ⟨3/10⟩ L씩 남겼으니 ⟨3/10⟩을 3번 더해요.","곱셈으로 적으면 ⟨3/10⟩ × 3이에요.","⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨9/10⟩ — 모두 ⟨9/10⟩ L예요."],"variant_rule":{"alt":[{"stem":"수아, 도윤과 하린이 딸기우유를 ⟨2/9⟩ L씩 남겼어요. 남긴 딸기우유는 모두 몇 L인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨6/27⟩","mis":"M5-2-u2-X03"},{"t":"⟨2/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨5/9⟩","mis":"M5-2-u2-X15"}],"explanation":["3명이 ⟨2/9⟩ L씩 남겼으니 ⟨2/9⟩를 3번 더해요.","곱셈으로 적으면 ⟨2/9⟩ × 3이에요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨2/3⟩ — 모두 ⟨2/3⟩ L예요."]},{"stem":"민준, 서연과 지호가 딸기우유를 ⟨3/8⟩ L씩 남겼어요. 남긴 딸기우유는 모두 몇 L인가요?","options":[{"t":"⟨1 1/8⟩","correct":true},{"t":"⟨9/24⟩","mis":"M5-2-u2-X03"},{"t":"⟨3/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/4⟩","mis":"M5-2-u2-X15"}],"explanation":["3명이 ⟨3/8⟩ L씩 남겼으니 ⟨3/8⟩을 3번 더해요.","곱셈으로 적으면 ⟨3/8⟩ × 3이에요.","⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ = ⟨1 1/8⟩ — 모두 ⟨1 1/8⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#6','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','⟨2/5⟩ × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":6,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨2/5⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨8/20⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/20⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이에요.","한 칸의 크기 ⟨1/5⟩은 그대로이고 칸의 수만 4배가 돼요."],"variant_rule":{"alt":[{"stem":"⟨1/9⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨5/45⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/45⟩","mis":"M5-2-u2-X02"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/9⟩ × 5 = ⟨5/9⟩예요.","한 칸의 크기 ⟨1/9⟩은 그대로이고 칸의 수만 5배가 돼요."]},{"stem":"⟨5/6⟩ × 7을 계산하면 얼마인가요?","options":[{"t":"⟨5 5/6⟩","correct":true},{"t":"⟨35/42⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/42⟩","mis":"M5-2-u2-X02"},{"t":"2","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩예요.","한 칸의 크기 ⟨1/6⟩은 그대로이고 칸의 수만 7배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#7','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','수직선의 0에서 ⟨1/4⟩씩 3번 뛰어 세면 어느 수에 닿나요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":7,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"수직선의 0에서 ⟨1/4⟩씩 3번 뛰어 세면 어느 수에 닿나요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨3/12⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X17"},{"t":"1","mis":"M5-2-u2-X17"}],"explanation":["⟨1/4⟩씩 3번 뛰어 세면 ⟨1/4⟩ → ⟨1/2⟩ → ⟨3/4⟩이에요.","식으로는 ⟨1/4⟩ × 3이에요.","⟨1/4⟩ × 3 = ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"수직선의 0에서 ⟨2/7⟩씩 3번 뛰어 세면 어느 수에 닿나요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/7⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 1/7⟩","mis":"M5-2-u2-X17"}],"explanation":["⟨2/7⟩씩 3번 뛰어 세면 ⟨2/7⟩ → ⟨4/7⟩ → ⟨6/7⟩이에요.","식으로는 ⟨2/7⟩ × 3이에요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요."]},{"stem":"수직선의 0에서 ⟨3/10⟩씩 3번 뛰어 세면 어느 수에 닿나요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨9/30⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X17"}],"explanation":["⟨3/10⟩씩 3번 뛰어 세면 ⟨3/10⟩ → ⟨3/5⟩ → ⟨9/10⟩예요.","식으로는 ⟨3/10⟩ × 3이에요.","⟨3/10⟩ × 3 = ⟨9/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#8','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',2,'ox','auto','⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩은 ⟨3/10⟩ × 3과 같아요.',ARRAY['M5-2-u2-X15']::text[],true,'{"seq":8,"concept":"M5-2-u2-C1","difficulty":2,"kind":"ox","stem":"⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩은 ⟨3/10⟩ × 3과 같아요.","answer":"O","reason_options":[{"t":"같은 수를 세 번 더한 것은 그 수에 3을 곱한 것과 같으므로","correct":true},{"t":"분수는 곱셈으로 적을 수 없으므로","mis":"M5-2-u2-X15"}],"mis":"M5-2-u2-X15","explanation":["같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨3/10⟩ × 3이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩ + ⟨1/5⟩ = ⟨3/10⟩이에요.","answer":"X","reason_options":[{"t":"분모가 같으면 분모는 그대로 두고 분자끼리 더해 ⟨3/5⟩이므로","correct":true},{"t":"분모끼리, 분자끼리 모두 더해야 하므로","mis":"M5-2-u2-X03"}],"explanation":["분모가 같은 분수끼리는 분자끼리만 더해요.","⟨2/5⟩ + ⟨1/5⟩ = ⟨3/5⟩이에요.","⟨3/10⟩은 분모까지 더한 틀린 답이에요."]},{"stem":"⟨3/7⟩ + ⟨6/7⟩을 대분수로 나타내면 ⟨1 2/14⟩예요.","answer":"X","reason_options":[{"t":"⟨3/7⟩ + ⟨6/7⟩ = ⟨9/7⟩ = ⟨1 2/7⟩이므로","correct":true},{"t":"대분수로 고치면 분모가 두 배가 되므로","mis":"M5-2-u2-X03"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨3/7⟩ + ⟨6/7⟩ = ⟨9/7⟩예요.","⟨9/7⟩ = ⟨1 2/7⟩ — 분모는 7 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#9','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','운동회 응원 현수막을 만들려고 길이가 ⟨1/4⟩ m인 천 3장을 이어 붙였어요. 사용한 천은 모두 몇 m인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"운동회 응원 현수막을 만들려고 길이가 ⟨1/4⟩ m인 천 3장을 이어 붙였어요. 사용한 천은 모두 몇 m인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨3/12⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/12⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["⟨1/4⟩ m짜리 천 3장이니 ⟨1/4⟩ × 3이에요.","분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/4⟩ × 3 = ⟨3/4⟩ — ⟨3/4⟩ m예요."],"variant_rule":{"alt":[{"stem":"운동회 응원 현수막을 만들려고 길이가 ⟨2/5⟩ m인 천 3장을 이어 붙였어요. 사용한 천은 모두 몇 m인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨6/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["⟨2/5⟩ m짜리 천 3장이니 ⟨2/5⟩ × 3이에요.","분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/5⟩ × 3 = ⟨6/5⟩ = ⟨1 1/5⟩ — ⟨1 1/5⟩ m예요."]},{"stem":"운동회 응원 현수막을 만들려고 길이가 ⟨3/8⟩ m인 천 2장을 이어 붙였어요. 사용한 천은 모두 몇 m인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨6/16⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/16⟩","mis":"M5-2-u2-X02"},{"t":"⟨5/8⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨3/8⟩ m짜리 천 2장이니 ⟨3/8⟩ × 2예요.","분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/8⟩ × 2 = ⟨6/8⟩ = ⟨3/4⟩ — ⟨3/4⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_basic#10','math',5,2,'u2','L02','g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',3,'mc','auto','⟨2/5⟩ × 4와 ⟨3/4⟩ × 2 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X01']::text[],true,'{"seq":10,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"⟨2/5⟩ × 4와 ⟨3/4⟩ × 2 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩ × 4","correct":true},{"t":"⟨3/4⟩ × 2","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X01"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨2/5⟩ × 4 = ⟨1 3/5⟩이에요.","⟨3/4⟩ × 2 = ⟨1 1/2⟩이에요.","⟨1 3/5⟩ > ⟨1 1/2⟩이라 ⟨2/5⟩ × 4가 더 커요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ × 5와 ⟨3/8⟩ × 4 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1/3⟩ × 5","correct":true},{"t":"⟨3/8⟩ × 4","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X01"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1/3⟩ × 5 = ⟨1 2/3⟩예요.","⟨3/8⟩ × 4 = ⟨1 1/2⟩이에요.","⟨1 2/3⟩ > ⟨1 1/2⟩이라 ⟨1/3⟩ × 5가 더 커요."]},{"stem":"⟨5/6⟩ × 2와 ⟨2/3⟩ × 3 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2/3⟩ × 3","correct":true},{"t":"⟨5/6⟩ × 2","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X01"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨5/6⟩ × 2 = ⟨1 2/3⟩예요.","⟨2/3⟩ × 3 = 2예요.","⟨1 2/3⟩ < 2라 ⟨2/3⟩ × 3이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#1','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C1',2,'mc','auto','⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/9⟩","correct":true},{"t":"⟨8/36⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/9⟩","mis":"M5-2-u2-X12"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨8/9⟩이에요.","⟨8/9⟩ — 분모까지 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨3/11⟩ + ⟨3/11⟩ + ⟨3/11⟩을 계산하면 얼마인가요?","options":[{"t":"⟨9/11⟩","correct":true},{"t":"⟨9/33⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 9/11⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/11⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨3/11⟩ + ⟨3/11⟩ + ⟨3/11⟩ = ⟨9/11⟩예요.","⟨9/11⟩ — 분모까지 더하면 안 돼요."]},{"stem":"⟨4/13⟩ + ⟨4/13⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/13⟩","correct":true},{"t":"⟨8/26⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/13⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/13⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨4/13⟩ + ⟨4/13⟩ = ⟨8/13⟩이에요.","⟨8/13⟩ — 분모까지 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#2','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',2,'sa','auto','⟨5/6⟩ × 7을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C2","difficulty":2,"kind":"sa","stem":"⟨5/6⟩ × 7을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩예요.","그래서 자연수 부분은 5예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"⟨3/4⟩ × 5를 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/4⟩ × 5 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","그래서 분자은 3이에요."]},{"stem":"⟨4/7⟩ × 5를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 5 = ⟨20/7⟩ = ⟨2 6/7⟩이에요.","그래서 자연수 부분은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#3','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'error','auto','⟨2/5⟩ × 4를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C2","difficulty":3,"kind":"error","stem":"⟨2/5⟩ × 4를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨2/5⟩ × 4 = ⟨8/20⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"도윤 — 「⟨2/5⟩ × 4 = ⟨8/5⟩」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨2/5⟩ × 4 = ⟨1 3/5⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이에요.","수아는 분모에도 4를 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨3/7⟩ × 2 = ⟨6/14⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"서연 — 「⟨3/7⟩ × 2 = ⟨6/7⟩」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨3/7⟩ × 2 = ⟨6/7⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨3/7⟩ × 2 = ⟨6/7⟩이에요.","민준은 분모에도 2를 곱해서 틀렸어요."]},{"stem":"⟨4/9⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨4/9⟩ × 2 = ⟨8/18⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"나린 — 「⟨4/9⟩ × 2 = ⟨8/9⟩」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨4/9⟩ × 2 = ⟨8/9⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨4/9⟩ × 2 = ⟨8/9⟩이에요.","가온은 분모에도 2를 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#4','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'mc','auto','계산 결과가 자연수인 것은 어느 것인가요?',ARRAY['M5-2-u2-X12']::text[],true,'{"seq":4,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩ × 10","correct":true},{"t":"⟨3/4⟩ × 5","mis":"M5-2-u2-X12"},{"t":"⟨1/6⟩ × 14","mis":"M5-2-u2-X12"},{"t":"⟨5/8⟩ × 3","mis":"M5-2-u2-X12"}],"explanation":["분자와 자연수를 곱한 수가 분모로 나누어떨어지면 자연수예요.","⟨3/4⟩ × 5 = ⟨3 3/4⟩, ⟨2/5⟩ × 10 = 4, ⟨1/6⟩ × 14 = ⟨2 1/3⟩, ⟨5/8⟩ × 3 = ⟨1 7/8⟩이에요.","그래서 자연수인 것은 ⟨2/5⟩ × 10이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × 8","correct":true},{"t":"⟨2/3⟩ × 4","mis":"M5-2-u2-X12"},{"t":"⟨5/6⟩ × 3","mis":"M5-2-u2-X12"},{"t":"⟨4/9⟩ × 2","mis":"M5-2-u2-X12"}],"explanation":["분자와 자연수를 곱한 수가 분모로 나누어떨어지면 자연수예요.","⟨2/3⟩ × 4 = ⟨2 2/3⟩, ⟨3/8⟩ × 8 = 3, ⟨5/6⟩ × 3 = ⟨2 1/2⟩, ⟨4/9⟩ × 2 = ⟨8/9⟩이에요.","그래서 자연수인 것은 ⟨3/8⟩ × 8이에요."]},{"stem":"이번에는 다른 보기예요. 계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨2/9⟩ × 9","correct":true},{"t":"⟨1/4⟩ × 6","mis":"M5-2-u2-X12"},{"t":"⟨5/7⟩ × 3","mis":"M5-2-u2-X12"},{"t":"⟨3/10⟩ × 5","mis":"M5-2-u2-X12"}],"explanation":["분자와 자연수를 곱한 수가 분모로 나누어떨어지면 자연수예요.","⟨1/4⟩ × 6 = ⟨1 1/2⟩, ⟨5/7⟩ × 3 = ⟨2 1/7⟩, ⟨3/10⟩ × 5 = ⟨1 1/2⟩, ⟨2/9⟩ × 9 = 2예요.","그래서 자연수인 것은 ⟨2/9⟩ × 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#5','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'sa','auto','한 변의 길이가 ⟨3/8⟩ cm인 정삼각형의 둘레를 구해 기약분수(가분수)로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C2","difficulty":3,"kind":"sa","stem":"한 변의 길이가 ⟨3/8⟩ cm인 정삼각형의 둘레를 구해 기약분수(가분수)로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정삼각형은 3변의 길이가 모두 같아요.","둘레는 ⟨3/8⟩ × 3 = ⟨9/8⟩예요.","그래서 분자는 9예요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"한 변의 길이가 ⟨2/7⟩ cm인 정사각형의 둘레를 구해 기약분수(가분수)로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정사각형은 4변의 길이가 모두 같아요.","둘레는 ⟨2/7⟩ × 4 = ⟨8/7⟩이에요.","그래서 분자는 8이에요."]},{"stem":"한 변의 길이가 ⟨5/9⟩ cm인 정육각형의 둘레를 구해 기약분수(가분수)로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["정육각형은 6변의 길이가 모두 같아요.","둘레는 ⟨5/9⟩ × 6 = ⟨30/9⟩ = ⟨10/3⟩이에요.","그래서 분자는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#6','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'mc','auto','⟨3/4⟩ × 2를 계산할 때 약분은 언제 해야 하나요?',ARRAY['M5-2-u2-X13','M5-2-u2-X12']::text[],true,'{"seq":6,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"⟨3/4⟩ × 2를 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩이에요.","곱하기 전에 4와 2를 2로 약분해도 ⟨3/2⟩ × 1 = ⟨3/2⟩이에요.","언제 약분하든 값은 같아요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ × 4를 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨5/6⟩ × 4 = ⟨20/6⟩ = ⟨10/3⟩이에요.","곱하기 전에 6과 4를 2로 약분해도 ⟨5/3⟩ × 2 = ⟨10/3⟩이에요.","언제 약분하든 값은 같아요."]},{"stem":"⟨7/12⟩ × 8을 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩예요.","곱하기 전에 12와 8을 4로 약분해도 ⟨7/3⟩ × 2 = ⟨14/3⟩예요.","언제 약분하든 값은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#7','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'ox','auto','⟨2/5⟩ × 4를 계산할 때는 분모에도 4를 곱해요.',ARRAY['M5-2-u2-X01']::text[],true,'{"seq":7,"concept":"M5-2-u2-C2","difficulty":3,"kind":"ox","stem":"⟨2/5⟩ × 4를 계산할 때는 분모에도 4를 곱해요.","answer":"X","reason_options":[{"t":"한 칸의 크기 ⟨1/5⟩은 그대로이고 칸의 수만 늘어나 분모는 그대로이므로","correct":true},{"t":"분수에 곱할 때는 분모와 분자에 똑같이 곱하므로","mis":"M5-2-u2-X01"}],"mis":"M5-2-u2-X01","explanation":["⟨2/5⟩ × 4 = ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩예요.","분모가 같은 분수의 덧셈이라 분모는 그대로예요.","⟨2/5⟩ × 4 = ⟨8/5⟩ — 분모는 5예요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ × 3의 분자는 5예요.","answer":"X","reason_options":[{"t":"분자와 자연수를 곱해 2 × 3 = 6이므로","correct":true},{"t":"분자와 자연수를 더해 2 + 3 = 5이므로","mis":"M5-2-u2-X15"}],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","2 × 3 = 6이에요.","⟨2/9⟩ × 3 = ⟨6/9⟩ — 분자는 6이에요."]},{"stem":"⟨3/4⟩ × 2는 곱하기 전에 약분해도, 곱한 뒤에 약분해도 값이 같아요.","answer":"O","reason_options":[{"t":"곱하기 전·중·후 어느 때 약분해도 ⟨3/2⟩으로 같으므로","correct":true},{"t":"곱한 뒤에만 약분할 수 있으므로","mis":"M5-2-u2-X13"}],"explanation":["곱한 뒤 약분하면 ⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩이에요.","곱하기 전에 4와 2를 약분해도 ⟨3/2⟩ × 1 = ⟨3/2⟩이에요.","약분은 언제 해도 값이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#8','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'sa','auto','⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C2","difficulty":4,"kind":"sa","stem":"⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로이고 분자만 3에서 15로 바뀌었어요.","분자와 □를 곱해 15가 되어야 해요 — 3 × 5 = 15.","그래서 □는 5예요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨2/9⟩ × □ = ⟨8/9⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로이고 분자만 2에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 2 × 4 = 8.","그래서 □는 4예요."]},{"stem":"⟨4/11⟩ × □ = ⟨8/11⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모는 그대로이고 분자만 4에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 4 × 2 = 8.","그래서 □는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#9','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'match','auto','곱셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":4,"kind":"match","stem":"곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨1/9⟩ × 5","r":"⟨5/9⟩"},{"l":"⟨5/6⟩ × 7","r":"⟨5 5/6⟩"},{"l":"⟨7/12⟩ × 8","r":"⟨4 2/3⟩"}],"mis":"M5-2-u2-X01","explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/9⟩ × 5 = ⟨5/9⟩, ⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩, ⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","분모에 자연수를 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨2/5⟩ × 4","r":"⟨1 3/5⟩"},{"l":"⟨1/4⟩ × 3","r":"⟨3/4⟩"},{"l":"⟨3/10⟩ × 3","r":"⟨9/10⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩, ⟨1/4⟩ × 3 = ⟨3/4⟩, ⟨3/10⟩ × 3 = ⟨9/10⟩예요.","분모에 자연수를 곱하지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨4/7⟩ × 3","r":"⟨1 5/7⟩"},{"l":"⟨2/9⟩ × 6","r":"⟨1 1/3⟩"},{"l":"⟨5/8⟩ × 2","r":"⟨1 1/4⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 3 = ⟨12/7⟩ = ⟨1 5/7⟩, ⟨2/9⟩ × 6 = ⟨12/9⟩ = ⟨4/3⟩ = ⟨1 1/3⟩, ⟨5/8⟩ × 2 = ⟨10/8⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","분모에 자연수를 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L02_challenge#10','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'essay','teacher','⟨2/5⟩ × 4를 계산할 때 분모 5는 그대로 두고 분자에만 4를 곱하는 까닭을 수직선(또는 덧셈)을 이용해 설명하고, 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C2","difficulty":4,"kind":"essay","stem":"⟨2/5⟩ × 4를 계산할 때 분모 5는 그대로 두고 분자에만 4를 곱하는 까닭을 수직선(또는 덧셈)을 이용해 설명하고, 계산해 보세요.","answer_guide":{"answer":"예: ⟨2/5⟩ × 4는 ⟨2/5⟩를 4번 더한 것이다. 수직선의 0에서 ⟨2/5⟩씩 4번 뛰어 세면 ⟨1/5⟩짜리 칸이 2 × 4 = 8개가 된다. 한 칸의 크기 ⟨1/5⟩은 그대로이고 칸의 수만 늘어났으므로 분모는 그대로 두고 분자만 곱한다. ⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이다.","scoring_points":["같은 수를 4번 더한 것(뛰어 세기)으로 설명했는가","한 칸의 크기는 그대로라 분모가 그대로임을 밝혔는가","⟨8/5⟩(= ⟨1 3/5⟩)을 구했는가"]},"explanation":["⟨2/5⟩ × 4 = ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩예요.","⟨1/5⟩ 칸이 8개 — 칸 크기는 그대로예요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#1','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','⟨1 1/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":1,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/4⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨1/4⟩을 더하면 분자는 4 + 1 = 5예요.","⟨1 1/4⟩ = ⟨5/4⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1 3/5⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨4/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨5/5⟩예요 — 1 × 5 = 5.","여기에 ⟨3/5⟩을 더하면 분자는 5 + 3 = 8이에요.","⟨1 3/5⟩ = ⟨8/5⟩이에요."]},{"stem":"⟨2 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/3⟩","correct":true},{"t":"⟨3/7⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 2는 ⟨6/3⟩이에요 — 2 × 3 = 6.","여기에 ⟨1/3⟩을 더하면 분자는 6 + 1 = 7이에요.","⟨2 1/3⟩ = ⟨7/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#2','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','⟨1 1/4⟩ × 3을 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":2,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩ × 3을 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 3 + ⟨1/4⟩ × 3","correct":true},{"t":"1 × 3 + ⟨1/4⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨1/4⟩ × 3","mis":"M5-2-u2-X05"},{"t":"1 × ⟨1/4⟩ × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/4⟩은 1 + ⟨1/4⟩이에요.","자연수 부분과 분수 부분에 모두 3을 곱해 더해요.","1 × 3 + ⟨1/4⟩ × 3 = 3 + ⟨3/4⟩ = ⟨3 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 5 + ⟨1/3⟩ × 5","correct":true},{"t":"2 × 5 + ⟨1/3⟩","mis":"M5-2-u2-X05"},{"t":"2 + ⟨1/3⟩ × 5","mis":"M5-2-u2-X05"},{"t":"2 × ⟨1/3⟩ × 5","mis":"M5-2-u2-X15"}],"explanation":["⟨2 1/3⟩은 2 + ⟨1/3⟩이에요.","자연수 부분과 분수 부분에 모두 5를 곱해 더해요.","2 × 5 + ⟨1/3⟩ × 5 = 10 + ⟨1 2/3⟩ = ⟨11 2/3⟩예요."]},{"stem":"⟨1 3/5⟩ × 2를 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨3/5⟩ × 2","correct":true},{"t":"1 × 2 + ⟨3/5⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨3/5⟩ × 2","mis":"M5-2-u2-X05"},{"t":"1 × ⟨3/5⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/5⟩은 1 + ⟨3/5⟩이에요.","자연수 부분과 분수 부분에 모두 2를 곱해 더해요.","1 × 2 + ⟨3/5⟩ × 2 = 2 + ⟨1 1/5⟩ = ⟨3 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#3','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'ox','auto','⟨1 1/4⟩ × 3은 ⟨1 1/4⟩ + ⟨1 1/4⟩ + ⟨1 1/4⟩과 같아요.',ARRAY['M5-2-u2-X15']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"ox","stem":"⟨1 1/4⟩ × 3은 ⟨1 1/4⟩ + ⟨1 1/4⟩ + ⟨1 1/4⟩과 같아요.","answer":"O","reason_options":[{"t":"같은 수를 세 번 더한 것을 곱셈으로 적은 것이므로","correct":true},{"t":"대분수는 곱셈으로 적을 수 없으므로","mis":"M5-2-u2-X15"}],"mis":"M5-2-u2-X15","explanation":["⟨1 1/4⟩씩 세 번 뛰어 세면 ⟨1 1/4⟩ → ⟨2 2/4⟩ → ⟨3 3/4⟩이에요.","⟨1 1/4⟩ × 3 = ⟨3 3/4⟩이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"⟨1 3/5⟩을 가분수로 나타내면 ⟨8/5⟩이에요.","answer":"O","reason_options":[{"t":"1 × 5 + 3 = 8이므로","correct":true},{"t":"1 + 3 + 5 = 9이므로","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨5/5⟩예요.","⟨5/5⟩ + ⟨3/5⟩ = ⟨8/5⟩이에요.","그래서 맞아요."]},{"stem":"대분수에 자연수를 곱하는 방법은 가르기와 가분수로 고치기 두 가지가 있고, 답은 같아요.","answer":"O","reason_options":[{"t":"같은 수를 다르게 계산했을 뿐이므로","correct":true},{"t":"가분수로 고치면 답이 더 커지므로","mis":"M5-2-u2-X12"}],"explanation":["가르기: 2 × 5 + ⟨1/3⟩ × 5 = ⟨11 2/3⟩예요.","가분수: ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","두 방법 모두 ⟨11 2/3⟩ — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#4','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":4,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨1 1/4⟩ L씩 3병이니 ⟨1 1/4⟩ × 3이에요.","⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","모두 ⟨3 3/4⟩ L예요."],"variant_rule":{"alt":[{"stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 2/5⟩ L짜리 병에 가득 담았더니 2병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨1 2/5⟩ L씩 2병이니 ⟨1 2/5⟩ × 2예요.","⟨1 2/5⟩ × 2 = ⟨7/5⟩ × 2 = ⟨14/5⟩ = ⟨2 4/5⟩예요.","모두 ⟨2 4/5⟩ L예요."]},{"stem":"사과 따기 체험에서 만든 사과주스를 ⟨2 1/3⟩ L짜리 병에 가득 담았더니 2병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨4 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X05"},{"t":"2","mis":"M5-2-u2-X04"}],"explanation":["⟨2 1/3⟩ L씩 2병이니 ⟨2 1/3⟩ × 2예요.","⟨2 1/3⟩ × 2 = ⟨7/3⟩ × 2 = ⟨14/3⟩ = ⟨4 2/3⟩예요.","모두 ⟨4 2/3⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#5','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'mc','auto','⟨1 3/5⟩ × 2를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":5,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨1 3/5⟩ × 2를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/5⟩","correct":true},{"t":"⟨2 3/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 3/5⟩ = ⟨8/5⟩이에요.","⟨1 3/5⟩ × 2 = ⟨8/5⟩ × 2 = ⟨16/5⟩ = ⟨3 1/5⟩이에요.","자연수 부분으로 갈라도 1 × 2 + ⟨3/5⟩ × 2 = ⟨3 1/5⟩로 같아요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨11 2/3⟩","correct":true},{"t":"⟨10 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 2/3⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨2 1/3⟩ × 5 = ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","자연수 부분으로 갈라도 2 × 5 + ⟨1/3⟩ × 5 = ⟨11 2/3⟩로 같아요."]},{"stem":"⟨3 2/9⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨19 1/3⟩","correct":true},{"t":"⟨18 2/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨3 2/9⟩ = ⟨29/9⟩예요.","⟨3 2/9⟩ × 6 = ⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩ = ⟨19 1/3⟩이에요.","자연수 부분으로 갈라도 3 × 6 + ⟨2/9⟩ × 6 = ⟨19 1/3⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#6','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'sa','auto','⟨1 1/4⟩ × 3을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C3","difficulty":2,"kind":"sa","stem":"⟨1 1/4⟩ × 3을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 대분수를 가분수로 고쳐요 — ⟨1 1/4⟩ = ⟨5/4⟩.","⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 대분수를 가분수로 고쳐요 — ⟨2 1/3⟩ = ⟨7/3⟩.","⟨2 1/3⟩ × 5 = ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","그래서 분자은 2예요."]},{"stem":"⟨1 3/5⟩ × 2를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 대분수를 가분수로 고쳐요 — ⟨1 3/5⟩ = ⟨8/5⟩.","⟨1 3/5⟩ × 2 = ⟨8/5⟩ × 2 = ⟨16/5⟩ = ⟨3 1/5⟩이에요.","그래서 자연수 부분은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#7','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'sa','auto','⟨1 3/5⟩ × 2를 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C3","difficulty":2,"kind":"sa","stem":"⟨1 3/5⟩ × 2를 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["⟨1 3/5⟩ = ⟨8/5⟩이에요 — 1 × 5 + 3 = 8.","⟨8/5⟩ × 2 = ⟨16/5⟩이에요.","그래서 분자는 16이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ × 3을 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩예요 — 2 × 4 + 1 = 9.","⟨9/4⟩ × 3 = ⟨27/4⟩이에요.","그래서 분자는 27이에요."]},{"stem":"⟨1 4/9⟩ × 2를 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["⟨1 4/9⟩ = ⟨13/9⟩이에요 — 1 × 9 + 4 = 13.","⟨13/9⟩ × 2 = ⟨26/9⟩이에요.","그래서 분자는 26이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#8','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'ox','auto','⟨1 1/4⟩ × 3 = ⟨3 1/4⟩이에요.',ARRAY['M5-2-u2-X05']::text[],true,'{"seq":8,"concept":"M5-2-u2-C3","difficulty":2,"kind":"ox","stem":"⟨1 1/4⟩ × 3 = ⟨3 1/4⟩이에요.","answer":"X","reason_options":[{"t":"분수 부분에도 3을 곱해 ⟨3 3/4⟩이 되므로","correct":true},{"t":"자연수 부분에만 곱하면 되므로","mis":"M5-2-u2-X05"}],"mis":"M5-2-u2-X05","explanation":["⟨1 1/4⟩ = 1 + ⟨1/4⟩이에요.","1 × 3 = 3, ⟨1/4⟩ × 3 = ⟨3/4⟩이에요.","⟨1 1/4⟩ × 3 = ⟨3 3/4⟩ — 분수 부분도 곱해야 해요."],"variant_rule":{"alt":[{"stem":"⟨3 2/9⟩ × 2는 ⟨2/9⟩ × 2 + 3과 같아요.","answer":"X","reason_options":[{"t":"자연수 부분 3에도 2를 곱해야 하므로","correct":true},{"t":"자연수 부분은 그대로 더하면 되므로","mis":"M5-2-u2-X05"}],"explanation":["⟨3 2/9⟩ = 3 + ⟨2/9⟩예요.","3 × 2 + ⟨2/9⟩ × 2 = 6 + ⟨4/9⟩ = ⟨6 4/9⟩예요.","자연수 부분에도 곱해야 해요."]},{"stem":"⟨1 1/6⟩ × 15를 계산할 때 6과 15를 먼저 약분해도 돼요.","answer":"X","reason_options":[{"t":"가분수로 고치기 전에 약분하면 자연수 부분 1이 빠지므로","correct":true},{"t":"분모와 자연수는 언제든 약분할 수 있으므로","mis":"M5-2-u2-X06"}],"explanation":["먼저 약분하면 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩로 틀려요.","가분수로 고치면 ⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","약분은 가분수로 고친 뒤에 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#9','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'sa','auto','한 변의 길이가 ⟨9 3/8⟩ m인 정사각형의 둘레를 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C3","difficulty":2,"kind":"sa","stem":"한 변의 길이가 ⟨9 3/8⟩ m인 정사각형의 둘레를 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["정사각형은 4변의 길이가 모두 같아요.","둘레는 ⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","그래서 답은 37이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"한 변의 길이가 ⟨2 1/4⟩ m인 정사각형의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정사각형은 4변의 길이가 모두 같아요.","둘레는 ⟨2 1/4⟩ × 4 = ⟨9/4⟩ × 4 = ⟨36/4⟩ = 9예요.","그래서 답은 9예요."]},{"stem":"한 변의 길이가 ⟨3 2/5⟩ m인 정삼각형의 둘레를 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["정삼각형은 3변의 길이가 모두 같아요.","둘레는 ⟨3 2/5⟩ × 3 = ⟨17/5⟩ × 3 = ⟨51/5⟩ = ⟨10 1/5⟩이에요.","그래서 답은 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_basic#10','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',3,'mc','auto','⟨1 1/4⟩ × 3과 ⟨1 1/2⟩ × 2 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X05']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"⟨1 1/4⟩ × 3과 ⟨1 1/2⟩ × 2 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1 1/4⟩ × 3","correct":true},{"t":"⟨1 1/2⟩ × 2","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X05"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","⟨1 1/2⟩ × 2 = ⟨3/2⟩ × 2 = ⟨6/2⟩ = 3이에요.","⟨3 3/4⟩ > 3이라 ⟨1 1/4⟩ × 3이 더 커요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 2와 ⟨1 3/4⟩ × 3 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ × 3","correct":true},{"t":"⟨2 1/3⟩ × 2","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X05"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × 2 = ⟨7/3⟩ × 2 = ⟨14/3⟩ = ⟨4 2/3⟩예요.","⟨1 3/4⟩ × 3 = ⟨7/4⟩ × 3 = ⟨21/4⟩ = ⟨5 1/4⟩이에요.","⟨4 2/3⟩ < ⟨5 1/4⟩이라 ⟨1 3/4⟩ × 3이 더 커요."]},{"stem":"⟨1 2/5⟩ × 4와 ⟨2 1/6⟩ × 3 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2 1/6⟩ × 3","correct":true},{"t":"⟨1 2/5⟩ × 4","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X05"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 2/5⟩ × 4 = ⟨7/5⟩ × 4 = ⟨28/5⟩ = ⟨5 3/5⟩이에요.","⟨2 1/6⟩ × 3 = ⟨13/6⟩ × 3 = ⟨39/6⟩ = ⟨13/2⟩ = ⟨6 1/2⟩이에요.","⟨5 3/5⟩ < ⟨6 1/2⟩이라 ⟨2 1/6⟩ × 3이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#1','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',2,'mc','auto','⟨2 1/3⟩ × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":1,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨2 1/3⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨9 1/3⟩","correct":true},{"t":"⟨8 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨2 1/3⟩ × 4 = ⟨7/3⟩ × 4 = ⟨28/3⟩ = ⟨9 1/3⟩이에요.","자연수 부분으로 갈라도 2 × 4 + ⟨1/3⟩ × 4 = ⟨9 1/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"⟨1 1/6⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨3 1/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X05"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/6⟩ = ⟨7/6⟩이에요.","⟨1 1/6⟩ × 3 = ⟨7/6⟩ × 3 = ⟨21/6⟩ = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","자연수 부분으로 갈라도 1 × 3 + ⟨1/6⟩ × 3 = ⟨3 1/2⟩로 같아요."]},{"stem":"⟨3 1/4⟩ × 2를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/2⟩","correct":true},{"t":"⟨6 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"2","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨3 1/4⟩ = ⟨13/4⟩이에요.","⟨3 1/4⟩ × 2 = ⟨13/4⟩ × 2 = ⟨26/4⟩ = ⟨13/2⟩ = ⟨6 1/2⟩이에요.","자연수 부분으로 갈라도 3 × 2 + ⟨1/4⟩ × 2 = ⟨6 1/2⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#2','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',2,'sa','auto','⟨3 2/9⟩ × 6을 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C3","difficulty":2,"kind":"sa","stem":"⟨3 2/9⟩ × 6을 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["⟨3 2/9⟩ = ⟨29/9⟩예요 — 3 × 9 + 2 = 29.","⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩이에요.","그래서 분자는 58이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨2 3/7⟩ × 2를 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["⟨2 3/7⟩ = ⟨17/7⟩이에요 — 2 × 7 + 3 = 17.","⟨17/7⟩ × 2 = ⟨34/7⟩예요.","그래서 분자는 34예요."]},{"stem":"⟨1 5/8⟩ × 4를 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["⟨1 5/8⟩ = ⟨13/8⟩이에요 — 1 × 8 + 5 = 13.","⟨13/8⟩ × 4 = ⟨52/8⟩ = ⟨13/2⟩이에요.","그래서 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#3','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'mc','auto','어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X02','M5-2-u2-X12']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 1/6⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 1/6⟩ = ⟨7/6⟩.","바르게 하면 ⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 친구가 ⟨1 3/8⟩ × 4를 「8과 4를 먼저 약분해 ⟨1 3/2⟩ × 1」로 고쳐 ⟨2 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 3/8⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 3/8⟩ = ⟨11/8⟩.","바르게 하면 ⟨1 3/8⟩ × 4 = ⟨11/8⟩ × 4 = ⟨44/8⟩ = ⟨11/2⟩ = ⟨5 1/2⟩이에요."]},{"stem":"어떤 친구가 ⟨2 1/4⟩ × 6을 「4와 6을 먼저 약분해 ⟨2 1/2⟩ × 3」으로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨2 1/4⟩에서 분모만 약분하면 자연수 부분 2가 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩.","바르게 하면 ⟨2 1/4⟩ × 6 = ⟨9/4⟩ × 6 = ⟨54/4⟩ = ⟨27/2⟩ = ⟨13 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#4','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'error','auto','⟨1 1/4⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X17']::text[],true,'{"seq":4,"concept":"M5-2-u2-C3","difficulty":3,"kind":"error","stem":"⟨1 1/4⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「1 × 3만 하면 되니까 ⟨3 1/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"도윤 — 「가분수로 고쳐 ⟨5/4⟩ × 3 = ⟨3 3/4⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「1 × 3 + ⟨1/4⟩ × 3 = ⟨3 3/4⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수 부분과 분수 부분이 함께 있는 수예요.","두 부분에 모두 3을 곱해야 해요 — ⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩.","수아는 자연수 부분에만 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「2 × 5만 하면 되니까 ⟨10 1/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"서연 — 「가분수로 고쳐 ⟨7/3⟩ × 5 = ⟨11 2/3⟩야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「2 × 5 + ⟨1/3⟩ × 5 = ⟨11 2/3⟩야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수 부분과 분수 부분이 함께 있는 수예요.","두 부분에 모두 5를 곱해야 해요 — ⟨2 1/3⟩ × 5 = ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩.","민준은 자연수 부분에만 곱해서 틀렸어요."]},{"stem":"⟨3 2/9⟩ × 6을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「3 × 6만 하면 되니까 ⟨18 2/9⟩야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"나린 — 「가분수로 고쳐 ⟨29/9⟩ × 6 = ⟨19 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「3 × 6 + ⟨2/9⟩ × 6 = ⟨19 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수 부분과 분수 부분이 함께 있는 수예요.","두 부분에 모두 6을 곱해야 해요 — ⟨3 2/9⟩ × 6 = ⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩ = ⟨19 1/3⟩.","가온은 자연수 부분에만 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#5','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'sa','auto','⟨3 2/9⟩ × 6을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C3","difficulty":3,"kind":"sa","stem":"⟨3 2/9⟩ × 6을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["먼저 대분수를 가분수로 고쳐요 — ⟨3 2/9⟩ = ⟨29/9⟩.","⟨3 2/9⟩ × 6 = ⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩ = ⟨19 1/3⟩이에요.","그래서 자연수 부분은 19예요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"⟨1 1/6⟩ × 15를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["먼저 대분수를 가분수로 고쳐요 — ⟨1 1/6⟩ = ⟨7/6⟩.","⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","그래서 자연수 부분은 17이에요."]},{"stem":"⟨2 3/7⟩ × 3을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 대분수를 가분수로 고쳐요 — ⟨2 3/7⟩ = ⟨17/7⟩.","⟨2 3/7⟩ × 3 = ⟨17/7⟩ × 3 = ⟨51/7⟩ = ⟨7 2/7⟩예요.","그래서 분자은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#6','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'sa','auto','한 변의 길이가 ⟨9 1/2⟩ m인 정사각형의 둘레는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C3","difficulty":3,"kind":"sa","stem":"한 변의 길이가 ⟨9 1/2⟩ m인 정사각형의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["정사각형은 4변의 길이가 모두 같아요.","둘레는 ⟨9 1/2⟩ × 4 = ⟨19/2⟩ × 4 = ⟨76/2⟩ = 38이에요.","그래서 답은 38이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"한 변의 길이가 ⟨4 2/3⟩ m인 정삼각형의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["정삼각형은 3변의 길이가 모두 같아요.","둘레는 ⟨4 2/3⟩ × 3 = ⟨14/3⟩ × 3 = ⟨42/3⟩ = 14예요.","그래서 답은 14예요."]},{"stem":"한 변의 길이가 ⟨2 3/5⟩ m인 정육각형의 둘레를 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["정육각형은 6변의 길이가 모두 같아요.","둘레는 ⟨2 3/5⟩ × 6 = ⟨13/5⟩ × 6 = ⟨78/5⟩ = ⟨15 3/5⟩이에요.","그래서 답은 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#7','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'ox','auto','⟨1 1/6⟩ × 15를 계산할 때 6과 15를 먼저 약분해도 돼요.',ARRAY['M5-2-u2-X06']::text[],true,'{"seq":7,"concept":"M5-2-u2-C3","difficulty":3,"kind":"ox","stem":"⟨1 1/6⟩ × 15를 계산할 때 6과 15를 먼저 약분해도 돼요.","answer":"X","reason_options":[{"t":"가분수로 고치기 전에 약분하면 자연수 부분 1이 빠지므로","correct":true},{"t":"분모와 자연수는 언제든 약분할 수 있으므로","mis":"M5-2-u2-X06"}],"mis":"M5-2-u2-X06","explanation":["먼저 약분하면 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩로 틀려요.","가분수로 고치면 ⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","약분은 가분수로 고친 뒤에 해요."],"variant_rule":{"alt":[{"stem":"⟨3 2/9⟩ × 2는 ⟨2/9⟩ × 2 + 3과 같아요.","answer":"X","reason_options":[{"t":"자연수 부분 3에도 2를 곱해야 하므로","correct":true},{"t":"자연수 부분은 그대로 더하면 되므로","mis":"M5-2-u2-X05"}],"explanation":["⟨3 2/9⟩ = 3 + ⟨2/9⟩예요.","3 × 2 + ⟨2/9⟩ × 2 = 6 + ⟨4/9⟩ = ⟨6 4/9⟩예요.","자연수 부분에도 곱해야 해요."]},{"stem":"⟨1 1/4⟩ × 3 = ⟨3 1/4⟩이에요.","answer":"X","reason_options":[{"t":"분수 부분에도 3을 곱해 ⟨3 3/4⟩이 되므로","correct":true},{"t":"자연수 부분에만 곱하면 되므로","mis":"M5-2-u2-X05"}],"explanation":["⟨1 1/4⟩ = 1 + ⟨1/4⟩이에요.","1 × 3 = 3, ⟨1/4⟩ × 3 = ⟨3/4⟩이에요.","⟨1 1/4⟩ × 3 = ⟨3 3/4⟩ — 분수 부분도 곱해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#8','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',4,'mc','auto','⟨2 1/3⟩ × 3과 ⟨1 2/3⟩ × 4 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X05']::text[],true,'{"seq":8,"concept":"M5-2-u2-C3","difficulty":4,"kind":"mc","stem":"⟨2 1/3⟩ × 3과 ⟨1 2/3⟩ × 4 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2 1/3⟩ × 3","correct":true},{"t":"⟨1 2/3⟩ × 4","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X05"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × 3 = ⟨7/3⟩ × 3 = ⟨21/3⟩ = 7이에요.","⟨1 2/3⟩ × 4 = ⟨5/3⟩ × 4 = ⟨20/3⟩ = ⟨6 2/3⟩예요.","7 > ⟨6 2/3⟩라 ⟨2 1/3⟩ × 3이 더 커요."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩ × 4와 ⟨2 2/3⟩ × 3 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2 2/3⟩ × 3","correct":true},{"t":"⟨1 5/6⟩ × 4","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X05"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 5/6⟩ × 4 = ⟨11/6⟩ × 4 = ⟨44/6⟩ = ⟨22/3⟩ = ⟨7 1/3⟩이에요.","⟨2 2/3⟩ × 3 = ⟨8/3⟩ × 3 = ⟨24/3⟩ = 8이에요.","⟨7 1/3⟩ < 8이라 ⟨2 2/3⟩ × 3이 더 커요."]},{"stem":"⟨3 1/2⟩ × 2와 ⟨1 7/8⟩ × 4 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1 7/8⟩ × 4","correct":true},{"t":"⟨3 1/2⟩ × 2","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X05"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3 1/2⟩ × 2 = ⟨7/2⟩ × 2 = ⟨14/2⟩ = 7이에요.","⟨1 7/8⟩ × 4 = ⟨15/8⟩ × 4 = ⟨60/8⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","7 < ⟨7 1/2⟩이라 ⟨1 7/8⟩ × 4가 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#9','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',4,'mc','auto','사과 따기 체험에서 만든 사과주스를 ⟨1 3/4⟩ L짜리 병에 가득 담았더니 6병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":9,"concept":"M5-2-u2-C3","difficulty":4,"kind":"mc","stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 3/4⟩ L짜리 병에 가득 담았더니 6병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨10 1/2⟩","correct":true},{"t":"⟨6 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/2⟩","mis":"M5-2-u2-X05"},{"t":"6","mis":"M5-2-u2-X04"}],"explanation":["⟨1 3/4⟩ L씩 6병이니 ⟨1 3/4⟩ × 6이에요.","⟨1 3/4⟩ × 6 = ⟨7/4⟩ × 6 = ⟨42/4⟩ = ⟨21/2⟩ = ⟨10 1/2⟩이에요.","모두 ⟨10 1/2⟩ L예요."],"variant_rule":{"alt":[{"stem":"사과 따기 체험에서 만든 사과주스를 ⟨2 2/5⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨7 1/5⟩","correct":true},{"t":"⟨6 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨2 2/5⟩ L씩 3병이니 ⟨2 2/5⟩ × 3이에요.","⟨2 2/5⟩ × 3 = ⟨12/5⟩ × 3 = ⟨36/5⟩ = ⟨7 1/5⟩이에요.","모두 ⟨7 1/5⟩ L예요."]},{"stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 5/6⟩ L짜리 병에 가득 담았더니 4병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨7 1/3⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/3⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["⟨1 5/6⟩ L씩 4병이니 ⟨1 5/6⟩ × 4예요.","⟨1 5/6⟩ × 4 = ⟨11/6⟩ × 4 = ⟨44/6⟩ = ⟨22/3⟩ = ⟨7 1/3⟩이에요.","모두 ⟨7 1/3⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L03_challenge#10','math',5,2,'u2','L03','g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',4,'essay','teacher','어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩」로 계산했어요. 잘못된 까닭을 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":4,"kind":"essay","stem":"어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩」로 계산했어요. 잘못된 까닭을 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 대분수 ⟨1 1/6⟩을 가분수로 고치지 않고 분모 6과 15를 먼저 약분하면, 자연수 부분 1이 약분에서 빠져 버려 틀린다. ⟨1 1/6⟩을 먼저 가분수 ⟨7/6⟩로 고치면 ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이다.","scoring_points":["가분수로 고치기 전에 약분해 자연수 부분이 빠졌다고 썼는가","⟨1 1/6⟩ = ⟨7/6⟩로 고쳤는가","⟨17 1/2⟩(= ⟨35/2⟩)를 구했는가"]},"explanation":["먼저 약분하면 자연수 부분 1이 빠져요.","⟨1 1/6⟩ = ⟨7/6⟩이에요.","⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#1','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'sa','auto','6의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"6의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6을 똑같이 3으로 나누면 한 묶음은 6 ÷ 3 = 2예요.","그중의 1이니 2 × 1 = 2예요.","식으로는 6 × ⟨1/3⟩ = ⟨6/3⟩ = 2예요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"12의 ⟨1/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["12를 똑같이 4로 나누면 한 묶음은 12 ÷ 4 = 3이에요.","그중의 1이니 3 × 1 = 3이에요.","식으로는 12 × ⟨1/4⟩ = ⟨12/4⟩ = 3이에요."]},{"stem":"10의 ⟨2/5⟩는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10을 똑같이 5로 나누면 한 묶음은 10 ÷ 5 = 2예요.","그중의 2니 2 × 2 = 4예요.","식으로는 10 × ⟨2/5⟩ = ⟨20/5⟩ = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#2','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'mc','auto','6 × ⟨2/3⟩와 같은 뜻인 것은 어느 것인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X15']::text[],true,'{"seq":2,"concept":"M5-2-u2-C4","difficulty":1,"kind":"mc","stem":"6 × ⟨2/3⟩와 같은 뜻인 것은 어느 것인가요?","options":[{"t":"6을 똑같이 3으로 나눈 것 중의 2","correct":true},{"t":"6을 똑같이 2로 나눈 것 중의 3","mis":"M5-2-u2-X07"},{"t":"6을 3번 더한 것","mis":"M5-2-u2-X07"},{"t":"6에서 ⟨2/3⟩를 뺀 것","mis":"M5-2-u2-X15"}],"explanation":["「6의 ⟨2/3⟩」와 「6 × ⟨2/3⟩」는 같은 말이에요.","전체 6을 분모 3만큼 똑같이 나눈 것 중의 분자 2만큼이에요.","6 × ⟨2/3⟩ = ⟨12/3⟩ = 4예요."],"variant_rule":{"alt":[{"stem":"8 × ⟨3/4⟩과 같은 뜻인 것은 어느 것인가요?","options":[{"t":"8을 똑같이 4로 나눈 것 중의 3","correct":true},{"t":"8을 똑같이 3으로 나눈 것 중의 4","mis":"M5-2-u2-X07"},{"t":"8을 4번 더한 것","mis":"M5-2-u2-X07"},{"t":"8에서 ⟨3/4⟩을 뺀 것","mis":"M5-2-u2-X15"}],"explanation":["「8의 ⟨3/4⟩」과 「8 × ⟨3/4⟩」은 같은 말이에요.","전체 8을 분모 4만큼 똑같이 나눈 것 중의 분자 3만큼이에요.","8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요."]},{"stem":"10 × ⟨3/5⟩과 같은 뜻인 것은 어느 것인가요?","options":[{"t":"10을 똑같이 5로 나눈 것 중의 3","correct":true},{"t":"10을 똑같이 3으로 나눈 것 중의 5","mis":"M5-2-u2-X07"},{"t":"10을 5번 더한 것","mis":"M5-2-u2-X07"},{"t":"10에서 ⟨3/5⟩을 뺀 것","mis":"M5-2-u2-X15"}],"explanation":["「10의 ⟨3/5⟩」과 「10 × ⟨3/5⟩」은 같은 말이에요.","전체 10을 분모 5만큼 똑같이 나눈 것 중의 분자 3만큼이에요.","10 × ⟨3/5⟩ = ⟨30/5⟩ = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#3','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'ox','auto','「6의 ⟨1/3⟩」과 「6 × ⟨1/3⟩」은 같은 말이에요.',ARRAY['M5-2-u2-X07']::text[],true,'{"seq":3,"concept":"M5-2-u2-C4","difficulty":1,"kind":"ox","stem":"「6의 ⟨1/3⟩」과 「6 × ⟨1/3⟩」은 같은 말이에요.","answer":"O","reason_options":[{"t":"둘 다 6을 똑같이 3으로 나눈 것 중의 1이므로","correct":true},{"t":"「의」는 덧셈을 뜻하므로","mis":"M5-2-u2-X07"}],"mis":"M5-2-u2-X07","explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","6 × ⟨1/3⟩ = 2예요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"12 × ⟨1/4⟩은 12를 4로 나눈 것과 같아요.","answer":"O","reason_options":[{"t":"12의 ⟨1/4⟩은 12를 똑같이 4로 나눈 것 중의 1이므로","correct":true},{"t":"12에 4를 곱한 것이므로","mis":"M5-2-u2-X07"}],"explanation":["12를 똑같이 4로 나누면 한 묶음은 3이에요.","12 × ⟨1/4⟩ = 3이에요.","12 ÷ 4 = 3 — 맞아요."]},{"stem":"⟨3/5⟩ × 2와 2 × ⟨3/5⟩의 계산 결과는 같아요.","answer":"O","reason_options":[{"t":"뜻은 달라도 둘 다 ⟨6/5⟩이므로","correct":true},{"t":"곱하는 순서가 바뀌면 결과도 바뀌므로","mis":"M5-2-u2-X15"}],"explanation":["⟨3/5⟩ × 2 = ⟨6/5⟩이에요.","2 × ⟨3/5⟩ = ⟨6/5⟩이에요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#4','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'sa','auto','6의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"6의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["6을 똑같이 3으로 나누면 한 묶음은 6 ÷ 3 = 2예요.","그중의 2니 2 × 2 = 4예요.","식으로는 6 × ⟨2/3⟩ = ⟨12/3⟩ = 4예요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"15의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["15를 똑같이 3으로 나누면 한 묶음은 15 ÷ 3 = 5예요.","그중의 2니 5 × 2 = 10이에요.","식으로는 15 × ⟨2/3⟩ = ⟨30/3⟩ = 10이에요."]},{"stem":"20의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["20을 똑같이 4로 나누면 한 묶음은 20 ÷ 4 = 5예요.","그중의 3이니 5 × 3 = 15예요.","식으로는 20 × ⟨3/4⟩ = ⟨60/4⟩ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#5','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','2 × ⟨3/5⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X07']::text[],true,'{"seq":5,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"2 × ⟨3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨6/10⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/10⟩","mis":"M5-2-u2-X02"},{"t":"6","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","2 × ⟨3/5⟩ = ⟨6/5⟩ = ⟨1 1/5⟩이에요.","2를 똑같이 5로 나눈 것 중의 3만큼이에요."],"variant_rule":{"alt":[{"stem":"4 × ⟨2/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/7⟩","correct":true},{"t":"⟨8/28⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/28⟩","mis":"M5-2-u2-X02"},{"t":"8","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","4 × ⟨2/7⟩ = ⟨8/7⟩ = ⟨1 1/7⟩이에요.","4를 똑같이 7로 나눈 것 중의 2만큼이에요."]},{"stem":"3 × ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 7/8⟩","correct":true},{"t":"⟨15/24⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/24⟩","mis":"M5-2-u2-X02"},{"t":"15","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨5/8⟩ = ⟨15/8⟩ = ⟨1 7/8⟩이에요.","3을 똑같이 8로 나눈 것 중의 5만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#6','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'sa','auto','1시간의 ⟨1/5⟩은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C4","difficulty":2,"kind":"sa","stem":"1시간의 ⟨1/5⟩은 몇 분인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1시간은 60분이에요.","60의 ⟨1/5⟩은 60 × ⟨1/5⟩ = ⟨60/5⟩ = 12예요.","그래서 12분이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"1시간의 ⟨3/4⟩은 몇 분인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["1시간은 60분이에요.","60의 ⟨3/4⟩은 60 × ⟨3/4⟩ = ⟨180/4⟩ = 45예요.","그래서 45분이에요."]},{"stem":"하루의 ⟨1/8⟩은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24의 ⟨1/8⟩은 24 × ⟨1/8⟩ = ⟨24/8⟩ = 3이에요.","그래서 3시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#7','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'sa','auto','7 × ⟨3/5⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":2,"kind":"sa","stem":"7 × ⟨3/5⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","7 × ⟨3/5⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","그래서 자연수 부분은 4예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"9 × ⟨5/6⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","그래서 자연수 부분은 7이에요."]},{"stem":"5 × ⟨3/4⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","5 × ⟨3/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#8','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','⟨3/5⟩ × 2와 2 × ⟨3/5⟩을 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15','M5-2-u2-X07']::text[],true,'{"seq":8,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"⟨3/5⟩ × 2와 2 × ⟨3/5⟩을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"뜻은 다르지만 계산 결과는 같다","correct":true},{"t":"뜻도 같고 계산 결과도 같다","mis":"M5-2-u2-X17"},{"t":"뜻이 다르니 계산 결과도 다르다","mis":"M5-2-u2-X15"},{"t":"2 × ⟨3/5⟩은 계산할 수 없다","mis":"M5-2-u2-X07"}],"explanation":["⟨3/5⟩ × 2는 ⟨3/5⟩을 2번 더한 것이에요.","2 × ⟨3/5⟩은 2의 ⟨3/5⟩만큼이에요.","뜻은 다르지만 둘 다 ⟨1 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩ × 3과 3 × ⟨2/7⟩를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"뜻은 다르지만 계산 결과는 같다","correct":true},{"t":"뜻도 같고 계산 결과도 같다","mis":"M5-2-u2-X17"},{"t":"뜻이 다르니 계산 결과도 다르다","mis":"M5-2-u2-X15"},{"t":"3 × ⟨2/7⟩는 계산할 수 없다","mis":"M5-2-u2-X07"}],"explanation":["⟨2/7⟩ × 3은 ⟨2/7⟩를 3번 더한 것이에요.","3 × ⟨2/7⟩는 3의 ⟨2/7⟩만큼이에요.","뜻은 다르지만 둘 다 ⟨6/7⟩이에요."]},{"stem":"⟨3/8⟩ × 4와 4 × ⟨3/8⟩을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"뜻은 다르지만 계산 결과는 같다","correct":true},{"t":"뜻도 같고 계산 결과도 같다","mis":"M5-2-u2-X17"},{"t":"뜻이 다르니 계산 결과도 다르다","mis":"M5-2-u2-X15"},{"t":"4 × ⟨3/8⟩은 계산할 수 없다","mis":"M5-2-u2-X07"}],"explanation":["⟨3/8⟩ × 4는 ⟨3/8⟩을 4번 더한 것이에요.","4 × ⟨3/8⟩은 4의 ⟨3/8⟩만큼이에요.","뜻은 다르지만 둘 다 ⟨1 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#9','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','흙 6 kg 가운데 누나는 ⟨1/3⟩을, 나는 ⟨2/3⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X07','M5-2-u2-X12']::text[],true,'{"seq":9,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"흙 6 kg 가운데 누나는 ⟨1/3⟩을, 나는 ⟨2/3⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"나, 4 kg","correct":true},{"t":"누나, 2 kg","mis":"M5-2-u2-X17"},{"t":"나, ⟨2/3⟩ kg","mis":"M5-2-u2-X07"},{"t":"나, 5 kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 6 × ⟨1/3⟩ = ⟨6/3⟩ = 2 kg이에요.","나: 6 × ⟨2/3⟩ = ⟨12/3⟩ = 4 kg이에요.","2 < 4라 내가 더 많이 썼어요."],"variant_rule":{"alt":[{"stem":"흙 8 kg 가운데 누나는 ⟨1/4⟩을, 나는 ⟨3/4⟩을 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"나, 6 kg","correct":true},{"t":"누나, 2 kg","mis":"M5-2-u2-X17"},{"t":"나, ⟨3/4⟩ kg","mis":"M5-2-u2-X07"},{"t":"나, 7 kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 8 × ⟨1/4⟩ = ⟨8/4⟩ = 2 kg이에요.","나: 8 × ⟨3/4⟩ = ⟨24/4⟩ = 6 kg이에요.","2 < 6이라 내가 더 많이 썼어요."]},{"stem":"흙 10 kg 가운데 누나는 ⟨2/5⟩를, 나는 ⟨1/5⟩을 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"누나, 4 kg","correct":true},{"t":"나, 2 kg","mis":"M5-2-u2-X17"},{"t":"누나, ⟨2/5⟩ kg","mis":"M5-2-u2-X07"},{"t":"누나, 5 kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 10 × ⟨2/5⟩ = ⟨20/5⟩ = 4 kg이에요.","나: 10 × ⟨1/5⟩ = ⟨10/5⟩ = 2 kg이에요.","4 > 2라 누나가 더 많이 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_basic#10','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',3,'mc','auto','들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X17','M5-2-u2-X01']::text[],true,'{"seq":10,"concept":"M5-2-u2-C4","difficulty":3,"kind":"mc","stem":"들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/12⟩","mis":"M5-2-u2-X17"},{"t":"⟨20/48⟩","mis":"M5-2-u2-X01"}],"explanation":["4 L의 ⟨5/12⟩만큼이니 4 × ⟨5/12⟩예요.","4 × ⟨5/12⟩ = ⟨20/12⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","항아리에는 간장 ⟨1 2/3⟩ L가 들어 있어요."],"variant_rule":{"alt":[{"stem":"들이가 3 L인 항아리에 간장이 ⟨7/10⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨2 1/10⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-2-u2-X07"},{"t":"⟨7/10⟩","mis":"M5-2-u2-X17"},{"t":"⟨21/30⟩","mis":"M5-2-u2-X01"}],"explanation":["3 L의 ⟨7/10⟩만큼이니 3 × ⟨7/10⟩이에요.","3 × ⟨7/10⟩ = ⟨21/10⟩ = ⟨2 1/10⟩이에요.","항아리에는 간장 ⟨2 1/10⟩ L가 들어 있어요."]},{"stem":"들이가 5 L인 항아리에 간장이 ⟨3/8⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨1 7/8⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨15/40⟩","mis":"M5-2-u2-X01"}],"explanation":["5 L의 ⟨3/8⟩만큼이니 5 × ⟨3/8⟩이에요.","5 × ⟨3/8⟩ = ⟨15/8⟩ = ⟨1 7/8⟩이에요.","항아리에는 간장 ⟨1 7/8⟩ L가 들어 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#1','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',2,'mc','auto','9 × ⟨5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X07']::text[],true,'{"seq":1,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"9 × ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨45/54⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/54⟩","mis":"M5-2-u2-X02"},{"t":"45","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","9를 똑같이 6으로 나눈 것 중의 5만큼이에요."],"variant_rule":{"alt":[{"stem":"7 × ⟨3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/5⟩","correct":true},{"t":"⟨21/35⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/35⟩","mis":"M5-2-u2-X02"},{"t":"21","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","7 × ⟨3/5⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","7을 똑같이 5로 나눈 것 중의 3만큼이에요."]},{"stem":"6 × ⟨4/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨24/54⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/54⟩","mis":"M5-2-u2-X02"},{"t":"24","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","6 × ⟨4/9⟩ = ⟨24/9⟩ = ⟨8/3⟩ = ⟨2 2/3⟩예요.","6을 똑같이 9로 나눈 것 중의 4만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#2','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',2,'sa','auto','지한이는 하루의 ⟨1/8⟩ 동안 책을 읽었어요. 몇 시간 동안 읽었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C4","difficulty":2,"kind":"sa","stem":"지한이는 하루의 ⟨1/8⟩ 동안 책을 읽었어요. 몇 시간 동안 읽었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24의 ⟨1/8⟩은 24 × ⟨1/8⟩ = ⟨24/8⟩ = 3이에요.","그래서 3시간이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"서연이는 하루의 ⟨1/6⟩ 동안 책을 읽었어요. 몇 시간 동안 읽었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["하루는 24시간이에요.","24의 ⟨1/6⟩은 24 × ⟨1/6⟩ = ⟨24/6⟩ = 4예요.","그래서 4시간이에요."]},{"stem":"도윤이는 하루의 ⟨1/4⟩ 동안 책을 읽었어요. 몇 시간 동안 읽었나요? 숫자로 쓰세요.","answer":["6"],"explanation":["하루는 24시간이에요.","24의 ⟨1/4⟩은 24 × ⟨1/4⟩ = ⟨24/4⟩ = 6이에요.","그래서 6시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#3','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'error','auto','6 × ⟨2/3⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C4","difficulty":3,"kind":"error","stem":"6 × ⟨2/3⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「6을 3으로 나누면 끝이니까 2야.」","correct":true,"mis_target":"M5-2-u2-X07"},{"t":"도윤 — 「6의 ⟨2/3⟩이니까 4야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「6 × ⟨2/3⟩ = ⟨12/3⟩ = 4야.」","mis":"M5-2-u2-X17"}],"explanation":["6을 3으로 나눈 2는 한 묶음이에요.","그중의 2묶음이니 2 × 2 = 4예요.","수아는 한 묶음에서 멈춰 틀렸어요."],"variant_rule":{"alt":[{"stem":"12 × ⟨3/4⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「12를 4로 나누면 끝이니까 3이야.」","correct":true,"mis_target":"M5-2-u2-X07"},{"t":"서연 — 「12의 ⟨3/4⟩이니까 9야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「12 × ⟨3/4⟩ = ⟨36/4⟩ = 9야.」","mis":"M5-2-u2-X17"}],"explanation":["12를 4로 나눈 3은 한 묶음이에요.","그중의 3묶음이니 3 × 3 = 9예요.","민준은 한 묶음에서 멈춰 틀렸어요."]},{"stem":"10 × ⟨3/5⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「10을 5로 나누면 끝이니까 2야.」","correct":true,"mis_target":"M5-2-u2-X07"},{"t":"나린 — 「10의 ⟨3/5⟩이니까 6이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「10 × ⟨3/5⟩ = ⟨30/5⟩ = 6이야.」","mis":"M5-2-u2-X17"}],"explanation":["10을 5로 나눈 2는 한 묶음이에요.","그중의 3묶음이니 2 × 3 = 6이에요.","가온은 한 묶음에서 멈춰 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#4','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'sa','auto','6 × ⟨□/3⟩ = 4일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":3,"kind":"sa","stem":"6 × ⟨□/3⟩ = 4일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["2"],"explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","2묶음이 4니 □ = 4 ÷ 2 = 2예요.","6 × ⟨2/3⟩ = 4 — 맞아요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"20 × ⟨□/4⟩ = 15일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["20을 똑같이 4로 나누면 한 묶음은 5예요.","3묶음이 15니 □ = 15 ÷ 5 = 3이에요.","20 × ⟨3/4⟩ = 15 — 맞아요."]},{"stem":"15 × ⟨□/5⟩ = 12일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["4"],"explanation":["15를 똑같이 5로 나누면 한 묶음은 3이에요.","4묶음이 12니 □ = 12 ÷ 3 = 4예요.","15 × ⟨4/5⟩ = 12 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#5','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'sa','auto','4 × ⟨5/12⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C4","difficulty":3,"kind":"sa","stem":"4 × ⟨5/12⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","4 × ⟨5/12⟩ = ⟨20/12⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","그래서 자연수 부분은 1이에요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"7 × ⟨5/8⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","7 × ⟨5/8⟩ = ⟨35/8⟩ = ⟨4 3/8⟩이에요.","그래서 자연수 부분은 4예요."]},{"stem":"9 × ⟨7/10⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨7/10⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","그래서 자연수 부분은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#6','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'ox','auto','6 × ⟨2/3⟩ = 12예요.',ARRAY['M5-2-u2-X07']::text[],true,'{"seq":6,"concept":"M5-2-u2-C4","difficulty":3,"kind":"ox","stem":"6 × ⟨2/3⟩ = 12예요.","answer":"X","reason_options":[{"t":"6을 3으로 나눈 것 중의 2라서 4이므로","correct":true},{"t":"6에 분자 2를 곱하면 되므로","mis":"M5-2-u2-X07"}],"mis":"M5-2-u2-X07","explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","두 묶음은 2 + 2 = 4예요.","6 × ⟨2/3⟩ = ⟨12/3⟩ = 4예요."],"variant_rule":{"alt":[{"stem":"2 × ⟨3/5⟩의 계산 결과는 2보다 작아요.","answer":"O","reason_options":[{"t":"1보다 작은 ⟨3/5⟩을 곱했으므로","correct":true},{"t":"곱셈은 언제나 커지므로","mis":"M5-2-u2-X08"}],"explanation":["2 × ⟨3/5⟩ = ⟨6/5⟩ = ⟨1 1/5⟩이에요.","⟨3/5⟩은 1보다 작아요.","그래서 2보다 작아요 — 맞아요."]},{"stem":"1시간의 ⟨1/5⟩은 12분이에요.","answer":"O","reason_options":[{"t":"60분의 ⟨1/5⟩은 60 ÷ 5 = 12분이므로","correct":true},{"t":"1시간은 100분이므로","mis":"M5-2-u2-X07"}],"explanation":["1시간은 60분이에요.","60 × ⟨1/5⟩ = 12예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#7','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'match','auto','곱셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":3,"kind":"match","stem":"곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"2 × ⟨3/5⟩","r":"⟨1 1/5⟩"},{"l":"6 × ⟨1/3⟩","r":"2"},{"l":"4 × ⟨3/8⟩","r":"⟨1 1/2⟩"}],"mis":"M5-2-u2-X07","explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","2 × ⟨3/5⟩ = ⟨6/5⟩ = ⟨1 1/5⟩, 6 × ⟨1/3⟩ = ⟨6/3⟩ = 2, 4 × ⟨3/8⟩ = ⟨12/8⟩ = ⟨3/2⟩ = ⟨1 1/2⟩이에요.","자연수를 분모에 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"3 × ⟨2/7⟩","r":"⟨6/7⟩"},{"l":"9 × ⟨2/3⟩","r":"6"},{"l":"5 × ⟨1/2⟩","r":"⟨2 1/2⟩"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨2/7⟩ = ⟨6/7⟩, 9 × ⟨2/3⟩ = ⟨18/3⟩ = 6, 5 × ⟨1/2⟩ = ⟨5/2⟩ = ⟨2 1/2⟩이에요.","자연수를 분모에 곱하지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"8 × ⟨3/4⟩","r":"6"},{"l":"2 × ⟨4/9⟩","r":"⟨8/9⟩"},{"l":"7 × ⟨1/4⟩","r":"⟨1 3/4⟩"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","8 × ⟨3/4⟩ = ⟨24/4⟩ = 6, 2 × ⟨4/9⟩ = ⟨8/9⟩, 7 × ⟨1/4⟩ = ⟨7/4⟩ = ⟨1 3/4⟩이에요.","자연수를 분모에 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#8','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',4,'mc','auto','들이가 6 L인 항아리에 식초가 ⟨5/8⟩만큼 들어 있어요. 항아리에 든 식초는 몇 L인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X17','M5-2-u2-X01']::text[],true,'{"seq":8,"concept":"M5-2-u2-C4","difficulty":4,"kind":"mc","stem":"들이가 6 L인 항아리에 식초가 ⟨5/8⟩만큼 들어 있어요. 항아리에 든 식초는 몇 L인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨30/48⟩","mis":"M5-2-u2-X01"}],"explanation":["6 L의 ⟨5/8⟩만큼이니 6 × ⟨5/8⟩예요.","6 × ⟨5/8⟩ = ⟨30/8⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","항아리에는 식초 ⟨3 3/4⟩ L가 들어 있어요."],"variant_rule":{"alt":[{"stem":"들이가 4 L인 항아리에 간장이 ⟨7/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨7/12⟩","mis":"M5-2-u2-X17"},{"t":"⟨28/48⟩","mis":"M5-2-u2-X01"}],"explanation":["4 L의 ⟨7/12⟩만큼이니 4 × ⟨7/12⟩이에요.","4 × ⟨7/12⟩ = ⟨28/12⟩ = ⟨7/3⟩ = ⟨2 1/3⟩이에요.","항아리에는 간장 ⟨2 1/3⟩ L가 들어 있어요."]},{"stem":"들이가 9 L인 항아리에 참기름이 ⟨2/15⟩만큼 들어 있어요. 항아리에 든 참기름은 몇 L인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-2-u2-X07"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X17"},{"t":"⟨18/135⟩","mis":"M5-2-u2-X01"}],"explanation":["9 L의 ⟨2/15⟩만큼이니 9 × ⟨2/15⟩예요.","9 × ⟨2/15⟩ = ⟨18/15⟩ = ⟨6/5⟩ = ⟨1 1/5⟩이에요.","항아리에는 참기름 ⟨1 1/5⟩ L가 들어 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#9','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',4,'mc','auto','흙 9 kg 가운데 누나는 ⟨2/3⟩를, 나는 ⟨5/6⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X07','M5-2-u2-X12']::text[],true,'{"seq":9,"concept":"M5-2-u2-C4","difficulty":4,"kind":"mc","stem":"흙 9 kg 가운데 누나는 ⟨2/3⟩를, 나는 ⟨5/6⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"나, ⟨7 1/2⟩ kg","correct":true},{"t":"누나, 6 kg","mis":"M5-2-u2-X17"},{"t":"나, ⟨5/6⟩ kg","mis":"M5-2-u2-X07"},{"t":"나, ⟨8 1/2⟩ kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 9 × ⟨2/3⟩ = ⟨18/3⟩ = 6 kg이에요.","나: 9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩ kg이에요.","6 < ⟨7 1/2⟩이라 내가 더 많이 썼어요."],"variant_rule":{"alt":[{"stem":"흙 12 kg 가운데 누나는 ⟨3/4⟩을, 나는 ⟨5/8⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"누나, 9 kg","correct":true},{"t":"나, ⟨7 1/2⟩ kg","mis":"M5-2-u2-X17"},{"t":"누나, ⟨3/4⟩ kg","mis":"M5-2-u2-X07"},{"t":"누나, 10 kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 12 × ⟨3/4⟩ = ⟨36/4⟩ = 9 kg이에요.","나: 12 × ⟨5/8⟩ = ⟨60/8⟩ = ⟨15/2⟩ = ⟨7 1/2⟩ kg이에요.","9 > ⟨7 1/2⟩이라 누나가 더 많이 썼어요."]},{"stem":"흙 15 kg 가운데 누나는 ⟨2/5⟩를, 나는 ⟨7/10⟩을 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"나, ⟨10 1/2⟩ kg","correct":true},{"t":"누나, 6 kg","mis":"M5-2-u2-X17"},{"t":"나, ⟨7/10⟩ kg","mis":"M5-2-u2-X07"},{"t":"나, ⟨11 1/2⟩ kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 15 × ⟨2/5⟩ = ⟨30/5⟩ = 6 kg이에요.","나: 15 × ⟨7/10⟩ = ⟨105/10⟩ = ⟨21/2⟩ = ⟨10 1/2⟩ kg이에요.","6 < ⟨10 1/2⟩이라 내가 더 많이 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L04_challenge#10','math',5,2,'u2','L04','g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',4,'essay','teacher','흙 6 kg 가운데 누나는 ⟨1/3⟩을, 나는 ⟨2/3⟩를 썼어요. 두 사람이 쓴 흙의 양을 각각 「전체를 똑같이 나눈 것 중의 몇」으로 설명하며 구하고, ⟨3/5⟩ × 2와 2 × ⟨3/5⟩의 뜻이 어떻게 다른지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C4","difficulty":4,"kind":"essay","stem":"흙 6 kg 가운데 누나는 ⟨1/3⟩을, 나는 ⟨2/3⟩를 썼어요. 두 사람이 쓴 흙의 양을 각각 「전체를 똑같이 나눈 것 중의 몇」으로 설명하며 구하고, ⟨3/5⟩ × 2와 2 × ⟨3/5⟩의 뜻이 어떻게 다른지도 쓰세요.","answer_guide":{"answer":"예: 6을 똑같이 3으로 나누면 한 묶음은 2이다. 누나는 그중의 1이라 6 × ⟨1/3⟩ = 2 kg, 나는 그중의 2라 6 × ⟨2/3⟩ = 4 kg을 썼다. ⟨3/5⟩ × 2는 ⟨3/5⟩을 두 번 더한 것이고, 2 × ⟨3/5⟩은 2의 ⟨3/5⟩만큼이라 뜻은 다르지만 둘 다 ⟨6/5⟩으로 계산 결과는 같다.","scoring_points":["6을 3으로 나눈 한 묶음 2를 찾았는가","누나 2 kg, 나 4 kg을 구했는가","두 곱셈의 뜻이 다르지만 결과는 같다고 썼는가"]},"explanation":["6을 3으로 나누면 한 묶음은 2예요.","누나 2 kg, 나 4 kg이에요.","⟨3/5⟩ × 2와 2 × ⟨3/5⟩은 뜻은 달라도 ⟨6/5⟩으로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#1','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','2 × ⟨1 2/5⟩를 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"2 × ⟨1 2/5⟩를 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 1 + 2 × ⟨2/5⟩","correct":true},{"t":"2 × 1 + ⟨2/5⟩","mis":"M5-2-u2-X05"},{"t":"1 + 2 × ⟨2/5⟩","mis":"M5-2-u2-X05"},{"t":"2 × 1 × ⟨2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 2/5⟩ = 1 + ⟨2/5⟩예요.","2를 두 부분에 모두 곱해 더해요.","2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩ = ⟨2 4/5⟩예요."],"variant_rule":{"alt":[{"stem":"3 × ⟨2 1/2⟩을 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 × 2 + 3 × ⟨1/2⟩","correct":true},{"t":"3 × 2 + ⟨1/2⟩","mis":"M5-2-u2-X05"},{"t":"2 + 3 × ⟨1/2⟩","mis":"M5-2-u2-X05"},{"t":"3 × 2 × ⟨1/2⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨2 1/2⟩ = 2 + ⟨1/2⟩이에요.","3을 두 부분에 모두 곱해 더해요.","3 × 2 + 3 × ⟨1/2⟩ = 6 + ⟨1 1/2⟩ = ⟨7 1/2⟩이에요."]},{"stem":"4 × ⟨1 1/3⟩을 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 × 1 + 4 × ⟨1/3⟩","correct":true},{"t":"4 × 1 + ⟨1/3⟩","mis":"M5-2-u2-X05"},{"t":"1 + 4 × ⟨1/3⟩","mis":"M5-2-u2-X05"},{"t":"4 × 1 × ⟨1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/3⟩ = 1 + ⟨1/3⟩이에요.","4를 두 부분에 모두 곱해 더해요.","4 × 1 + 4 × ⟨1/3⟩ = 4 + ⟨1 1/3⟩ = ⟨5 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#2','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','2 × ⟨1 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"2 × ⟨1 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/5⟩ = ⟨7/5⟩이에요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩예요.","둘로 갈라도 2 × 1 + 2 × ⟨2/5⟩ = ⟨2 4/5⟩로 같아요."],"variant_rule":{"alt":[{"stem":"3 × ⟨2 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨6 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/2⟩ = ⟨5/2⟩예요.","3 × ⟨2 1/2⟩ = 3 × ⟨5/2⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","둘로 갈라도 3 × 2 + 3 × ⟨1/2⟩ = ⟨7 1/2⟩로 같아요."]},{"stem":"4 × ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 1/3⟩","correct":true},{"t":"⟨4 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/3⟩ = ⟨4/3⟩예요.","4 × ⟨1 1/3⟩ = 4 × ⟨4/3⟩ = ⟨16/3⟩ = ⟨5 1/3⟩이에요.","둘로 갈라도 4 × 1 + 4 × ⟨1/3⟩ = ⟨5 1/3⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#3','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'ox','auto','5 × 1은 5와 같아요.',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":3,"concept":"M5-2-u2-C5","difficulty":1,"kind":"ox","stem":"5 × 1은 5와 같아요.","answer":"O","reason_options":[{"t":"1을 곱하면 그대로이므로","correct":true},{"t":"곱하면 반드시 커져야 하므로","mis":"M5-2-u2-X08"}],"mis":"M5-2-u2-X08","explanation":["어떤 수에 1을 곱하면 그 수 그대로예요.","5 × 1 = 5예요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"5 × ⟨1 1/9⟩은 5보다 커요.","answer":"O","reason_options":[{"t":"1보다 큰 ⟨1 1/9⟩을 곱했으므로","correct":true},{"t":"대분수를 곱하면 늘 작아지므로","mis":"M5-2-u2-X08"}],"explanation":["⟨1 1/9⟩은 1보다 커요.","5 × ⟨1 1/9⟩ = ⟨50/9⟩ = ⟨5 5/9⟩예요.","그래서 5보다 커요 — 맞아요."]},{"stem":"8 × ⟨3/4⟩의 계산 결과는 8보다 작아요.","answer":"O","reason_options":[{"t":"1보다 작은 ⟨3/4⟩을 곱했으므로","correct":true},{"t":"8에 3을 곱하므로","mis":"M5-2-u2-X08"}],"explanation":["8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요.","6은 8보다 작아요.","곱셈은 곱하는 수만큼을 구하는 계산이에요 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#4','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','5 × ⟨2/3⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":4,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"5 × ⟨2/3⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"5보다 작다","correct":true},{"t":"5보다 크다","mis":"M5-2-u2-X08"},{"t":"5와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨2/3⟩가 1보다 작아요.","5 × ⟨2/3⟩ = ⟨3 1/3⟩이에요.","그래서 「5보다 작다」예요."],"variant_rule":{"alt":[{"stem":"6 × ⟨1 1/4⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"6보다 크다","correct":true},{"t":"6보다 작다","mis":"M5-2-u2-X08"},{"t":"6과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 1/4⟩이 1보다 커요.","6 × ⟨1 1/4⟩ = ⟨7 1/2⟩이에요.","그래서 「6보다 크다」예요."]},{"stem":"7 × ⟨5/6⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"7보다 작다","correct":true},{"t":"7보다 크다","mis":"M5-2-u2-X08"},{"t":"7과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨5/6⟩가 1보다 작아요.","7 × ⟨5/6⟩ = ⟨5 5/6⟩예요.","그래서 「7보다 작다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#5','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'sa','auto','3 × ⟨2 1/2⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":2,"kind":"sa","stem":"3 × ⟨2 1/2⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨2 1/2⟩ = ⟨5/2⟩예요.","3 × ⟨2 1/2⟩ = 3 × ⟨5/2⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","그래서 자연수 부분은 7이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"4 × ⟨3 2/7⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["⟨3 2/7⟩ = ⟨23/7⟩이에요.","4 × ⟨3 2/7⟩ = 4 × ⟨23/7⟩ = ⟨92/7⟩ = ⟨13 1/7⟩이에요.","그래서 자연수 부분은 13이에요."]},{"stem":"8 × ⟨1 5/6⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨1 5/6⟩ = ⟨11/6⟩이에요.","8 × ⟨1 5/6⟩ = 8 × ⟨11/6⟩ = ⟨88/6⟩ = ⟨44/3⟩ = ⟨14 2/3⟩예요.","그래서 자연수 부분은 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#6','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'mc','auto','가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":6,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨6 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 2 × ⟨1 2/5⟩예요.","세로를 1과 ⟨2/5⟩로 갈라 더하면 2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩예요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ — ⟨2 4/5⟩ m²예요."],"variant_rule":{"alt":[{"stem":"가로가 3 m, 세로가 ⟨1 1/4⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨8 1/2⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 3 × ⟨1 1/4⟩이에요.","세로를 1과 ⟨1/4⟩로 갈라 더하면 3 × 1 + 3 × ⟨1/4⟩ = 3 + ⟨3/4⟩이에요.","3 × ⟨1 1/4⟩ = 3 × ⟨5/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩ — ⟨3 3/4⟩ m²예요."]},{"stem":"가로가 4 m, 세로가 ⟨2 1/3⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨9 1/3⟩","correct":true},{"t":"⟨8 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨12 2/3⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 4 × ⟨2 1/3⟩이에요.","세로를 2와 ⟨1/3⟩로 갈라 더하면 4 × 2 + 4 × ⟨1/3⟩ = 8 + ⟨1 1/3⟩이에요.","4 × ⟨2 1/3⟩ = 4 × ⟨7/3⟩ = ⟨28/3⟩ = ⟨9 1/3⟩ — ⟨9 1/3⟩ m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#7','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":7,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 6보다 큰 것은 어느 것인가요?","options":[{"t":"6 × ⟨1 1/5⟩","correct":true},{"t":"6 × ⟨3/4⟩","mis":"M5-2-u2-X08"},{"t":"6 × 1","mis":"M5-2-u2-X08"},{"t":"6 × ⟨7/8⟩","mis":"M5-2-u2-X08"}],"explanation":["6에 1보다 작은 수를 곱하면 6보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/5⟩뿐이에요.","그래서 6보다 큰 것은 6 × ⟨1 1/5⟩이에요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 4보다 작은 것은 어느 것인가요?","options":[{"t":"4 × ⟨9/10⟩","correct":true},{"t":"4 × ⟨1 2/3⟩","mis":"M5-2-u2-X08"},{"t":"4 × 1","mis":"M5-2-u2-X08"},{"t":"4 × ⟨1 1/6⟩","mis":"M5-2-u2-X08"}],"explanation":["4에 1보다 작은 수를 곱하면 4보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨9/10⟩뿐이에요.","그래서 4보다 작은 것은 4 × ⟨9/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#8','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'sa','auto','윤재는 쓰레기를 2 kg 주웠고, 수아는 그 ⟨1 3/4⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C5","difficulty":2,"kind":"sa","stem":"윤재는 쓰레기를 2 kg 주웠고, 수아는 그 ⟨1 3/4⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["2 kg의 ⟨1 3/4⟩배는 2 × ⟨1 3/4⟩이에요.","2 × ⟨1 3/4⟩ = 2 × ⟨7/4⟩ = ⟨14/4⟩ = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","그래서 답은 7이에요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"윤재는 쓰레기를 3 kg 주웠고, 수아는 그 ⟨1 1/2⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["3 kg의 ⟨1 1/2⟩배는 3 × ⟨1 1/2⟩이에요.","3 × ⟨1 1/2⟩ = 3 × ⟨3/2⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","그래서 답은 9예요."]},{"stem":"윤재는 쓰레기를 4 kg 주웠고, 수아는 그 ⟨1 2/5⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["4 kg의 ⟨1 2/5⟩배는 4 × ⟨1 2/5⟩예요.","4 × ⟨1 2/5⟩ = 4 × ⟨7/5⟩ = ⟨28/5⟩ = ⟨5 3/5⟩이에요.","그래서 답은 28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#9','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'ox','auto','곱셈을 하면 계산 결과는 언제나 처음 수보다 커져요.',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":9,"concept":"M5-2-u2-C5","difficulty":2,"kind":"ox","stem":"곱셈을 하면 계산 결과는 언제나 처음 수보다 커져요.","answer":"X","reason_options":[{"t":"1보다 작은 수를 곱하면 처음 수보다 작아지므로","correct":true},{"t":"곱셈은 늘 커지는 계산이므로","mis":"M5-2-u2-X08"}],"mis":"M5-2-u2-X08","explanation":["5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","5보다 작아졌어요.","곱하는 수가 1보다 작으면 결과는 작아져요."],"variant_rule":{"alt":[{"stem":"5 × ⟨19/20⟩는 5보다 커요.","answer":"X","reason_options":[{"t":"⟨19/20⟩는 1보다 작아 5보다 작아지므로","correct":true},{"t":"분자 19가 크니 곱하면 커지므로","mis":"M5-2-u2-X08"}],"explanation":["⟨19/20⟩는 1에 아주 가깝지만 1보다 작아요.","5 × ⟨19/20⟩ = ⟨95/20⟩ = ⟨4 3/4⟩이에요.","5보다 작아요."]},{"stem":"2 × ⟨1 2/5⟩는 2 × 1과 2 × ⟨2/5⟩를 더한 것과 같아요.","answer":"O","reason_options":[{"t":"⟨1 2/5⟩ = 1 + ⟨2/5⟩이므로 둘로 갈라 곱해 더한 것이므로","correct":true},{"t":"대분수는 둘로 가를 수 없으므로","mis":"M5-2-u2-X05"}],"explanation":["⟨1 2/5⟩ = 1 + ⟨2/5⟩예요.","2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩ = ⟨2 4/5⟩예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_basic#10','math',5,2,'u2','L05','g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',3,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":10,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"6 × ⟨1 1/2⟩","correct":true},{"t":"6 × ⟨2/3⟩","mis":"M5-2-u2-X17"},{"t":"6 × ⟨1 3/8⟩","mis":"M5-2-u2-X17"},{"t":"6 × ⟨5/6⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 6에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수를 견주면 6 × ⟨2/3⟩ = 4, 6 × ⟨1 3/8⟩ = ⟨8 1/4⟩, 6 × ⟨5/6⟩ = 5, 6 × ⟨1 1/2⟩ = 9예요.","그래서 가장 큰 것은 6 × ⟨1 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"4 × ⟨1 1/3⟩","correct":true},{"t":"4 × ⟨3/4⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨7/8⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨1 1/5⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 4에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수를 견주면 4 × ⟨3/4⟩ = 3, 4 × ⟨1 1/3⟩ = ⟨5 1/3⟩, 4 × ⟨7/8⟩ = ⟨3 1/2⟩, 4 × ⟨1 1/5⟩ = ⟨4 4/5⟩예요.","그래서 가장 큰 것은 4 × ⟨1 1/3⟩이에요."]},{"stem":"이번에는 다른 보기예요. 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"8 × ⟨1 3/8⟩","correct":true},{"t":"8 × ⟨1/2⟩","mis":"M5-2-u2-X17"},{"t":"8 × ⟨1 1/4⟩","mis":"M5-2-u2-X17"},{"t":"8 × ⟨3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 8에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수를 견주면 8 × ⟨1/2⟩ = 4, 8 × ⟨1 1/4⟩ = 10, 8 × ⟨3/4⟩ = 6, 8 × ⟨1 3/8⟩ = 11이에요.","그래서 가장 큰 것은 8 × ⟨1 3/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#1','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',2,'mc','auto','8 × ⟨1 5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":1,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"8 × ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨14 2/3⟩","correct":true},{"t":"⟨8 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨7 2/3⟩","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 5/6⟩ = ⟨11/6⟩이에요.","8 × ⟨1 5/6⟩ = 8 × ⟨11/6⟩ = ⟨88/6⟩ = ⟨44/3⟩ = ⟨14 2/3⟩예요.","둘로 갈라도 8 × 1 + 8 × ⟨5/6⟩ = ⟨14 2/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"6 × ⟨1 3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/4⟩","correct":true},{"t":"⟨6 3/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"3","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 3/8⟩ = ⟨11/8⟩이에요.","6 × ⟨1 3/8⟩ = 6 × ⟨11/8⟩ = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","둘로 갈라도 6 × 1 + 6 × ⟨3/8⟩ = ⟨8 1/4⟩로 같아요."]},{"stem":"9 × ⟨2 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨19 1/2⟩","correct":true},{"t":"⟨18 1/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/6⟩ = ⟨13/6⟩이에요.","9 × ⟨2 1/6⟩ = 9 × ⟨13/6⟩ = ⟨117/6⟩ = ⟨39/2⟩ = ⟨19 1/2⟩이에요.","둘로 갈라도 9 × 2 + 9 × ⟨1/6⟩ = ⟨19 1/2⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#2','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',2,'sa','auto','윤재는 쓰레기를 6 kg 주웠고, 수아는 그 ⟨1 3/8⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":2,"kind":"sa","stem":"윤재는 쓰레기를 6 kg 주웠고, 수아는 그 ⟨1 3/8⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["6 kg의 ⟨1 3/8⟩배는 6 × ⟨1 3/8⟩이에요.","6 × ⟨1 3/8⟩ = 6 × ⟨11/8⟩ = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","그래서 답은 8이에요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"윤재는 쓰레기를 2 kg 주웠고, 수아는 그 ⟨1 3/4⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["2 kg의 ⟨1 3/4⟩배는 2 × ⟨1 3/4⟩이에요.","2 × ⟨1 3/4⟩ = 2 × ⟨7/4⟩ = ⟨14/4⟩ = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","그래서 답은 3이에요."]},{"stem":"윤재는 쓰레기를 5 kg 주웠고, 수아는 그 ⟨2 1/3⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["5 kg의 ⟨2 1/3⟩배는 5 × ⟨2 1/3⟩이에요.","5 × ⟨2 1/3⟩ = 5 × ⟨7/3⟩ = ⟨35/3⟩ = ⟨11 2/3⟩예요.","그래서 답은 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#3','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'error','auto','3 × ⟨2 1/2⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C5","difficulty":3,"kind":"error","stem":"3 × ⟨2 1/2⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「3 × 2 = 6이니까 ⟨6 1/2⟩이야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"도윤 — 「3 × ⟨5/2⟩ = ⟨7 1/2⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「3 × 2 + 3 × ⟨1/2⟩ = ⟨7 1/2⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/2⟩ = 2 + ⟨1/2⟩이라 두 부분에 모두 3을 곱해야 해요.","3 × ⟨2 1/2⟩ = 3 × ⟨5/2⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","수아는 분수 부분에 곱하지 않아 틀렸어요."],"variant_rule":{"alt":[{"stem":"4 × ⟨1 2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「4 × 1 = 4이니까 ⟨4 2/3⟩야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"서연 — 「4 × ⟨5/3⟩ = ⟨6 2/3⟩야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「4 × 1 + 4 × ⟨2/3⟩ = ⟨6 2/3⟩야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 2/3⟩ = 1 + ⟨2/3⟩라 두 부분에 모두 4를 곱해야 해요.","4 × ⟨1 2/3⟩ = 4 × ⟨5/3⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","민준은 분수 부분에 곱하지 않아 틀렸어요."]},{"stem":"5 × ⟨1 3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「5 × 1 = 5이니까 ⟨5 3/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"나린 — 「5 × ⟨7/4⟩ = ⟨8 3/4⟩이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「5 × 1 + 5 × ⟨3/4⟩ = ⟨8 3/4⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 3/4⟩ = 1 + ⟨3/4⟩이라 두 부분에 모두 5를 곱해야 해요.","5 × ⟨1 3/4⟩ = 5 × ⟨7/4⟩ = ⟨35/4⟩ = ⟨8 3/4⟩이에요.","가온은 분수 부분에 곱하지 않아 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#4','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 7보다 작은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":4,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 7보다 작은 것은 어느 것인가요?","options":[{"t":"7 × ⟨5/6⟩","correct":true},{"t":"7 × ⟨1 1/4⟩","mis":"M5-2-u2-X08"},{"t":"7 × 1","mis":"M5-2-u2-X08"},{"t":"7 × ⟨1 2/5⟩","mis":"M5-2-u2-X08"}],"explanation":["7에 1보다 작은 수를 곱하면 7보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨5/6⟩뿐이에요.","그래서 7보다 작은 것은 7 × ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 9보다 작은 것은 어느 것인가요?","options":[{"t":"9 × ⟨8/9⟩","correct":true},{"t":"9 × ⟨2 1/3⟩","mis":"M5-2-u2-X08"},{"t":"9 × 1","mis":"M5-2-u2-X08"},{"t":"9 × ⟨3 2/7⟩","mis":"M5-2-u2-X08"}],"explanation":["9에 1보다 작은 수를 곱하면 9보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨8/9⟩뿐이에요.","그래서 9보다 작은 것은 9 × ⟨8/9⟩이에요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 3보다 큰 것은 어느 것인가요?","options":[{"t":"3 × ⟨1 1/8⟩","correct":true},{"t":"3 × ⟨1/5⟩","mis":"M5-2-u2-X08"},{"t":"3 × ⟨9/10⟩","mis":"M5-2-u2-X08"},{"t":"3 × 1","mis":"M5-2-u2-X08"}],"explanation":["3에 1보다 작은 수를 곱하면 3보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/8⟩뿐이에요.","그래서 3보다 큰 것은 3 × ⟨1 1/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#5','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'mc','auto','가로가 5 m, 세로가 ⟨2 3/4⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"가로가 5 m, 세로가 ⟨2 3/4⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨13 3/4⟩","correct":true},{"t":"⟨10 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨15 1/2⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 5 × ⟨2 3/4⟩이에요.","세로를 2와 ⟨3/4⟩으로 갈라 더하면 5 × 2 + 5 × ⟨3/4⟩ = 10 + ⟨3 3/4⟩이에요.","5 × ⟨2 3/4⟩ = 5 × ⟨11/4⟩ = ⟨55/4⟩ = ⟨13 3/4⟩ — ⟨13 3/4⟩ m²예요."],"variant_rule":{"alt":[{"stem":"가로가 6 m, 세로가 ⟨1 5/8⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨9 3/4⟩","correct":true},{"t":"⟨6 5/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨15 1/4⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 6 × ⟨1 5/8⟩예요.","세로를 1과 ⟨5/8⟩로 갈라 더하면 6 × 1 + 6 × ⟨5/8⟩ = 6 + ⟨3 3/4⟩이에요.","6 × ⟨1 5/8⟩ = 6 × ⟨13/8⟩ = ⟨78/8⟩ = ⟨39/4⟩ = ⟨9 3/4⟩ — ⟨9 3/4⟩ m²예요."]},{"stem":"가로가 3 m, 세로가 ⟨4 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨13 1/5⟩","correct":true},{"t":"⟨12 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨14 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 3 × ⟨4 2/5⟩예요.","세로를 4와 ⟨2/5⟩로 갈라 더하면 3 × 4 + 3 × ⟨2/5⟩ = 12 + ⟨1 1/5⟩이에요.","3 × ⟨4 2/5⟩ = 3 × ⟨22/5⟩ = ⟨66/5⟩ = ⟨13 1/5⟩ — ⟨13 1/5⟩ m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#6','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'ox','auto','5 × ⟨19/20⟩는 5보다 커요.',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":6,"concept":"M5-2-u2-C5","difficulty":3,"kind":"ox","stem":"5 × ⟨19/20⟩는 5보다 커요.","answer":"X","reason_options":[{"t":"⟨19/20⟩는 1보다 작아 5보다 작아지므로","correct":true},{"t":"분자 19가 크니 곱하면 커지므로","mis":"M5-2-u2-X08"}],"mis":"M5-2-u2-X08","explanation":["⟨19/20⟩는 1에 아주 가깝지만 1보다 작아요.","5 × ⟨19/20⟩ = ⟨95/20⟩ = ⟨4 3/4⟩이에요.","5보다 작아요."],"variant_rule":{"alt":[{"stem":"곱셈을 하면 계산 결과는 언제나 처음 수보다 커져요.","answer":"X","reason_options":[{"t":"1보다 작은 수를 곱하면 처음 수보다 작아지므로","correct":true},{"t":"곱셈은 늘 커지는 계산이므로","mis":"M5-2-u2-X08"}],"explanation":["5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","5보다 작아졌어요.","곱하는 수가 1보다 작으면 결과는 작아져요."]},{"stem":"8 × ⟨3/4⟩의 계산 결과는 8보다 작아요.","answer":"O","reason_options":[{"t":"1보다 작은 ⟨3/4⟩을 곱했으므로","correct":true},{"t":"8에 3을 곱하므로","mis":"M5-2-u2-X08"}],"explanation":["8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요.","6은 8보다 작아요.","곱셈은 곱하는 수만큼을 구하는 계산이에요 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#7','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'sa','auto','6 × ⟨1 3/8⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C5","difficulty":3,"kind":"sa","stem":"6 × ⟨1 3/8⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1 3/8⟩ = ⟨11/8⟩이에요.","6 × ⟨1 3/8⟩ = 6 × ⟨11/8⟩ = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","그래서 분자은 1이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"4 × ⟨3 2/7⟩를 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨3 2/7⟩ = ⟨23/7⟩이에요.","4 × ⟨3 2/7⟩ = 4 × ⟨23/7⟩ = ⟨92/7⟩ = ⟨13 1/7⟩이에요.","그래서 분자은 1이에요."]},{"stem":"7 × ⟨2 1/4⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩예요.","7 × ⟨2 1/4⟩ = 7 × ⟨9/4⟩ = ⟨63/4⟩ = ⟨15 3/4⟩이에요.","그래서 분자은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#8','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',4,'mc','auto','계산 결과가 가장 작은 것은 어느 것인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":8,"concept":"M5-2-u2-C5","difficulty":4,"kind":"mc","stem":"계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"5 × ⟨4/5⟩","correct":true},{"t":"5 × ⟨1 1/5⟩","mis":"M5-2-u2-X17"},{"t":"5 × ⟨1 1/2⟩","mis":"M5-2-u2-X17"},{"t":"5 × ⟨1 2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 5에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수를 견주면 5 × ⟨1 1/5⟩ = 6, 5 × ⟨4/5⟩ = 4, 5 × ⟨1 1/2⟩ = ⟨7 1/2⟩, 5 × ⟨1 2/3⟩ = ⟨8 1/3⟩이에요.","그래서 가장 작은 것은 5 × ⟨4/5⟩예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"6 × ⟨2/3⟩","correct":true},{"t":"6 × ⟨1 1/6⟩","mis":"M5-2-u2-X17"},{"t":"6 × ⟨3/4⟩","mis":"M5-2-u2-X17"},{"t":"6 × ⟨1 5/6⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 6에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수를 견주면 6 × ⟨2/3⟩ = 4, 6 × ⟨1 1/6⟩ = 7, 6 × ⟨3/4⟩ = ⟨4 1/2⟩, 6 × ⟨1 5/6⟩ = 11이에요.","그래서 가장 작은 것은 6 × ⟨2/3⟩예요."]},{"stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"10 × ⟨2 1/2⟩","correct":true},{"t":"10 × ⟨1 3/5⟩","mis":"M5-2-u2-X17"},{"t":"10 × ⟨9/10⟩","mis":"M5-2-u2-X17"},{"t":"10 × ⟨1 1/10⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 10에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수를 견주면 10 × ⟨1 3/5⟩ = 16, 10 × ⟨9/10⟩ = 9, 10 × ⟨1 1/10⟩ = 11, 10 × ⟨2 1/2⟩ = 25예요.","그래서 가장 큰 것은 10 × ⟨2 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#9','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',4,'sa','auto','윤재는 쓰레기를 6 kg 주웠고, 수아는 그 ⟨1 3/8⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C5","difficulty":4,"kind":"sa","stem":"윤재는 쓰레기를 6 kg 주웠고, 수아는 그 ⟨1 3/8⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["6 kg의 ⟨1 3/8⟩배는 6 × ⟨1 3/8⟩이에요.","6 × ⟨1 3/8⟩ = 6 × ⟨11/8⟩ = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","그래서 답은 33이에요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"윤재는 쓰레기를 5 kg 주웠고, 수아는 그 ⟨2 1/3⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["5 kg의 ⟨2 1/3⟩배는 5 × ⟨2 1/3⟩이에요.","5 × ⟨2 1/3⟩ = 5 × ⟨7/3⟩ = ⟨35/3⟩ = ⟨11 2/3⟩예요.","그래서 답은 35예요."]},{"stem":"윤재는 쓰레기를 4 kg 주웠고, 수아는 그 ⟨1 5/6⟩배를 주웠어요. 수아가 주운 쓰레기의 양을 기약분수인 가분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["4 kg의 ⟨1 5/6⟩배는 4 × ⟨1 5/6⟩예요.","4 × ⟨1 5/6⟩ = 4 × ⟨11/6⟩ = ⟨44/6⟩ = ⟨22/3⟩ = ⟨7 1/3⟩이에요.","그래서 답은 22예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L05_challenge#10','math',5,2,'u2','L05','g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',4,'essay','teacher','친구가 「곱셈을 하면 언제나 처음 수보다 커진다」고 말했어요. 5 × ⟨2/3⟩, 5 × 1, 5 × ⟨1 1/9⟩을 예로 들어 친구의 말이 맞는지 판단하고, 곱한 결과가 커지는지 작아지는지 계산하지 않고 알 수 있는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C5","difficulty":4,"kind":"essay","stem":"친구가 「곱셈을 하면 언제나 처음 수보다 커진다」고 말했어요. 5 × ⟨2/3⟩, 5 × 1, 5 × ⟨1 1/9⟩을 예로 들어 친구의 말이 맞는지 판단하고, 곱한 결과가 커지는지 작아지는지 계산하지 않고 알 수 있는 방법을 쓰세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩로 5보다 작고, 5 × 1 = 5로 그대로이며, 5 × ⟨1 1/9⟩ = ⟨50/9⟩ = ⟨5 5/9⟩로 5보다 크다. 곱하는 수가 1보다 작으면 작아지고, 1이면 그대로, 1보다 크면 커지므로 곱하는 수를 1과 견주면 계산하지 않고도 알 수 있다.","scoring_points":["친구의 말이 틀렸다고 판단했는가","세 곱셈의 결과를 5와 견주었는가","곱하는 수를 1과 견주면 된다고 썼는가"]},"explanation":["5 × ⟨2/3⟩ = ⟨3 1/3⟩ — 작아졌어요.","5 × 1 = 5, 5 × ⟨1 1/9⟩ = ⟨5 5/9⟩예요.","곱하는 수를 1과 견주면 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#1','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'mc','auto','⟨1/4⟩ × ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":1,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/4⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨2/12⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 4등분 한 것 중의 1을 다시 3등분 해요.","전체는 4 × 3 = 12칸이 되고, 그중의 1칸이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/5⟩ × ⟨1/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/35⟩","correct":true},{"t":"⟨2/35⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/12⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/12⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 5등분 한 것 중의 1을 다시 7등분 해요.","전체는 5 × 7 = 35칸이 되고, 그중의 1칸이에요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩이에요."]},{"stem":"⟨1/3⟩ × ⟨1/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/24⟩","correct":true},{"t":"⟨2/24⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 3등분 한 것 중의 1을 다시 8등분 해요.","전체는 3 × 8 = 24칸이 되고, 그중의 1칸이에요.","⟨1/3⟩ × ⟨1/8⟩ = ⟨1/24⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#2','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'sa','auto','⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C6","difficulty":1,"kind":"sa","stem":"⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 칸은 분모끼리 곱한 5 × 3 = 15칸이에요.","빗금 친 칸은 분자끼리 곱한 4 × 2 = 8칸이에요.","그래서 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨1/2⟩을 그림으로 나타내려고 전체를 가로로 4등분, 세로로 2등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["전체 칸은 분모끼리 곱한 4 × 2 = 8칸이에요.","빗금 친 칸은 분자끼리 곱한 3 × 1 = 3칸이에요.","그래서 ⟨3/4⟩ × ⟨1/2⟩ = ⟨3/8⟩이에요."]},{"stem":"⟨2/3⟩ × ⟨3/5⟩을 그림으로 나타내려고 전체를 가로로 3등분, 세로로 5등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 칸은 분모끼리 곱한 3 × 5 = 15칸이에요.","빗금 친 칸은 분자끼리 곱한 2 × 3 = 6칸이에요.","그래서 ⟨2/3⟩ × ⟨3/5⟩ = ⟨6/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#3','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'sa','auto','⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u2-C6","difficulty":1,"kind":"sa","stem":"⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["전체 칸은 분모끼리 곱한 5 × 3 = 15칸이에요.","빗금 친 칸은 분자끼리 곱한 4 × 2 = 8칸이에요.","그래서 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨1/2⟩을 그림으로 나타내려고 전체를 가로로 4등분, 세로로 2등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["전체 칸은 분모끼리 곱한 4 × 2 = 8칸이에요.","빗금 친 칸은 분자끼리 곱한 3 × 1 = 3칸이에요.","그래서 ⟨3/4⟩ × ⟨1/2⟩ = ⟨3/8⟩이에요."]},{"stem":"⟨2/3⟩ × ⟨3/5⟩을 그림으로 나타내려고 전체를 가로로 3등분, 세로로 5등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["전체 칸은 분모끼리 곱한 3 × 5 = 15칸이에요.","빗금 친 칸은 분자끼리 곱한 2 × 3 = 6칸이에요.","그래서 ⟨2/3⟩ × ⟨3/5⟩ = ⟨6/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#4','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'ox','auto','⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":4,"concept":"M5-2-u2-C6","difficulty":1,"kind":"ox","stem":"⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","answer":"O","reason_options":[{"t":"4등분 한 것을 다시 3등분 하면 12칸 중 1칸이므로","correct":true},{"t":"분모끼리 더해 7칸 중 1칸이므로","mis":"M5-2-u2-X10"}],"mis":"M5-2-u2-X10","explanation":["가로 4번, 세로 3번 잘라 12칸이에요.","그중의 1칸이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"⟨4/5⟩ × ⟨2/3⟩ = ⟨8/5⟩이에요.","answer":"X","reason_options":[{"t":"분모도 분모끼리 곱해 ⟨8/15⟩이므로","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱하므로","mis":"M5-2-u2-X09"}],"explanation":["분모는 분모끼리 곱해 5 × 3 = 15예요.","분자는 4 × 2 = 8이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."]},{"stem":"⟨3/5⟩ × ⟨1/3⟩을 그림으로 나타내면 전체 칸은 8칸이에요.","answer":"X","reason_options":[{"t":"전체 칸은 분모끼리 곱한 5 × 3 = 15칸이므로","correct":true},{"t":"전체 칸은 분모끼리 더한 5 + 3 = 8칸이므로","mis":"M5-2-u2-X10"}],"explanation":["가로로 5등분, 세로로 3등분 하면 15칸이에요.","빗금 친 칸은 3 × 1 = 3칸이에요.","⟨3/5⟩ × ⟨1/3⟩ = ⟨3/15⟩ = ⟨1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#5','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','⟨4/5⟩ × ⟨2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":5,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ × ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨12/10⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","전체 15칸 가운데 8칸이라고 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ × ⟨5/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5/24⟩","correct":true},{"t":"⟨15/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨15/9⟩","mis":"M5-2-u2-X09"},{"t":"⟨27/40⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩예요.","전체 72칸 가운데 15칸이라고 볼 수 있어요."]},{"stem":"⟨2/7⟩ × ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/14⟩","correct":true},{"t":"⟨6/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/21⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩ = ⟨3/14⟩이에요.","전체 28칸 가운데 6칸이라고 볼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#6','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩이니 ⟨1/4⟩ × ⟨1/3⟩이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","전체의 ⟨1/12⟩이에요."],"variant_rule":{"alt":[{"stem":"이사한 뒤 시루떡 전체의 ⟨1/3⟩ 중에서 ⟨1/2⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨1/3⟩ 중에서 ⟨1/2⟩이니 ⟨1/3⟩ × ⟨1/2⟩이에요.","⟨1/3⟩ × ⟨1/2⟩ = ⟨1/6⟩이에요.","전체의 ⟨1/6⟩이에요."]},{"stem":"이사한 뒤 시루떡 전체의 ⟨2/5⟩ 중에서 ⟨1/4⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/10⟩","correct":true},{"t":"⟨2/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨3/9⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨2/5⟩ 중에서 ⟨1/4⟩이니 ⟨2/5⟩ × ⟨1/4⟩이에요.","⟨2/5⟩ × ⟨1/4⟩ = ⟨2/20⟩ = ⟨1/10⟩이에요.","전체의 ⟨1/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#7','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'sa','auto','⟨9/10⟩ × ⟨5/6⟩를 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C6","difficulty":2,"kind":"sa","stem":"⟨9/10⟩ × ⟨5/6⟩를 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모끼리, 분자끼리 곱해요.","⟨9/10⟩ × ⟨5/6⟩ = ⟨45/60⟩ = ⟨3/4⟩이에요.","그래서 분자는 3이에요."],"mis":"M5-2-u2-X12","variant_rule":{"alt":[{"stem":"⟨3/8⟩ × ⟨5/9⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["분모끼리, 분자끼리 곱해요.","⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩예요.","그래서 분모는 24예요."]},{"stem":"⟨5/6⟩ × ⟨3/10⟩을 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모끼리, 분자끼리 곱해요.","⟨5/6⟩ × ⟨3/10⟩ = ⟨15/60⟩ = ⟨1/4⟩이에요.","그래서 분모는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#8','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','⟨3/4⟩ × ⟨2/5⟩의 계산 결과와 ⟨3/4⟩의 크기를 바르게 견준 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨3/4⟩ × ⟨2/5⟩의 계산 결과와 ⟨3/4⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ × ⟨2/5⟩ < ⟨3/4⟩","correct":true},{"t":"⟨3/4⟩ × ⟨2/5⟩ > ⟨3/4⟩","mis":"M5-2-u2-X08"},{"t":"⟨3/4⟩ × ⟨2/5⟩ = ⟨3/4⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3/4⟩ × ⟨2/5⟩ = ⟨3/10⟩이에요.","1보다 작은 ⟨2/5⟩를 곱했으니 ⟨3/4⟩보다 작아져요.","⟨3/10⟩ < ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ × ⟨1/2⟩의 계산 결과와 ⟨5/6⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩ × ⟨1/2⟩ < ⟨5/6⟩","correct":true},{"t":"⟨5/6⟩ × ⟨1/2⟩ > ⟨5/6⟩","mis":"M5-2-u2-X08"},{"t":"⟨5/6⟩ × ⟨1/2⟩ = ⟨5/6⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩예요.","1보다 작은 ⟨1/2⟩을 곱했으니 ⟨5/6⟩보다 작아져요.","⟨5/12⟩ < ⟨5/6⟩예요."]},{"stem":"⟨7/8⟩ × ⟨3/4⟩의 계산 결과와 ⟨7/8⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨7/8⟩ × ⟨3/4⟩ < ⟨7/8⟩","correct":true},{"t":"⟨7/8⟩ × ⟨3/4⟩ > ⟨7/8⟩","mis":"M5-2-u2-X08"},{"t":"⟨7/8⟩ × ⟨3/4⟩ = ⟨7/8⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨7/8⟩ × ⟨3/4⟩ = ⟨21/32⟩이에요.","1보다 작은 ⟨3/4⟩을 곱했으니 ⟨7/8⟩보다 작아져요.","⟨21/32⟩ < ⟨7/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#9','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','⟨4/5⟩ × ⟨2/3⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":9,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ × ⟨2/3⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"분모는 분모끼리, 분자는 분자끼리 곱한다","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱한다","mis":"M5-2-u2-X09"},{"t":"분자는 그대로 두고 분모끼리 곱한다","mis":"M5-2-u2-X10"},{"t":"분모와 분자를 서로 엇갈려 곱한다","mis":"M5-2-u2-X10"}],"explanation":["⟨4/5⟩ × ⟨2/3⟩를 그림으로 그리면 가로 5등분, 세로 3등분 해서 전체는 5 × 3 = 15칸이에요.","빗금 친 칸은 4 × 2 = 8칸이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩ — 분모끼리, 분자끼리 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨1/2⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"분모는 분모끼리, 분자는 분자끼리 곱한다","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱한다","mis":"M5-2-u2-X09"},{"t":"분자는 그대로 두고 분모끼리 곱한다","mis":"M5-2-u2-X10"},{"t":"분모와 분자를 서로 엇갈려 곱한다","mis":"M5-2-u2-X10"}],"explanation":["⟨3/4⟩ × ⟨1/2⟩을 그림으로 그리면 가로 4등분, 세로 2등분 해서 전체는 4 × 2 = 8칸이에요.","빗금 친 칸은 3 × 1 = 3칸이에요.","⟨3/4⟩ × ⟨1/2⟩ = ⟨3/8⟩ — 분모끼리, 분자끼리 곱했어요."]},{"stem":"⟨2/3⟩ × ⟨3/5⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"분모는 분모끼리, 분자는 분자끼리 곱한다","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱한다","mis":"M5-2-u2-X09"},{"t":"분자는 그대로 두고 분모끼리 곱한다","mis":"M5-2-u2-X10"},{"t":"분모와 분자를 서로 엇갈려 곱한다","mis":"M5-2-u2-X10"}],"explanation":["⟨2/3⟩ × ⟨3/5⟩을 그림으로 그리면 가로 3등분, 세로 5등분 해서 전체는 3 × 5 = 15칸이에요.","빗금 친 칸은 2 × 3 = 6칸이에요.","⟨2/3⟩ × ⟨3/5⟩ = ⟨6/15⟩ = ⟨2/5⟩ — 분모끼리, 분자끼리 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_basic#10','math',5,2,'u2','L06','g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',3,'mc','auto','⟨2/3⟩ × ⟨3/4⟩과 ⟨4/5⟩ × ⟨5/6⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],true,'{"seq":10,"concept":"M5-2-u2-C6","difficulty":3,"kind":"mc","stem":"⟨2/3⟩ × ⟨3/4⟩과 ⟨4/5⟩ × ⟨5/6⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ × ⟨5/6⟩","correct":true},{"t":"⟨2/3⟩ × ⟨3/4⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X10"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨2/3⟩ × ⟨3/4⟩ = ⟨6/12⟩ = ⟨1/2⟩이에요.","⟨4/5⟩ × ⟨5/6⟩ = ⟨20/30⟩ = ⟨2/3⟩예요.","⟨1/2⟩ < ⟨2/3⟩라 ⟨4/5⟩ × ⟨5/6⟩가 더 커요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ × ⟨4/5⟩와 ⟨3/4⟩ × ⟨2/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ × ⟨2/3⟩","correct":true},{"t":"⟨1/2⟩ × ⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X10"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1/2⟩ × ⟨4/5⟩ = ⟨4/10⟩ = ⟨2/5⟩예요.","⟨3/4⟩ × ⟨2/3⟩ = ⟨6/12⟩ = ⟨1/2⟩이에요.","⟨2/5⟩ < ⟨1/2⟩이라 ⟨3/4⟩ × ⟨2/3⟩가 더 커요."]},{"stem":"⟨5/6⟩ × ⟨3/10⟩과 ⟨2/5⟩ × ⟨3/4⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩ × ⟨3/4⟩","correct":true},{"t":"⟨5/6⟩ × ⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X10"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨5/6⟩ × ⟨3/10⟩ = ⟨15/60⟩ = ⟨1/4⟩이에요.","⟨2/5⟩ × ⟨3/4⟩ = ⟨6/20⟩ = ⟨3/10⟩이에요.","⟨1/4⟩ < ⟨3/10⟩이라 ⟨2/5⟩ × ⟨3/4⟩이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#1','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',2,'mc','auto','⟨9/10⟩ × ⟨5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":1,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨9/10⟩ × ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨45/10⟩","mis":"M5-2-u2-X09"},{"t":"⟨45/6⟩","mis":"M5-2-u2-X09"},{"t":"⟨54/50⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨9/10⟩ × ⟨5/6⟩ = ⟨45/60⟩ = ⟨3/4⟩이에요.","전체 60칸 가운데 45칸이라고 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨1/5⟩ × ⟨1/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/35⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨7/5⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩이에요.","전체 35칸 가운데 1칸이라고 볼 수 있어요."]},{"stem":"⟨5/8⟩ × ⟨4/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨20/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨20/15⟩","mis":"M5-2-u2-X09"},{"t":"⟨75/32⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨5/8⟩ × ⟨4/15⟩ = ⟨20/120⟩ = ⟨1/6⟩이에요.","전체 120칸 가운데 20칸이라고 볼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#2','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',2,'sa','auto','⟨3/8⟩ × ⟨5/9⟩를 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C6","difficulty":2,"kind":"sa","stem":"⟨3/8⟩ × ⟨5/9⟩를 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모끼리, 분자끼리 곱해요.","⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩예요.","그래서 분자는 5예요."],"mis":"M5-2-u2-X12","variant_rule":{"alt":[{"stem":"⟨4/9⟩ × ⟨3/8⟩을 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모끼리, 분자끼리 곱해요.","⟨4/9⟩ × ⟨3/8⟩ = ⟨12/72⟩ = ⟨1/6⟩이에요.","그래서 분모는 6이에요."]},{"stem":"⟨7/12⟩ × ⟨4/21⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모끼리, 분자끼리 곱해요.","⟨7/12⟩ × ⟨4/21⟩ = ⟨28/252⟩ = ⟨1/9⟩이에요.","그래서 분모는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#3','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'error','auto','⟨4/5⟩ × ⟨2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨4/5⟩ × ⟨2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「분모는 그대로 두고 분자끼리 곱해 ⟨8/5⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"도윤 — 「⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「전체 15칸 중 8칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","수아는 분모를 그대로 두어 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ × ⟨2/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「분모는 그대로 두고 분자끼리 곱해 ⟨6/7⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"서연 — 「⟨3/7⟩ × ⟨2/5⟩ = ⟨6/35⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「전체 35칸 중 6칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨3/7⟩ × ⟨2/5⟩ = ⟨6/35⟩이에요.","민준은 분모를 그대로 두어 틀렸어요."]},{"stem":"⟨5/6⟩ × ⟨1/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「분모는 그대로 두고 분자끼리 곱해 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"나린 — 「⟨5/6⟩ × ⟨1/4⟩ = ⟨5/24⟩야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「전체 24칸 중 5칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨5/6⟩ × ⟨1/4⟩ = ⟨5/24⟩예요.","가온은 분모를 그대로 두어 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#4','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'error','auto','⟨4/9⟩ × ⟨6/7⟩을 곱하기 전에 약분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u2-X13','M5-2-u2-X17']::text[],true,'{"seq":4,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨4/9⟩ × ⟨6/7⟩을 곱하기 전에 약분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「분자 4와 분자 6을 약분해도 돼.」","correct":true,"mis_target":"M5-2-u2-X13"},{"t":"도윤 — 「분자 6과 분모 9를 약분해도 돼.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「약분하지 않고 곱한 뒤 기약분수로 나타내도 돼.」","mis":"M5-2-u2-X17"}],"explanation":["약분은 분자와 분모를 같은 수로 나누는 것이라 분자와 분모 사이에서만 해요.","분자끼리 나누면 값이 달라져요.","바르게 하면 ⟨4/9⟩ × ⟨6/7⟩ = ⟨24/63⟩ = ⟨8/21⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨6/7⟩ × ⟨9/10⟩를 곱하기 전에 약분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「분자 6과 분자 9를 약분해도 돼.」","correct":true,"mis_target":"M5-2-u2-X13"},{"t":"서연 — 「분자 6과 분모 10을 약분해도 돼.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「약분하지 않고 곱한 뒤 기약분수로 나타내도 돼.」","mis":"M5-2-u2-X17"}],"explanation":["약분은 분자와 분모를 같은 수로 나누는 것이라 분자와 분모 사이에서만 해요.","분자끼리 나누면 값이 달라져요.","바르게 하면 ⟨6/7⟩ × ⟨9/10⟩ = ⟨54/70⟩ = ⟨27/35⟩이에요."]},{"stem":"⟨8/9⟩ × ⟨6/11⟩을 곱하기 전에 약분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자 8과 분자 6을 약분해도 돼.」","correct":true,"mis_target":"M5-2-u2-X13"},{"t":"나린 — 「분자 6과 분모 9를 약분해도 돼.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「약분하지 않고 곱한 뒤 기약분수로 나타내도 돼.」","mis":"M5-2-u2-X17"}],"explanation":["약분은 분자와 분모를 같은 수로 나누는 것이라 분자와 분모 사이에서만 해요.","분자끼리 나누면 값이 달라져요.","바르게 하면 ⟨8/9⟩ × ⟨6/11⟩ = ⟨48/99⟩ = ⟨16/33⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#5','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'sa','auto','⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C6","difficulty":3,"kind":"sa","stem":"⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 3 = 12이어야 해요.","12 ÷ 3 = 4니 □는 4예요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"⟨1/□⟩ × ⟨1/6⟩ = ⟨1/30⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 6 = 30이어야 해요.","30 ÷ 6 = 5니 □는 5예요."]},{"stem":"⟨1/□⟩ × ⟨1/2⟩ = ⟨1/14⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 2 = 14이어야 해요.","14 ÷ 2 = 7이니 □는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#6','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'ox','auto','⟨9/10⟩ × ⟨5/6⟩에서 곱하기 전에 분자 9와 분모 6을 약분해도 돼요.',ARRAY['M5-2-u2-X13']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":3,"kind":"ox","stem":"⟨9/10⟩ × ⟨5/6⟩에서 곱하기 전에 분자 9와 분모 6을 약분해도 돼요.","answer":"O","reason_options":[{"t":"분자와 분모 사이의 약분은 언제 해도 값이 같으므로","correct":true},{"t":"분모끼리만 약분할 수 있으므로","mis":"M5-2-u2-X13"}],"mis":"M5-2-u2-X13","explanation":["9와 6을 3으로, 5와 10을 5로 약분하면 ⟨3/2⟩ × ⟨1/2⟩이에요.","⟨3/2⟩ × ⟨1/2⟩ = ⟨3/4⟩이에요.","곱한 뒤 약분해도 ⟨45/60⟩ = ⟨3/4⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"진분수끼리 곱하면 계산 결과는 곱한 두 분수보다 작아요.","answer":"O","reason_options":[{"t":"1보다 작은 수를 곱하면 작아지므로","correct":true},{"t":"곱하면 언제나 커지므로","mis":"M5-2-u2-X08"}],"explanation":["⟨2/3⟩ × ⟨3/4⟩ = ⟨1/2⟩이에요.","⟨1/2⟩은 ⟨2/3⟩보다도, ⟨3/4⟩보다도 작아요.","그래서 맞아요."]},{"stem":"⟨1/5⟩ × ⟨1/7⟩ = ⟨2/35⟩예요.","answer":"X","reason_options":[{"t":"분자끼리 곱하면 1 × 1 = 1이라 ⟨1/35⟩이므로","correct":true},{"t":"분자끼리 더해 2가 되므로","mis":"M5-2-u2-X10"}],"explanation":["분모끼리 5 × 7 = 35예요.","분자끼리 1 × 1 = 1이에요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#7','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'mc','auto','이사한 뒤 시루떡 전체의 ⟨3/4⟩ 중에서 ⟨2/3⟩를 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":7,"concept":"M5-2-u2-C6","difficulty":3,"kind":"mc","stem":"이사한 뒤 시루떡 전체의 ⟨3/4⟩ 중에서 ⟨2/3⟩를 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨6/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨3/4⟩ 중에서 ⟨2/3⟩니 ⟨3/4⟩ × ⟨2/3⟩예요.","⟨3/4⟩ × ⟨2/3⟩ = ⟨6/12⟩ = ⟨1/2⟩이에요.","전체의 ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"이사한 뒤 시루떡 전체의 ⟨5/6⟩ 중에서 ⟨3/5⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨15/6⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨5/6⟩ 중에서 ⟨3/5⟩이니 ⟨5/6⟩ × ⟨3/5⟩이에요.","⟨5/6⟩ × ⟨3/5⟩ = ⟨15/30⟩ = ⟨1/2⟩이에요.","전체의 ⟨1/2⟩이에요."]},{"stem":"이사한 뒤 시루떡 전체의 ⟨2/3⟩ 중에서 ⟨3/8⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨6/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨3/8⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨2/3⟩ 중에서 ⟨3/8⟩이니 ⟨2/3⟩ × ⟨3/8⟩이에요.","⟨2/3⟩ × ⟨3/8⟩ = ⟨6/24⟩ = ⟨1/4⟩이에요.","전체의 ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#8','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',4,'match','auto','곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":4,"kind":"match","stem":"곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨1/2⟩ × ⟨1/3⟩","r":"⟨1/6⟩"},{"l":"⟨2/3⟩ × ⟨3/4⟩","r":"⟨1/2⟩"},{"l":"⟨3/5⟩ × ⟨5/9⟩","r":"⟨1/3⟩"}],"mis":"M5-2-u2-X10","explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/2⟩ × ⟨1/3⟩ = ⟨1/6⟩, ⟨2/3⟩ × ⟨3/4⟩ = ⟨6/12⟩ = ⟨1/2⟩, ⟨3/5⟩ × ⟨5/9⟩ = ⟨15/45⟩ = ⟨1/3⟩이에요.","분모를 그대로 두지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨1/4⟩ × ⟨2/5⟩","r":"⟨1/10⟩"},{"l":"⟨3/7⟩ × ⟨1/3⟩","r":"⟨1/7⟩"},{"l":"⟨5/8⟩ × ⟨2/3⟩","r":"⟨5/12⟩"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/4⟩ × ⟨2/5⟩ = ⟨2/20⟩ = ⟨1/10⟩, ⟨3/7⟩ × ⟨1/3⟩ = ⟨3/21⟩ = ⟨1/7⟩, ⟨5/8⟩ × ⟨2/3⟩ = ⟨10/24⟩ = ⟨5/12⟩예요.","분모를 그대로 두지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨2/5⟩ × ⟨5/6⟩","r":"⟨1/3⟩"},{"l":"⟨3/4⟩ × ⟨1/6⟩","r":"⟨1/8⟩"},{"l":"⟨4/9⟩ × ⟨3/8⟩","r":"⟨1/6⟩"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/5⟩ × ⟨5/6⟩ = ⟨10/30⟩ = ⟨1/3⟩, ⟨3/4⟩ × ⟨1/6⟩ = ⟨3/24⟩ = ⟨1/8⟩, ⟨4/9⟩ × ⟨3/8⟩ = ⟨12/72⟩ = ⟨1/6⟩이에요.","분모를 그대로 두지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#9','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',4,'sa','auto','⟨5/6⟩ × ⟨3/4⟩을 그림으로 나타내려고 전체를 가로로 6등분, 세로로 4등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C6","difficulty":4,"kind":"sa","stem":"⟨5/6⟩ × ⟨3/4⟩을 그림으로 나타내려고 전체를 가로로 6등분, 세로로 4등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 칸은 분모끼리 곱한 6 × 4 = 24칸이에요.","빗금 친 칸은 분자끼리 곱한 5 × 3 = 15칸이에요.","그래서 ⟨5/6⟩ × ⟨3/4⟩ = ⟨15/24⟩예요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"⟨7/8⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 8등분, 세로로 3등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["전체 칸은 분모끼리 곱한 8 × 3 = 24칸이에요.","빗금 친 칸은 분자끼리 곱한 7 × 2 = 14칸이에요.","그래서 ⟨7/8⟩ × ⟨2/3⟩ = ⟨14/24⟩예요."]},{"stem":"⟨3/10⟩ × ⟨7/9⟩을 그림으로 나타내려고 전체를 가로로 10등분, 세로로 9등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["전체 칸은 분모끼리 곱한 10 × 9 = 90칸이에요.","빗금 친 칸은 분자끼리 곱한 3 × 7 = 21칸이에요.","그래서 ⟨3/10⟩ × ⟨7/9⟩ = ⟨21/90⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L06_challenge#10','math',5,2,'u2','L06','g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',4,'essay','teacher','⟨4/5⟩ × ⟨2/3⟩를 직사각형 그림으로 설명하려고 해요. 전체를 어떻게 자르는지, 전체 칸과 빗금 친 칸이 몇 개인지 쓰고, 분모끼리·분자끼리 곱하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C6","difficulty":4,"kind":"essay","stem":"⟨4/5⟩ × ⟨2/3⟩를 직사각형 그림으로 설명하려고 해요. 전체를 어떻게 자르는지, 전체 칸과 빗금 친 칸이 몇 개인지 쓰고, 분모끼리·분자끼리 곱하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 전체를 가로로 5등분, 세로로 3등분 하면 전체 칸은 5 × 3 = 15칸이다. ⟨4/5⟩만큼(가로 4칸) 중에서 ⟨2/3⟩만큼(세로 2칸)을 빗금 치면 4 × 2 = 8칸이다. 그래서 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이다. 가로와 세로로 모두 잘랐기 때문에 전체 칸은 분모끼리의 곱, 빗금 친 칸은 분자끼리의 곱이 된다.","scoring_points":["가로 5등분·세로 3등분으로 전체 15칸을 구했는가","빗금 친 칸 8칸을 구했는가","⟨8/15⟩을 구하고 분모끼리·분자끼리 곱하는 까닭을 썼는가"]},"explanation":["전체는 5 × 3 = 15칸이에요.","빗금 친 칸은 4 × 2 = 8칸이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#1','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'sa','auto','⟨3 1/2⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨3 1/2⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 3은 ⟨6/2⟩이에요.","분자는 3 × 2 + 1 = 7이에요.","⟨3 1/2⟩ = ⟨7/2⟩이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨1 4/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["자연수 1은 ⟨5/5⟩예요.","분자는 1 × 5 + 4 = 9예요.","⟨1 4/5⟩ = ⟨9/5⟩예요."]},{"stem":"⟨2 2/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["자연수 2는 ⟨10/5⟩이에요.","분자는 2 × 5 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#2','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'mc','auto','자연수 2를 분모가 1인 분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X14']::text[],true,'{"seq":2,"concept":"M5-2-u2-C7","difficulty":1,"kind":"mc","stem":"자연수 2를 분모가 1인 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/1⟩","correct":true},{"t":"⟨2/2⟩","mis":"M5-2-u2-X14"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X14"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X14"}],"explanation":["분모가 1인 분수는 「1로 나눈 것」이라 분자 그대로예요.","2 = ⟨2/1⟩예요.","⟨2/2⟩는 1, ⟨1/2⟩은 1보다 작은 수라 2가 아니에요."],"variant_rule":{"alt":[{"stem":"자연수 5를 분모가 1인 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/1⟩","correct":true},{"t":"⟨5/5⟩","mis":"M5-2-u2-X14"},{"t":"⟨1/5⟩","mis":"M5-2-u2-X14"},{"t":"⟨5/10⟩","mis":"M5-2-u2-X14"}],"explanation":["분모가 1인 분수는 「1로 나눈 것」이라 분자 그대로예요.","5 = ⟨5/1⟩예요.","⟨5/5⟩는 1, ⟨1/5⟩은 1보다 작은 수라 5가 아니에요."]},{"stem":"자연수 7을 분모가 1인 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/1⟩","correct":true},{"t":"⟨7/7⟩","mis":"M5-2-u2-X14"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X14"},{"t":"⟨7/10⟩","mis":"M5-2-u2-X14"}],"explanation":["분모가 1인 분수는 「1로 나눈 것」이라 분자 그대로예요.","7 = ⟨7/1⟩이에요.","⟨7/7⟩은 1, ⟨1/7⟩은 1보다 작은 수라 7이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#3','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'ox','auto','대분수끼리 곱할 때는 먼저 가분수로 고쳐서 분모끼리, 분자끼리 곱해요.',ARRAY['M5-2-u2-X11']::text[],true,'{"seq":3,"concept":"M5-2-u2-C7","difficulty":1,"kind":"ox","stem":"대분수끼리 곱할 때는 먼저 가분수로 고쳐서 분모끼리, 분자끼리 곱해요.","answer":"O","reason_options":[{"t":"대분수 그대로는 분모끼리·분자끼리 곱하는 규칙을 쓸 수 없으므로","correct":true},{"t":"자연수끼리, 분수끼리 따로 곱하면 되므로","mis":"M5-2-u2-X11"}],"mis":"M5-2-u2-X11","explanation":["⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩예요.","⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"자연수 2를 분모가 1인 분수로 나타내면 ⟨2/1⟩예요.","answer":"O","reason_options":[{"t":"2를 1로 나누면 2이므로","correct":true},{"t":"분모와 분자가 같아야 하므로","mis":"M5-2-u2-X14"}],"explanation":["분모가 1이면 분자 그대로의 수예요.","⟨2/1⟩ = 2예요.","그래서 맞아요."]},{"stem":"⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨3 4/10⟩예요.","answer":"X","reason_options":[{"t":"가분수로 고쳐 계산하면 ⟨6 3/10⟩이므로","correct":true},{"t":"자연수끼리 3 × 1, 분수끼리 곱하면 되므로","mis":"M5-2-u2-X11"}],"explanation":["자연수끼리·분수끼리 따로 곱하면 빠지는 부분이 생겨요.","⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩이에요.","바른 답은 ⟨6 3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#4','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'sa','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대분수는 먼저 가분수로 고쳐요.","⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","그래서 자연수 부분은 6이에요."],"mis":"M5-2-u2-X11","variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대분수는 먼저 가분수로 고쳐요.","⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","그래서 자연수 부분은 4예요."]},{"stem":"⟨2 1/3⟩ × ⟨1 1/5⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대분수는 먼저 가분수로 고쳐요.","⟨2 1/3⟩ × ⟨1 1/5⟩ = ⟨7/3⟩ × ⟨6/5⟩ = ⟨42/15⟩ = ⟨14/5⟩ = ⟨2 4/5⟩예요.","그래서 자연수 부분은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#5','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04','M5-2-u2-X12']::text[],true,'{"seq":5,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/10⟩","correct":true},{"t":"⟨3 2/5⟩","mis":"M5-2-u2-X11"},{"t":"⟨3 3/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨7 3/10⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩.","분모끼리, 분자끼리 곱해요.","⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/5⟩","correct":true},{"t":"⟨2 3/10⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨5 1/5⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨2 2/5⟩ = ⟨12/5⟩, ⟨1 3/4⟩ = ⟨7/4⟩.","분모끼리, 분자끼리 곱해요.","⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요."]},{"stem":"⟨1 2/3⟩ × ⟨2 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨2 1/6⟩","mis":"M5-2-u2-X11"},{"t":"⟨2 1/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨4 3/4⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 2/3⟩ = ⟨5/3⟩, ⟨2 1/4⟩ = ⟨9/4⟩.","분모끼리, 분자끼리 곱해요.","⟨1 2/3⟩ × ⟨2 1/4⟩ = ⟨5/3⟩ × ⟨9/4⟩ = ⟨45/12⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#6','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":6,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5/21⟩","correct":true},{"t":"⟨10/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/42⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"}],"explanation":["분수가 셋이어도 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩ = ⟨10/42⟩ = ⟨5/21⟩예요.","앞의 두 수만 곱하고 멈추지 않도록 해요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩ × ⟨3/4⟩ × ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/10⟩","correct":true},{"t":"⟨6/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X17"},{"t":"⟨6/12⟩","mis":"M5-2-u2-X10"}],"explanation":["분수가 셋이어도 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨3/4⟩ × ⟨1/5⟩ = ⟨6/60⟩ = ⟨1/10⟩이에요.","앞의 두 수만 곱하고 멈추지 않도록 해요."]},{"stem":"⟨1/3⟩ × ⟨3/5⟩ × ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/8⟩","correct":true},{"t":"⟨15/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨9/120⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/5⟩","mis":"M5-2-u2-X17"}],"explanation":["분수가 셋이어도 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/3⟩ × ⟨3/5⟩ × ⟨5/8⟩ = ⟨15/120⟩ = ⟨1/8⟩이에요.","앞의 두 수만 곱하고 멈추지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#7','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'sa','auto','⟨1 7/25⟩ × ⟨5/12⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":2,"kind":"sa","stem":"⟨1 7/25⟩ × ⟨5/12⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨1 7/25⟩ × ⟨5/12⟩ = ⟨32/25⟩ × ⟨5/12⟩ = ⟨160/300⟩ = ⟨8/15⟩이에요.","그래서 분모는 15예요."],"mis":"M5-2-u2-X12","variant_rule":{"alt":[{"stem":"5 × ⟨7/10⟩ × ⟨3/14⟩을 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","5 × ⟨7/10⟩ × ⟨3/14⟩ = ⟨5/1⟩ × ⟨7/10⟩ × ⟨3/14⟩ = ⟨105/140⟩ = ⟨3/4⟩이에요.","그래서 분모는 4예요."]},{"stem":"⟨1 1/6⟩ × ⟨3/7⟩을 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨1 1/6⟩ × ⟨3/7⟩ = ⟨7/6⟩ × ⟨3/7⟩ = ⟨21/42⟩ = ⟨1/2⟩이에요.","그래서 분모는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#8','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하는 순서를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],true,'{"seq":8,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하는 순서를 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞에서부터 곱해도, 뒤의 두 수를 먼저 곱해도 답이 같다","correct":true},{"t":"반드시 앞의 두 수부터 곱해야 답이 맞다","mis":"M5-2-u2-X17"},{"t":"뒤의 두 수를 먼저 곱하면 답이 달라진다","mis":"M5-2-u2-X17"},{"t":"세 분수는 한꺼번에 곱할 수 없다","mis":"M5-2-u2-X10"}],"explanation":["앞에서부터: ⟨1/2⟩ × ⟨2/3⟩ = ⟨1/3⟩, 여기에 ⟨5/7⟩를 곱해요.","뒤부터: ⟨2/3⟩ × ⟨5/7⟩ = ⟨10/21⟩을 먼저 구해요.","어느 쪽이든 ⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩ = ⟨5/21⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨2/5⟩ × ⟨5/6⟩를 계산하는 순서를 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞에서부터 곱해도, 뒤의 두 수를 먼저 곱해도 답이 같다","correct":true},{"t":"반드시 앞의 두 수부터 곱해야 답이 맞다","mis":"M5-2-u2-X17"},{"t":"뒤의 두 수를 먼저 곱하면 답이 달라진다","mis":"M5-2-u2-X17"},{"t":"세 분수는 한꺼번에 곱할 수 없다","mis":"M5-2-u2-X10"}],"explanation":["앞에서부터: ⟨3/4⟩ × ⟨2/5⟩ = ⟨3/10⟩, 여기에 ⟨5/6⟩를 곱해요.","뒤부터: ⟨2/5⟩ × ⟨5/6⟩ = ⟨1/3⟩을 먼저 구해요.","어느 쪽이든 ⟨3/4⟩ × ⟨2/5⟩ × ⟨5/6⟩ = ⟨1/4⟩이에요."]},{"stem":"⟨4/5⟩ × ⟨1/2⟩ × ⟨5/8⟩를 계산하는 순서를 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞에서부터 곱해도, 뒤의 두 수를 먼저 곱해도 답이 같다","correct":true},{"t":"반드시 앞의 두 수부터 곱해야 답이 맞다","mis":"M5-2-u2-X17"},{"t":"뒤의 두 수를 먼저 곱하면 답이 달라진다","mis":"M5-2-u2-X17"},{"t":"세 분수는 한꺼번에 곱할 수 없다","mis":"M5-2-u2-X10"}],"explanation":["앞에서부터: ⟨4/5⟩ × ⟨1/2⟩ = ⟨2/5⟩, 여기에 ⟨5/8⟩를 곱해요.","뒤부터: ⟨1/2⟩ × ⟨5/8⟩ = ⟨5/16⟩를 먼저 구해요.","어느 쪽이든 ⟨4/5⟩ × ⟨1/2⟩ × ⟨5/8⟩ = ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#9','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'sa','auto','5학년 학생 160명 가운데 ⟨5/8⟩가 남학생이고, 남학생 가운데 ⟨3/5⟩이 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C7","difficulty":2,"kind":"sa","stem":"5학년 학생 160명 가운데 ⟨5/8⟩가 남학생이고, 남학생 가운데 ⟨3/5⟩이 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["남학생은 160 × ⟨5/8⟩ = 100명이에요.","그 가운데 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60명이에요.","한 번에 160 × ⟨5/8⟩ × ⟨3/5⟩ = 60으로 구해도 같아요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"5학년 학생 120명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨2/3⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["남학생은 120 × ⟨3/4⟩ = 90명이에요.","그 가운데 ⟨2/3⟩니 90 × ⟨2/3⟩ = 60명이에요.","한 번에 120 × ⟨3/4⟩ × ⟨2/3⟩ = 60으로 구해도 같아요."]},{"stem":"5학년 학생 140명 가운데 ⟨4/7⟩가 남학생이고, 남학생 가운데 ⟨3/8⟩이 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["남학생은 140 × ⟨4/7⟩ = 80명이에요.","그 가운데 ⟨3/8⟩이니 80 × ⟨3/8⟩ = 30명이에요.","한 번에 140 × ⟨4/7⟩ × ⟨3/8⟩ = 30으로 구해도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_basic#10','math',5,2,'u2','L07','g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',3,'mc','auto','⟨1 1/2⟩ × ⟨1 1/3⟩과 ⟨2 1/2⟩ × ⟨2/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X11']::text[],true,'{"seq":10,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"⟨1 1/2⟩ × ⟨1 1/3⟩과 ⟨2 1/2⟩ × ⟨2/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1 1/2⟩ × ⟨1 1/3⟩","correct":true},{"t":"⟨2 1/2⟩ × ⟨2/3⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X11"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/2⟩ × ⟨1 1/3⟩ = ⟨3/2⟩ × ⟨4/3⟩ = ⟨12/6⟩ = 2예요.","⟨2 1/2⟩ × ⟨2/3⟩ = ⟨5/2⟩ × ⟨2/3⟩ = ⟨10/6⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","2 > ⟨1 2/3⟩라 ⟨1 1/2⟩ × ⟨1 1/3⟩이 더 커요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × ⟨3/4⟩과 ⟨1 3/5⟩ × ⟨1 1/4⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1 3/5⟩ × ⟨1 1/4⟩","correct":true},{"t":"⟨2 1/3⟩ × ⟨3/4⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X11"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × ⟨3/4⟩ = ⟨7/3⟩ × ⟨3/4⟩ = ⟨21/12⟩ = ⟨7/4⟩ = ⟨1 3/4⟩이에요.","⟨1 3/5⟩ × ⟨1 1/4⟩ = ⟨8/5⟩ × ⟨5/4⟩ = ⟨40/20⟩ = 2예요.","⟨1 3/4⟩ < 2라 ⟨1 3/5⟩ × ⟨1 1/4⟩이 더 커요."]},{"stem":"⟨1 1/4⟩ × ⟨1 1/5⟩과 ⟨3/4⟩ × ⟨2 1/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ × ⟨2 1/3⟩","correct":true},{"t":"⟨1 1/4⟩ × ⟨1 1/5⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X11"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/4⟩ × ⟨1 1/5⟩ = ⟨5/4⟩ × ⟨6/5⟩ = ⟨30/20⟩ = ⟨3/2⟩ = ⟨1 1/2⟩이에요.","⟨3/4⟩ × ⟨2 1/3⟩ = ⟨3/4⟩ × ⟨7/3⟩ = ⟨21/12⟩ = ⟨7/4⟩ = ⟨1 3/4⟩이에요.","⟨1 1/2⟩ < ⟨1 3/4⟩이라 ⟨3/4⟩ × ⟨2 1/3⟩이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EX