INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#1','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',2,'mc','auto','⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04','M5-2-u2-X12']::text[],true,'{"seq":1,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/5⟩","correct":true},{"t":"⟨2 3/10⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨5 1/5⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨2 2/5⟩ = ⟨12/5⟩, ⟨1 3/4⟩ = ⟨7/4⟩.","분모끼리, 분자끼리 곱해요.","⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 3/7⟩ × ⟨2 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨2 1/7⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 1/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨4 1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 3/7⟩ = ⟨10/7⟩, ⟨2 1/3⟩ = ⟨7/3⟩.","분모끼리, 분자끼리 곱해요.","⟨1 3/7⟩ × ⟨2 1/3⟩ = ⟨10/7⟩ × ⟨7/3⟩ = ⟨70/21⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요."]},{"stem":"⟨3 1/3⟩ × ⟨1 1/5⟩을 계산하면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"⟨3 1/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 3/5⟩","mis":"M5-2-u2-X04"},{"t":"5","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨3 1/3⟩ = ⟨10/3⟩, ⟨1 1/5⟩ = ⟨6/5⟩.","분모끼리, 분자끼리 곱해요.","⟨3 1/3⟩ × ⟨1 1/5⟩ = ⟨10/3⟩ × ⟨6/5⟩ = ⟨60/15⟩ = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#2','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',2,'sa','auto','⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C7","difficulty":2,"kind":"sa","stem":"⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩ = ⟨84/3024⟩ = ⟨1/36⟩이에요.","그래서 분모는 36이에요."],"mis":"M5-2-u2-X12","variant_rule":{"alt":[{"stem":"5 × ⟨7/10⟩ × ⟨3/14⟩을 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","5 × ⟨7/10⟩ × ⟨3/14⟩ = ⟨5/1⟩ × ⟨7/10⟩ × ⟨3/14⟩ = ⟨105/140⟩ = ⟨3/4⟩이에요.","그래서 분모는 4예요."]},{"stem":"⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩ = ⟨10/42⟩ = ⟨5/21⟩예요.","그래서 분모는 21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#3','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'error','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨4/5⟩ 해서 ⟨3 2/5⟩야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"도윤 — 「가분수로 고쳐 ⟨7/2⟩ × ⟨9/5⟩ = ⟨6 3/10⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨3 1/2⟩ × ⟨1 4/5⟩의 답은 ⟨6 3/10⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","수아는 부분끼리 따로 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × ⟨1 1/2⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/3⟩ × ⟨1/2⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"서연 — 「가분수로 고쳐 ⟨7/3⟩ × ⟨3/2⟩ = ⟨3 1/2⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨2 1/3⟩ × ⟨1 1/2⟩의 답은 ⟨3 1/2⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/3⟩ × ⟨1 1/2⟩ = ⟨7/3⟩ × ⟨3/2⟩ = ⟨21/6⟩ = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","민준은 부분끼리 따로 곱해서 틀렸어요."]},{"stem":"⟨1 2/5⟩ × ⟨2 1/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「자연수끼리 1 × 2, 분수끼리 ⟨2/5⟩ × ⟨1/4⟩ 해서 ⟨2 1/10⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"나린 — 「가분수로 고쳐 ⟨7/5⟩ × ⟨9/4⟩ = ⟨3 3/20⟩이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨1 2/5⟩ × ⟨2 1/4⟩의 답은 ⟨3 3/20⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨1 2/5⟩ × ⟨2 1/4⟩ = ⟨7/5⟩ × ⟨9/4⟩ = ⟨63/20⟩ = ⟨3 3/20⟩이에요.","가온은 부분끼리 따로 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#4','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'sa','auto','⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C7","difficulty":3,"kind":"sa","stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["대분수는 먼저 가분수로 고쳐요.","⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","그래서 분자은 1이에요."],"mis":"M5-2-u2-X11","variant_rule":{"alt":[{"stem":"⟨1 3/7⟩ × ⟨2 1/3⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["대분수는 먼저 가분수로 고쳐요.","⟨1 3/7⟩ × ⟨2 1/3⟩ = ⟨10/7⟩ × ⟨7/3⟩ = ⟨70/21⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","그래서 분자은 1이에요."]},{"stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하여 기약분수인 대분수로 나타냈을 때 분자은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대분수는 먼저 가분수로 고쳐요.","⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","그래서 분자은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#5','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'sa','auto','5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C7","difficulty":3,"kind":"sa","stem":"5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["남학생은 96 × ⟨3/4⟩ = 72명이에요.","그 가운데 ⟨5/8⟩니 72 × ⟨5/8⟩ = 45명이에요.","한 번에 96 × ⟨3/4⟩ × ⟨5/8⟩ = 45로 구해도 같아요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"5학년 학생 180명 가운데 ⟨2/3⟩가 남학생이고, 남학생 가운데 ⟨3/4⟩이 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["남학생은 180 × ⟨2/3⟩ = 120명이에요.","그 가운데 ⟨3/4⟩이니 120 × ⟨3/4⟩ = 90명이에요.","한 번에 180 × ⟨2/3⟩ × ⟨3/4⟩ = 90으로 구해도 같아요."]},{"stem":"5학년 학생 150명 가운데 ⟨3/5⟩이 남학생이고, 남학생 가운데 ⟨4/9⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["남학생은 150 × ⟨3/5⟩ = 90명이에요.","그 가운데 ⟨4/9⟩니 90 × ⟨4/9⟩ = 40명이에요.","한 번에 150 × ⟨3/5⟩ × ⟨4/9⟩ = 40으로 구해도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#6','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'ox','auto','⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩는 앞의 두 수만 곱하면 끝나요.',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":6,"concept":"M5-2-u2-C7","difficulty":3,"kind":"ox","stem":"⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩는 앞의 두 수만 곱하면 끝나요.","answer":"X","reason_options":[{"t":"세 분수 모두 분모끼리·분자끼리 곱해야 하므로","correct":true},{"t":"세 번째 수는 더하면 되므로","mis":"M5-2-u2-X17"}],"mis":"M5-2-u2-X17","explanation":["⟨1/2⟩ × ⟨2/3⟩ = ⟨1/3⟩이에요.","여기에 ⟨5/7⟩를 곱해야 해요.","⟨1/3⟩ × ⟨5/7⟩ = ⟨5/21⟩예요."],"variant_rule":{"alt":[{"stem":"세 분수의 곱셈은 먼저 약분한 다음 한 번에 곱해도 답이 같아요.","answer":"O","reason_options":[{"t":"분모끼리·분자끼리 곱하는 한 규칙 위에 있으므로","correct":true},{"t":"약분은 두 수 사이에서만 할 수 있으므로","mis":"M5-2-u2-X13"}],"explanation":["5 × ⟨7/10⟩ × ⟨3/14⟩에서 5 = ⟨5/1⟩로 봐요.","약분하면 ⟨1/1⟩ × ⟨1/2⟩ × ⟨3/2⟩이에요.","5 × ⟨7/10⟩ × ⟨3/14⟩ = ⟨3/4⟩ — 맞아요."]},{"stem":"⟨2/5⟩ × 3에서 3을 ⟨3/3⟩으로 보고 계산해도 돼요.","answer":"X","reason_options":[{"t":"3은 ⟨3/1⟩이고, ⟨3/3⟩은 1이므로","correct":true},{"t":"자연수는 분모와 분자가 같은 분수이므로","mis":"M5-2-u2-X14"}],"explanation":["⟨3/3⟩ = 1이에요.","3은 분모가 1인 분수 ⟨3/1⟩이에요.","⟨2/5⟩ × ⟨3/1⟩ = ⟨6/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#7','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'mc','auto','⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/36⟩","correct":true},{"t":"⟨84/21⟩","mis":"M5-2-u2-X09"},{"t":"⟨14/3024⟩","mis":"M5-2-u2-X10"},{"t":"⟨7/48⟩","mis":"M5-2-u2-X17"}],"explanation":["분수가 셋이어도 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩ = ⟨84/3024⟩ = ⟨1/36⟩이에요.","앞의 두 수만 곱하고 멈추지 않도록 해요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨2/9⟩ × ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/7⟩","correct":true},{"t":"⟨36/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨11/252⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/6⟩","mis":"M5-2-u2-X17"}],"explanation":["분수가 셋이어도 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3/4⟩ × ⟨2/9⟩ × ⟨6/7⟩ = ⟨36/252⟩ = ⟨1/7⟩이에요.","앞의 두 수만 곱하고 멈추지 않도록 해요."]},{"stem":"⟨5/6⟩ × ⟨3/10⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨60/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨12/300⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X17"}],"explanation":["분수가 셋이어도 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨5/6⟩ × ⟨3/10⟩ × ⟨4/5⟩ = ⟨60/300⟩ = ⟨1/5⟩이에요.","앞의 두 수만 곱하고 멈추지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#8','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',4,'mc','auto','⟨2 1/2⟩ × ⟨1 1/5⟩과 ⟨1 3/4⟩ × ⟨1 2/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X11']::text[],true,'{"seq":8,"concept":"M5-2-u2-C7","difficulty":4,"kind":"mc","stem":"⟨2 1/2⟩ × ⟨1 1/5⟩과 ⟨1 3/4⟩ × ⟨1 2/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2 1/2⟩ × ⟨1 1/5⟩","correct":true},{"t":"⟨1 3/4⟩ × ⟨1 2/3⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X11"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/2⟩ × ⟨1 1/5⟩ = ⟨5/2⟩ × ⟨6/5⟩ = ⟨30/10⟩ = 3이에요.","⟨1 3/4⟩ × ⟨1 2/3⟩ = ⟨7/4⟩ × ⟨5/3⟩ = ⟨35/12⟩ = ⟨2 11/12⟩이에요.","3 > ⟨2 11/12⟩이라 ⟨2 1/2⟩ × ⟨1 1/5⟩이 더 커요."],"variant_rule":{"alt":[{"stem":"⟨1 1/2⟩ × ⟨2 2/3⟩와 ⟨2 1/3⟩ × ⟨1 4/5⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨2 1/3⟩ × ⟨1 4/5⟩","correct":true},{"t":"⟨1 1/2⟩ × ⟨2 2/3⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X11"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/2⟩ × ⟨2 2/3⟩ = ⟨3/2⟩ × ⟨8/3⟩ = ⟨24/6⟩ = 4예요.","⟨2 1/3⟩ × ⟨1 4/5⟩ = ⟨7/3⟩ × ⟨9/5⟩ = ⟨63/15⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","4 < ⟨4 1/5⟩이라 ⟨2 1/3⟩ × ⟨1 4/5⟩가 더 커요."]},{"stem":"⟨1 3/5⟩ × ⟨2 1/2⟩과 ⟨1 1/4⟩ × ⟨3 1/3⟩ 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨1 1/4⟩ × ⟨3 1/3⟩","correct":true},{"t":"⟨1 3/5⟩ × ⟨2 1/2⟩","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X11"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨1 3/5⟩ × ⟨2 1/2⟩ = ⟨8/5⟩ × ⟨5/2⟩ = ⟨40/10⟩ = 4예요.","⟨1 1/4⟩ × ⟨3 1/3⟩ = ⟨5/4⟩ × ⟨10/3⟩ = ⟨50/12⟩ = ⟨25/6⟩ = ⟨4 1/6⟩이에요.","4 < ⟨4 1/6⟩이라 ⟨1 1/4⟩ × ⟨3 1/3⟩이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#9','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',4,'sa','auto','⟨1 1/2⟩ × ⟨2/3⟩ × ⟨3/4⟩을 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C7","difficulty":4,"kind":"sa","stem":"⟨1 1/2⟩ × ⟨2/3⟩ × ⟨3/4⟩을 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨1 1/2⟩ × ⟨2/3⟩ × ⟨3/4⟩ = ⟨3/2⟩ × ⟨2/3⟩ × ⟨3/4⟩ = ⟨18/24⟩ = ⟨3/4⟩이에요.","그래서 분자는 3이에요."],"mis":"M5-2-u2-X12","variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ × ⟨4/5⟩ × ⟨5/6⟩를 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨2 1/4⟩ × ⟨4/5⟩ × ⟨5/6⟩ = ⟨9/4⟩ × ⟨4/5⟩ × ⟨5/6⟩ = ⟨180/120⟩ = ⟨3/2⟩ = ⟨1 1/2⟩이에요.","그래서 분자는 3이에요."]},{"stem":"⟨1 2/3⟩ × ⟨3/5⟩ × ⟨7/8⟩을 계산하여 기약분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수는 분모가 1인 분수로, 대분수는 가분수로 보고 분모끼리·분자끼리 곱해요.","⟨1 2/3⟩ × ⟨3/5⟩ × ⟨7/8⟩ = ⟨5/3⟩ × ⟨3/5⟩ × ⟨7/8⟩ = ⟨105/120⟩ = ⟨7/8⟩이에요.","그래서 분자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L07_challenge#10','math',5,2,'u2','L07','g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',4,'essay','teacher','⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하는 과정을 쓰고, 자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨4/5⟩를 곱해 더하면 안 되는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C7","difficulty":4,"kind":"essay","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하는 과정을 쓰고, 자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨4/5⟩를 곱해 더하면 안 되는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 대분수를 가분수로 고치면 ⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩이다. ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이다. 자연수끼리, 분수끼리만 곱하면 3 + ⟨4/10⟩ = ⟨3 4/10⟩가 되는데, 이것은 3 × ⟨4/5⟩이나 ⟨1/2⟩ × 1 같은 부분을 빠뜨려 실제 값 ⟨6 3/10⟩보다 작아진다. 그래서 대분수는 가분수로 고쳐 분모끼리·분자끼리 곱해야 한다.","scoring_points":["두 대분수를 ⟨7/2⟩, ⟨9/5⟩로 고쳤는가","⟨6 3/10⟩(= ⟨63/10⟩)을 구했는가","따로 곱하면 빠지는 부분이 생긴다고 설명했는가"]},"explanation":["⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩예요.","⟨7/2⟩ × ⟨9/5⟩ = ⟨6 3/10⟩이에요.","따로 곱하면 빠지는 부분이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#1','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'mc','auto','서연이네 마을에서는 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 공공 도서관을 만들려고 해요. 지금까지 58명이 동의했어요. 적어도 몇 명이 더 동의해야 하는지 구하려면 더 알아야 하는 것은 어느 것인가요?',ARRAY['M5-2-u2-X16']::text[],true,'{"seq":1,"concept":"M5-2-u2-C8","difficulty":1,"kind":"mc","stem":"서연이네 마을에서는 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 공공 도서관을 만들려고 해요. 지금까지 58명이 동의했어요. 적어도 몇 명이 더 동의해야 하는지 구하려면 더 알아야 하는 것은 어느 것인가요?","options":[{"t":"전체 주민 수","correct":true},{"t":"동의한 사람의 이름","mis":"M5-2-u2-X16"},{"t":"마을의 넓이","mis":"M5-2-u2-X16"},{"t":"공공 도서관의 크기","mis":"M5-2-u2-X16"}],"explanation":["「전체의 ⟨2/3⟩」를 구하려면 전체가 몇 명인지 알아야 해요.","동의한 수 58명만으로는 최소로 필요한 수를 구할 수 없어요.","그래서 전체 주민 수가 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"준기네 마을에서는 전체 주민의 ⟨3/5⟩ 이상이 동의한 곳으로 어린이 놀이 공간을 만들려고 해요. 지금까지 45명이 동의했어요. 적어도 몇 명이 더 동의해야 하는지 구하려면 더 알아야 하는 것은 어느 것인가요?","options":[{"t":"전체 주민 수","correct":true},{"t":"동의한 사람의 이름","mis":"M5-2-u2-X16"},{"t":"마을의 넓이","mis":"M5-2-u2-X16"},{"t":"어린이 놀이 공간의 크기","mis":"M5-2-u2-X16"}],"explanation":["「전체의 ⟨3/5⟩」을 구하려면 전체가 몇 명인지 알아야 해요.","동의한 수 45명만으로는 최소로 필요한 수를 구할 수 없어요.","그래서 전체 주민 수가 더 있어야 해요."]},{"stem":"하린이네 마을에서는 전체 주민의 ⟨3/4⟩ 이상이 동의한 곳으로 작은 체육관을 만들려고 해요. 지금까지 50명이 동의했어요. 적어도 몇 명이 더 동의해야 하는지 구하려면 더 알아야 하는 것은 어느 것인가요?","options":[{"t":"전체 주민 수","correct":true},{"t":"동의한 사람의 이름","mis":"M5-2-u2-X16"},{"t":"마을의 넓이","mis":"M5-2-u2-X16"},{"t":"작은 체육관의 크기","mis":"M5-2-u2-X16"}],"explanation":["「전체의 ⟨3/4⟩」을 구하려면 전체가 몇 명인지 알아야 해요.","동의한 수 50명만으로는 최소로 필요한 수를 구할 수 없어요.","그래서 전체 주민 수가 더 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#2','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'sa','auto','서연이네 마을 전체 주민은 90명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"서연이네 마을 전체 주민은 90명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["60"],"explanation":["전체 90명의 ⟨2/3⟩ 이상이에요.","90 × ⟨2/3⟩ = 60(명)이에요.","적어도 60명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 80명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["48"],"explanation":["전체 80명의 ⟨3/5⟩ 이상이에요.","80 × ⟨3/5⟩ = 48(명)이에요.","적어도 48명이 동의해야 해요."]},{"stem":"하린이네 마을 전체 주민은 72명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["54"],"explanation":["전체 72명의 ⟨3/4⟩ 이상이에요.","72 × ⟨3/4⟩ = 54(명)이에요.","적어도 54명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#3','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'ox','auto','「전체의 ⟨2/3⟩ 이상」을 구할 때는 곱셈을 써요.',ARRAY['M5-2-u2-X15']::text[],true,'{"seq":3,"concept":"M5-2-u2-C8","difficulty":1,"kind":"ox","stem":"「전체의 ⟨2/3⟩ 이상」을 구할 때는 곱셈을 써요.","answer":"O","reason_options":[{"t":"전체의 ⟨2/3⟩는 (전체) × ⟨2/3⟩이므로","correct":true},{"t":"전체에 3을 더해야 하므로","mis":"M5-2-u2-X15"}],"mis":"M5-2-u2-X15","explanation":["전체 270명의 ⟨2/3⟩는 270 × ⟨2/3⟩예요.","270 × ⟨2/3⟩ = 180이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"전체 90명의 ⟨2/3⟩ 이상이 동의해야 할 때, 적어도 60명이 동의해야 해요.","answer":"O","reason_options":[{"t":"90 × ⟨2/3⟩ = 60이므로","correct":true},{"t":"90 − 30 = 60이므로","mis":"M5-2-u2-X07"}],"explanation":["90을 똑같이 3으로 나누면 30이에요.","그중의 2니 60이에요.","90 × ⟨2/3⟩ = 60 — 맞아요."]},{"stem":"최소로 동의해야 하는 수가 48명이고 지금까지 40명이 동의했으면, 8명이 더 동의해야 해요.","answer":"O","reason_options":[{"t":"48 − 40 = 8이므로","correct":true},{"t":"48 + 40 = 88이므로","mis":"M5-2-u2-X16"}],"explanation":["더 필요한 수는 (최소로 필요한 수) − (지금까지 동의한 수)예요.","48 − 40 = 8이에요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#4','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'sa','auto','서연이네 마을 전체 주민은 90명이고, 지금까지 52명이 공공 도서관 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"서연이네 마을 전체 주민은 90명이고, 지금까지 52명이 공공 도서관 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["아직 동의하지 않은 주민은 전체에서 동의한 수를 빼요.","90 − 52 = 38(명)이에요.","「더 동의해야 하는 수」와 다른 물음이에요 — 38명."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 80명이고, 지금까지 39명이 어린이 놀이 공간 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["아직 동의하지 않은 주민은 전체에서 동의한 수를 빼요.","80 − 39 = 41(명)이에요.","「더 동의해야 하는 수」와 다른 물음이에요 — 41명."]},{"stem":"하린이네 마을 전체 주민은 72명이고, 지금까지 47명이 작은 체육관 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["아직 동의하지 않은 주민은 전체에서 동의한 수를 빼요.","72 − 47 = 25(명)이에요.","「더 동의해야 하는 수」와 다른 물음이에요 — 25명."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#5','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'sa','auto','서연이네 마을 전체 주민은 90명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 52명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"서연이네 마을 전체 주민은 90명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 52명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["① 최소로 동의해야 하는 수: 90 × ⟨2/3⟩ = 60(명)이에요.","② 지금까지 52명이 동의했으니 60 − 52 = 8(명)이에요.","적어도 8명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 80명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 39명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["① 최소로 동의해야 하는 수: 80 × ⟨3/5⟩ = 48(명)이에요.","② 지금까지 39명이 동의했으니 48 − 39 = 9(명)이에요.","적어도 9명이 더 동의해야 해요."]},{"stem":"하린이네 마을 전체 주민은 72명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 47명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 72 × ⟨3/4⟩ = 54(명)이에요.","② 지금까지 47명이 동의했으니 54 − 47 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#6','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'mc','auto','서연이네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 공공 도서관을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X07']::text[],true,'{"seq":6,"concept":"M5-2-u2-C8","difficulty":2,"kind":"mc","stem":"서연이네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 공공 도서관을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"최소로 동의해야 하는 수를 곱셈으로 구한 뒤 동의한 수를 뺀다","correct":true},{"t":"동의한 수를 먼저 더한 뒤 전체로 나눈다","mis":"M5-2-u2-X16"},{"t":"전체 주민 수에서 동의한 수를 먼저 뺀다","mis":"M5-2-u2-X16"},{"t":"동의한 수에 분수를 곱한다","mis":"M5-2-u2-X07"}],"explanation":["① (전체 주민 수) × (분수)로 최소로 동의해야 하는 수를 구해요.","② 거기에서 지금까지 동의한 수를 빼요.","서연이네 마을 문제도 이 순서로 풀어요."],"variant_rule":{"alt":[{"stem":"준기네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 어린이 놀이 공간을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"최소로 동의해야 하는 수를 곱셈으로 구한 뒤 동의한 수를 뺀다","correct":true},{"t":"동의한 수를 먼저 더한 뒤 전체로 나눈다","mis":"M5-2-u2-X16"},{"t":"전체 주민 수에서 동의한 수를 먼저 뺀다","mis":"M5-2-u2-X16"},{"t":"동의한 수에 분수를 곱한다","mis":"M5-2-u2-X07"}],"explanation":["① (전체 주민 수) × (분수)로 최소로 동의해야 하는 수를 구해요.","② 거기에서 지금까지 동의한 수를 빼요.","준기네 마을 문제도 이 순서로 풀어요."]},{"stem":"하린이네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 작은 체육관을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"최소로 동의해야 하는 수를 곱셈으로 구한 뒤 동의한 수를 뺀다","correct":true},{"t":"동의한 수를 먼저 더한 뒤 전체로 나눈다","mis":"M5-2-u2-X16"},{"t":"전체 주민 수에서 동의한 수를 먼저 뺀다","mis":"M5-2-u2-X16"},{"t":"동의한 수에 분수를 곱한다","mis":"M5-2-u2-X07"}],"explanation":["① (전체 주민 수) × (분수)로 최소로 동의해야 하는 수를 구해요.","② 거기에서 지금까지 동의한 수를 빼요.","하린이네 마을 문제도 이 순서로 풀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#7','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'mc','auto','서연이네 마을 전체 주민은 90명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 63명이 동의했다면 공공 도서관을 만들 수 있나요?',ARRAY['M5-2-u2-X16','M5-2-u2-X07']::text[],true,'{"seq":7,"concept":"M5-2-u2-C8","difficulty":2,"kind":"mc","stem":"서연이네 마을 전체 주민은 90명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 63명이 동의했다면 공공 도서관을 만들 수 있나요?","options":[{"t":"만들 수 있다","correct":true},{"t":"아직 만들 수 없다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 90 × ⟨2/3⟩ = 60(명)이에요.","지금까지 63명이 동의했어요.","63명은 60명 이상이라 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 80명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 41명이 동의했다면 어린이 놀이 공간을 만들 수 있나요?","options":[{"t":"아직 만들 수 없다","correct":true},{"t":"만들 수 있다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 80 × ⟨3/5⟩ = 48(명)이에요.","지금까지 41명이 동의했어요.","7명이 더 필요해 아직 만들 수 없어요."]},{"stem":"하린이네 마을 전체 주민은 72명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 54명이 동의했다면 작은 체육관을 만들 수 있나요?","options":[{"t":"만들 수 있다","correct":true},{"t":"아직 만들 수 없다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 72 × ⟨3/4⟩ = 54(명)이에요.","지금까지 54명이 동의했어요.","54명은 54명 이상이라 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#8','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'sa','auto','도윤이네 마을 전체 주민은 84명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"도윤이네 마을 전체 주민은 84명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["63"],"explanation":["전체 84명의 ⟨3/4⟩ 이상이에요.","84 × ⟨3/4⟩ = 63(명)이에요.","적어도 63명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"가온이네 마을 전체 주민은 96명이에요. 전체 주민의 ⟨5/8⟩ 이상이 동의해야 반려견 놀이 마당을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["60"],"explanation":["전체 96명의 ⟨5/8⟩ 이상이에요.","96 × ⟨5/8⟩ = 60(명)이에요.","적어도 60명이 동의해야 해요."]},{"stem":"서연이네 마을 전체 주민은 75명이에요. 전체 주민의 ⟨4/5⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["60"],"explanation":["전체 75명의 ⟨4/5⟩ 이상이에요.","75 × ⟨4/5⟩ = 60(명)이에요.","적어도 60명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#9','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'ox','auto','전체 주민 수를 몰라도 적어도 몇 명이 더 동의해야 하는지 구할 수 있어요.',ARRAY['M5-2-u2-X16']::text[],true,'{"seq":9,"concept":"M5-2-u2-C8","difficulty":2,"kind":"ox","stem":"전체 주민 수를 몰라도 적어도 몇 명이 더 동의해야 하는지 구할 수 있어요.","answer":"X","reason_options":[{"t":"전체 주민 수가 있어야 최소로 필요한 수를 곱셈으로 구할 수 있으므로","correct":true},{"t":"동의한 수만 알면 되므로","mis":"M5-2-u2-X16"}],"mis":"M5-2-u2-X16","explanation":["최소로 동의해야 하는 수는 (전체) × (분수)예요.","전체를 모르면 곱셈을 할 수 없어요.","없는 정보부터 찾아야 해요."],"variant_rule":{"alt":[{"stem":"「⟨3/5⟩ 이상」이면 전체의 ⟨3/5⟩과 같은 수만큼 동의해도 돼요.","answer":"O","reason_options":[{"t":"「이상」은 그 수를 포함하므로","correct":true},{"t":"「이상」은 그 수보다 반드시 커야 하므로","mis":"M5-2-u2-X17"}],"explanation":["「이상」은 기준이 되는 수를 포함해요.","전체의 ⟨3/5⟩과 같은 수만큼 동의하면 조건을 채워요.","그래서 「적어도」 그 수만큼이에요."]},{"stem":"아직 동의하지 않은 주민 수와 더 동의해야 하는 주민 수는 늘 같아요.","answer":"X","reason_options":[{"t":"아직 동의하지 않은 수는 전체에서, 더 필요한 수는 최소 수에서 빼므로","correct":true},{"t":"두 수 모두 전체에서 동의한 수를 빼므로","mis":"M5-2-u2-X16"}],"explanation":["아직 동의하지 않은 수 = (전체) − (동의한 수)예요.","더 동의해야 하는 수 = (최소로 필요한 수) − (동의한 수)예요.","빼는 기준이 달라 보통 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_basic#10','math',5,2,'u2','L08','g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',3,'mc','auto','서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":10,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"준기네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 90 × ⟨2/3⟩ = 60, 60 − 52 = 8(명)이에요.","준기네 마을: 80 × ⟨3/5⟩ = 48, 48 − 39 = 9(명)이에요.","준기네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 60명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"하린이네 마을","correct":true},{"t":"도윤이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["하린이네 마을: 72 × ⟨3/4⟩ = 54, 54 − 47 = 7(명)이에요.","도윤이네 마을: 84 × ⟨3/4⟩ = 63, 63 − 60 = 3(명)이에요.","하린이네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"가온이네 마을은 주민 96명 가운데 ⟨5/8⟩ 이상, 서연이네 마을은 주민 75명 가운데 ⟨4/5⟩ 이상이 동의해야 해요. 지금까지 각각 49명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"가온이네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["가온이네 마을: 96 × ⟨5/8⟩ = 60, 60 − 49 = 11(명)이에요.","서연이네 마을: 75 × ⟨4/5⟩ = 60, 60 − 55 = 5(명)이에요.","가온이네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#1','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',2,'sa','auto','준기네 마을 전체 주민은 85명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 44명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"준기네 마을 전체 주민은 85명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 44명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 85 × ⟨3/5⟩ = 51(명)이에요.","② 지금까지 44명이 동의했으니 51 − 44 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"도윤이네 마을 전체 주민은 96명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 57명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 96 × ⟨2/3⟩ = 64(명)이에요.","② 지금까지 57명이 동의했으니 64 − 57 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]},{"stem":"가온이네 마을 전체 주민은 88명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 반려견 놀이 마당을 만들 수 있어요. 지금까지 55명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["① 최소로 동의해야 하는 수: 88 × ⟨3/4⟩ = 66(명)이에요.","② 지금까지 55명이 동의했으니 66 − 55 = 11(명)이에요.","적어도 11명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#2','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',2,'sa','auto','우리 반 학생 28명 가운데 ⟨3/4⟩ 이상이 찬성해야 체험 학습 장소를 바꿀 수 있어요. 지금까지 17명이 찬성했다면 적어도 몇 명이 더 찬성해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"우리 반 학생 28명 가운데 ⟨3/4⟩ 이상이 찬성해야 체험 학습 장소를 바꿀 수 있어요. 지금까지 17명이 찬성했다면 적어도 몇 명이 더 찬성해야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["최소로 찬성해야 하는 수: 28 × ⟨3/4⟩ = 21(명)이에요.","21 − 17 = 4(명)이에요.","적어도 4명이 더 찬성해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"우리 반 학생 30명 가운데 ⟨2/3⟩ 이상이 찬성해야 체험 학습 장소를 바꿀 수 있어요. 지금까지 14명이 찬성했다면 적어도 몇 명이 더 찬성해야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["최소로 찬성해야 하는 수: 30 × ⟨2/3⟩ = 20(명)이에요.","20 − 14 = 6(명)이에요.","적어도 6명이 더 찬성해야 해요."]},{"stem":"우리 반 학생 25명 가운데 ⟨3/5⟩ 이상이 찬성해야 체험 학습 장소를 바꿀 수 있어요. 지금까지 11명이 찬성했다면 적어도 몇 명이 더 찬성해야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["최소로 찬성해야 하는 수: 25 × ⟨3/5⟩ = 15(명)이에요.","15 − 11 = 4(명)이에요.","적어도 4명이 더 찬성해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#3','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'error','auto','서연이네 마을 전체 주민 90명의 ⟨2/3⟩ 이상이 동의해야 하고, 지금까지 52명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C8","difficulty":3,"kind":"error","stem":"서연이네 마을 전체 주민 90명의 ⟨2/3⟩ 이상이 동의해야 하고, 지금까지 52명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"수아 — 「90 − 52 = 38명이 더 동의해야 해.」","correct":true,"mis_target":"M5-2-u2-X16"},{"t":"도윤 — 「90 × ⟨2/3⟩ = 60명이 동의해야 해.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「60 − 52 = 8명이 더 동의해야 해.」","mis":"M5-2-u2-X17"}],"explanation":["먼저 최소로 동의해야 하는 수 90 × ⟨2/3⟩ = 60(명)을 구해요.","그다음 60 − 52 = 8(명)이에요.","수아는 전체에서 바로 빼서 「아직 동의하지 않은 수」를 구했어요."],"variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민 80명의 ⟨3/5⟩ 이상이 동의해야 하고, 지금까지 39명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"민준 — 「80 − 39 = 41명이 더 동의해야 해.」","correct":true,"mis_target":"M5-2-u2-X16"},{"t":"서연 — 「80 × ⟨3/5⟩ = 48명이 동의해야 해.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「48 − 39 = 9명이 더 동의해야 해.」","mis":"M5-2-u2-X17"}],"explanation":["먼저 최소로 동의해야 하는 수 80 × ⟨3/5⟩ = 48(명)을 구해요.","그다음 48 − 39 = 9(명)이에요.","민준은 전체에서 바로 빼서 「아직 동의하지 않은 수」를 구했어요."]},{"stem":"하린이네 마을 전체 주민 72명의 ⟨3/4⟩ 이상이 동의해야 하고, 지금까지 47명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"가온 — 「72 − 47 = 25명이 더 동의해야 해.」","correct":true,"mis_target":"M5-2-u2-X16"},{"t":"나린 — 「72 × ⟨3/4⟩ = 54명이 동의해야 해.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「54 − 47 = 7명이 더 동의해야 해.」","mis":"M5-2-u2-X17"}],"explanation":["먼저 최소로 동의해야 하는 수 72 × ⟨3/4⟩ = 54(명)을 구해요.","그다음 54 − 47 = 7(명)이에요.","가온은 전체에서 바로 빼서 「아직 동의하지 않은 수」를 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#4','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'sa','auto','서연이네 마을 전체 주민은 99명이고, 전체 주민의 ⟨5/9⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 46명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C8","difficulty":3,"kind":"sa","stem":"서연이네 마을 전체 주민은 99명이고, 전체 주민의 ⟨5/9⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 46명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["① 최소로 동의해야 하는 수: 99 × ⟨5/9⟩ = 55(명)이에요.","② 지금까지 46명이 동의했으니 55 − 46 = 9(명)이에요.","적어도 9명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 98명이고, 전체 주민의 ⟨4/7⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 49명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 98 × ⟨4/7⟩ = 56(명)이에요.","② 지금까지 49명이 동의했으니 56 − 49 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]},{"stem":"하린이네 마을 전체 주민은 91명이고, 전체 주민의 ⟨5/7⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 58명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 91 × ⟨5/7⟩ = 65(명)이에요.","② 지금까지 58명이 동의했으니 65 − 58 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#5','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'mc','auto','도윤이네 마을 전체 주민은 84명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 61명이 동의했다면 마을 텃밭을 만들 수 있나요?',ARRAY['M5-2-u2-X16','M5-2-u2-X07']::text[],true,'{"seq":5,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"도윤이네 마을 전체 주민은 84명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 61명이 동의했다면 마을 텃밭을 만들 수 있나요?","options":[{"t":"아직 만들 수 없다","correct":true},{"t":"만들 수 있다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 84 × ⟨3/4⟩ = 63(명)이에요.","지금까지 61명이 동의했어요.","2명이 더 필요해 아직 만들 수 없어요."],"variant_rule":{"alt":[{"stem":"가온이네 마을 전체 주민은 96명이고, 전체 주민의 ⟨5/8⟩ 이상이 동의해야 반려견 놀이 마당을 만들 수 있어요. 지금까지 60명이 동의했다면 반려견 놀이 마당을 만들 수 있나요?","options":[{"t":"만들 수 있다","correct":true},{"t":"아직 만들 수 없다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 96 × ⟨5/8⟩ = 60(명)이에요.","지금까지 60명이 동의했어요.","60명은 60명 이상이라 만들 수 있어요."]},{"stem":"준기네 마을 전체 주민은 85명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 52명이 동의했다면 어린이 놀이 공간을 만들 수 있나요?","options":[{"t":"만들 수 있다","correct":true},{"t":"아직 만들 수 없다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 85 × ⟨3/5⟩ = 51(명)이에요.","지금까지 52명이 동의했어요.","52명은 51명 이상이라 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#6','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'ox','auto','아직 동의하지 않은 주민 수와 더 동의해야 하는 주민 수는 늘 같아요.',ARRAY['M5-2-u2-X16']::text[],true,'{"seq":6,"concept":"M5-2-u2-C8","difficulty":3,"kind":"ox","stem":"아직 동의하지 않은 주민 수와 더 동의해야 하는 주민 수는 늘 같아요.","answer":"X","reason_options":[{"t":"아직 동의하지 않은 수는 전체에서, 더 필요한 수는 최소 수에서 빼므로","correct":true},{"t":"두 수 모두 전체에서 동의한 수를 빼므로","mis":"M5-2-u2-X16"}],"mis":"M5-2-u2-X16","explanation":["아직 동의하지 않은 수 = (전체) − (동의한 수)예요.","더 동의해야 하는 수 = (최소로 필요한 수) − (동의한 수)예요.","빼는 기준이 달라 보통 달라요."],"variant_rule":{"alt":[{"stem":"「⟨3/5⟩ 이상」이면 전체의 ⟨3/5⟩과 같은 수만큼 동의해도 돼요.","answer":"O","reason_options":[{"t":"「이상」은 그 수를 포함하므로","correct":true},{"t":"「이상」은 그 수보다 반드시 커야 하므로","mis":"M5-2-u2-X17"}],"explanation":["「이상」은 기준이 되는 수를 포함해요.","전체의 ⟨3/5⟩과 같은 수만큼 동의하면 조건을 채워요.","그래서 「적어도」 그 수만큼이에요."]},{"stem":"전체 주민 수를 몰라도 적어도 몇 명이 더 동의해야 하는지 구할 수 있어요.","answer":"X","reason_options":[{"t":"전체 주민 수가 있어야 최소로 필요한 수를 곱셈으로 구할 수 있으므로","correct":true},{"t":"동의한 수만 알면 되므로","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 (전체) × (분수)예요.","전체를 모르면 곱셈을 할 수 없어요.","없는 정보부터 찾아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#7','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'mc','auto','준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":7,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"도윤이네 마을","correct":true},{"t":"준기네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["준기네 마을: 85 × ⟨3/5⟩ = 51, 51 − 44 = 7(명)이에요.","도윤이네 마을: 96 × ⟨2/3⟩ = 64, 64 − 55 = 9(명)이에요.","도윤이네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"가온이네 마을은 주민 88명 가운데 ⟨3/4⟩ 이상, 하린이네 마을은 주민 91명 가운데 ⟨5/7⟩ 이상이 동의해야 해요. 지금까지 각각 55명, 58명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"가온이네 마을","correct":true},{"t":"하린이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["가온이네 마을: 88 × ⟨3/4⟩ = 66, 66 − 55 = 11(명)이에요.","하린이네 마을: 91 × ⟨5/7⟩ = 65, 65 − 58 = 7(명)이에요.","가온이네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"서연이네 마을은 주민 99명 가운데 ⟨5/9⟩ 이상, 준기네 마을은 주민 98명 가운데 ⟨4/7⟩ 이상이 동의해야 해요. 지금까지 각각 46명, 49명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"서연이네 마을","correct":true},{"t":"준기네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 99 × ⟨5/9⟩ = 55, 55 − 46 = 9(명)이에요.","준기네 마을: 98 × ⟨4/7⟩ = 56, 56 − 49 = 7(명)이에요.","서연이네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#8','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',4,'sa','auto','서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 두 마을에서 적어도 더 동의해야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":4,"kind":"sa","stem":"서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 두 마을에서 적어도 더 동의해야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["서연이네 마을: 90 × ⟨2/3⟩ = 60, 60 − 52 = 8(명)이에요.","준기네 마을: 80 × ⟨3/5⟩ = 48, 48 − 39 = 9(명)이에요.","모두 8 + 9 = 17(명)이에요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 가온이네 마을은 주민 96명 가운데 ⟨5/8⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 49명이 동의했어요. 두 마을에서 적어도 더 동의해야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["하린이네 마을: 72 × ⟨3/4⟩ = 54, 54 − 47 = 7(명)이에요.","가온이네 마을: 96 × ⟨5/8⟩ = 60, 60 − 49 = 11(명)이에요.","모두 7 + 11 = 18(명)이에요."]},{"stem":"도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상, 서연이네 마을은 주민 75명 가운데 ⟨4/5⟩ 이상이 동의해야 해요. 지금까지 각각 60명, 55명이 동의했어요. 두 마을에서 적어도 더 동의해야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["도윤이네 마을: 84 × ⟨3/4⟩ = 63, 63 − 60 = 3(명)이에요.","서연이네 마을: 75 × ⟨4/5⟩ = 60, 60 − 55 = 5(명)이에요.","모두 3 + 5 = 8(명)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#9','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',4,'sa','auto','서연이네 마을 전체 주민은 90명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 52명이 동의했고, 앞으로 하루에 2명씩 더 동의한다면 적어도 며칠이 지나야 공공 도서관을 만들 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C8","difficulty":4,"kind":"sa","stem":"서연이네 마을 전체 주민은 90명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 52명이 동의했고, 앞으로 하루에 2명씩 더 동의한다면 적어도 며칠이 지나야 공공 도서관을 만들 수 있나요? 숫자로 쓰세요.","answer":["4"],"explanation":["최소로 동의해야 하는 수: 90 × ⟨2/3⟩ = 60(명), 더 필요한 수: 60 − 52 = 8(명)이에요.","하루에 2명씩이면 4일에 8명이 더 동의해요.","4일이 지나면 8명 이상이 되어 만들 수 있어요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 80명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 39명이 동의했고, 앞으로 하루에 3명씩 더 동의한다면 적어도 며칠이 지나야 어린이 놀이 공간을 만들 수 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["최소로 동의해야 하는 수: 80 × ⟨3/5⟩ = 48(명), 더 필요한 수: 48 − 39 = 9(명)이에요.","하루에 3명씩이면 3일에 9명이 더 동의해요.","3일이 지나면 9명 이상이 되어 만들 수 있어요."]},{"stem":"하린이네 마을 전체 주민은 72명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 47명이 동의했고, 앞으로 하루에 2명씩 더 동의한다면 적어도 며칠이 지나야 작은 체육관을 만들 수 있나요? 숫자로 쓰세요.","answer":["4"],"explanation":["최소로 동의해야 하는 수: 72 × ⟨3/4⟩ = 54(명), 더 필요한 수: 54 − 47 = 7(명)이에요.","하루에 2명씩이면 4일에 8명이 더 동의해요.","4일이 지나면 7명 이상이 되어 만들 수 있어요. — 3일로는 6명이라 모자라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_L08_challenge#10','math',5,2,'u2','L08','g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',4,'essay','teacher','서연이네 마을에서는 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들어요. 전체 주민은 90명이고 지금까지 52명이 동의했어요. 적어도 몇 명이 더 동의해야 하는지 푸는 순서대로 쓰고, 처음에 전체 주민 수가 꼭 필요한 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C8","difficulty":4,"kind":"essay","stem":"서연이네 마을에서는 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들어요. 전체 주민은 90명이고 지금까지 52명이 동의했어요. 적어도 몇 명이 더 동의해야 하는지 푸는 순서대로 쓰고, 처음에 전체 주민 수가 꼭 필요한 까닭도 쓰세요.","answer_guide":{"answer":"예: ① 최소로 동의해야 하는 수는 90 × ⟨2/3⟩ = 60(명)이다. ② 지금까지 52명이 동의했으므로 60 − 52 = 8(명)이 더 동의해야 한다. 「전체의 ⟨2/3⟩」를 곱셈으로 구하려면 곱할 전체가 있어야 하므로 전체 주민 수를 모르면 풀 수 없다.","scoring_points":["90 × ⟨2/3⟩ = 60(명)을 구했는가","60 − 52 = 8(명)을 구했는가","전체 수가 있어야 곱셈을 할 수 있다고 썼는가"]},"explanation":["90 × ⟨2/3⟩ = 60(명)이에요.","60 − 52 = 8(명)이에요.","전체 수를 알아야 곱셈을 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#1','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C1',1,'mc','auto','⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨2/9⟩ × 3","correct":true},{"t":"⟨2/9⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨2/9⟩ + 3","mis":"M5-2-u2-X15"},{"t":"2 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨2/9⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨2/9⟩ × 3이에요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨3/8⟩ × 4","correct":true},{"t":"⟨3/8⟩ × 5","mis":"M5-2-u2-X17"},{"t":"⟨3/8⟩ + 4","mis":"M5-2-u2-X15"},{"t":"3 × 4","mis":"M5-2-u2-X15"}],"explanation":["⟨3/8⟩을 4번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ = ⟨3/8⟩ × 4예요."]},{"stem":"⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩ × 5","correct":true},{"t":"⟨1/6⟩ × 6","mis":"M5-2-u2-X17"},{"t":"⟨1/6⟩ + 5","mis":"M5-2-u2-X15"},{"t":"1 × 5","mis":"M5-2-u2-X15"}],"explanation":["⟨1/6⟩을 5번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ = ⟨1/6⟩ × 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#2','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',1,'sa','auto','⟨2/7⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C2","difficulty":1,"kind":"sa","stem":"⟨2/7⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 2 × 3 = 6이에요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨3/10⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 3 × 3 = 9예요.","⟨3/10⟩ × 3 = ⟨9/10⟩예요."]},{"stem":"⟨1/8⟩ × 7을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 1 × 7 = 7이에요.","⟨1/8⟩ × 7 = ⟨7/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#3','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',1,'mc','auto','⟨2 1/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨2 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/4⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨1/4⟩을 더하면 분자는 8 + 1 = 9예요.","⟨2 1/4⟩ = ⟨9/4⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/7⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/7⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨7/7⟩이에요 — 1 × 7 = 7.","여기에 ⟨2/7⟩를 더하면 분자는 7 + 2 = 9예요.","⟨1 2/7⟩ = ⟨9/7⟩예요."]},{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"⟨4/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨3/3⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#4','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C4',1,'sa','auto','8의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"8의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["8을 똑같이 4로 나누면 한 묶음은 8 ÷ 4 = 2예요.","그중의 3이니 2 × 3 = 6이에요.","식으로는 8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"9의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9를 똑같이 3으로 나누면 한 묶음은 9 ÷ 3 = 3이에요.","그중의 2니 3 × 2 = 6이에요.","식으로는 9 × ⟨2/3⟩ = ⟨18/3⟩ = 6이에요."]},{"stem":"10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10을 똑같이 5로 나누면 한 묶음은 10 ÷ 5 = 2예요.","그중의 1이니 2 × 1 = 2예요.","식으로는 10 × ⟨1/5⟩ = ⟨10/5⟩ = 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#5','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',1,'mc','auto','4 × ⟨3/5⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"4 × ⟨3/5⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"4보다 작다","correct":true},{"t":"4보다 크다","mis":"M5-2-u2-X08"},{"t":"4와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨3/5⟩이 1보다 작아요.","4 × ⟨3/5⟩ = ⟨2 2/5⟩예요.","그래서 「4보다 작다」예요."],"variant_rule":{"alt":[{"stem":"8 × ⟨1 2/7⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"8보다 크다","correct":true},{"t":"8보다 작다","mis":"M5-2-u2-X08"},{"t":"8과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 2/7⟩가 1보다 커요.","8 × ⟨1 2/7⟩ = ⟨10 2/7⟩예요.","그래서 「8보다 크다」예요."]},{"stem":"9 × ⟨4/9⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"9보다 작다","correct":true},{"t":"9보다 크다","mis":"M5-2-u2-X08"},{"t":"9와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨4/9⟩가 1보다 작아요.","9 × ⟨4/9⟩ = 4예요.","그래서 「9보다 작다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#6','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',1,'mc','auto','⟨1/3⟩ × ⟨1/5⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/3⟩ × ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/15⟩","correct":true},{"t":"⟨2/15⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/8⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 3등분 한 것 중의 1을 다시 5등분 해요.","전체는 3 × 5 = 15칸이 되고, 그중의 1칸이에요.","⟨1/3⟩ × ⟨1/5⟩ = ⟨1/15⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ × ⟨1/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/18⟩","correct":true},{"t":"⟨2/18⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 2등분 한 것 중의 1을 다시 9등분 해요.","전체는 2 × 9 = 18칸이 되고, 그중의 1칸이에요.","⟨1/2⟩ × ⟨1/9⟩ = ⟨1/18⟩이에요."]},{"stem":"⟨1/6⟩ × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/24⟩","correct":true},{"t":"⟨2/24⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 6등분 한 것 중의 1을 다시 4등분 해요.","전체는 6 × 4 = 24칸이 되고, 그중의 1칸이에요.","⟨1/6⟩ × ⟨1/4⟩ = ⟨1/24⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#7','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',1,'sa','auto','⟨2 3/4⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨2 3/4⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 2는 ⟨8/4⟩이에요.","분자는 2 × 4 + 3 = 11이에요.","⟨2 3/4⟩ = ⟨11/4⟩이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨1 5/6⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 1은 ⟨6/6⟩이에요.","분자는 1 × 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]},{"stem":"⟨4 1/3⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["자연수 4는 ⟨12/3⟩예요.","분자는 4 × 3 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#8','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C8',1,'sa','auto','서연이네 마을 전체 주민은 60명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"서연이네 마을 전체 주민은 60명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 60명의 ⟨2/3⟩ 이상이에요.","60 × ⟨2/3⟩ = 40(명)이에요.","적어도 40명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 70명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["42"],"explanation":["전체 70명의 ⟨3/5⟩ 이상이에요.","70 × ⟨3/5⟩ = 42(명)이에요.","적어도 42명이 동의해야 해요."]},{"stem":"하린이네 마을 전체 주민은 64명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["48"],"explanation":["전체 64명의 ⟨3/4⟩ 이상이에요.","64 × ⟨3/4⟩ = 48(명)이에요.","적어도 48명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#9','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',2,'mc','auto','⟨3/7⟩ × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨3/7⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/28⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/28⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/7⟩ × 4 = ⟨12/7⟩ = ⟨1 5/7⟩예요.","한 칸의 크기 ⟨1/7⟩은 그대로이고 칸의 수만 4배가 돼요."],"variant_rule":{"alt":[{"stem":"⟨5/9⟩ × 2를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/9⟩","correct":true},{"t":"⟨10/18⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/18⟩","mis":"M5-2-u2-X02"},{"t":"⟨7/9⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/9⟩ × 2 = ⟨10/9⟩ = ⟨1 1/9⟩이에요.","한 칸의 크기 ⟨1/9⟩은 그대로이고 칸의 수만 2배가 돼요."]},{"stem":"⟨2/3⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/3⟩ × 5 = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","한 칸의 크기 ⟨1/3⟩은 그대로이고 칸의 수만 5배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#10','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',2,'mc','auto','⟨1 2/3⟩ × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨1 2/3⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨6 2/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 2/3⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨1 2/3⟩ × 4 = ⟨5/3⟩ × 4 = ⟨20/3⟩ = ⟨6 2/3⟩예요.","자연수 부분으로 갈라도 1 × 4 + ⟨2/3⟩ × 4 = ⟨6 2/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"⟨2 1/5⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/5⟩","correct":true},{"t":"⟨6 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 3/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/5⟩ = ⟨11/5⟩이에요.","⟨2 1/5⟩ × 3 = ⟨11/5⟩ × 3 = ⟨33/5⟩ = ⟨6 3/5⟩이에요.","자연수 부분으로 갈라도 2 × 3 + ⟨1/5⟩ × 3 = ⟨6 3/5⟩으로 같아요."]},{"stem":"⟨1 1/8⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/4⟩","correct":true},{"t":"⟨6 1/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/8⟩ = ⟨9/8⟩예요.","⟨1 1/8⟩ × 6 = ⟨9/8⟩ × 6 = ⟨54/8⟩ = ⟨27/4⟩ = ⟨6 3/4⟩이에요.","자연수 부분으로 갈라도 1 × 6 + ⟨1/8⟩ × 6 = ⟨6 3/4⟩으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#11','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C4',2,'mc','auto','5 × ⟨2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X07']::text[],true,'{"seq":11,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"5 × ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"10","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","5를 똑같이 3으로 나눈 것 중의 2만큼이에요."],"variant_rule":{"alt":[{"stem":"3 × ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/21⟩","mis":"M5-2-u2-X02"},{"t":"12","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨4/7⟩ = ⟨12/7⟩ = ⟨1 5/7⟩예요.","3을 똑같이 7로 나눈 것 중의 4만큼이에요."]},{"stem":"6 × ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨30/48⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/48⟩","mis":"M5-2-u2-X02"},{"t":"30","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","6 × ⟨5/8⟩ = ⟨30/8⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","6을 똑같이 8로 나눈 것 중의 5만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#12','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',2,'mc','auto','3 × ⟨1 1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":12,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"3 × ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/4⟩ = ⟨5/4⟩예요.","3 × ⟨1 1/4⟩ = 3 × ⟨5/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","둘로 갈라도 3 × 1 + 3 × ⟨1/4⟩ = ⟨3 3/4⟩으로 같아요."],"variant_rule":{"alt":[{"stem":"2 × ⟨2 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 2/3⟩ = ⟨8/3⟩이에요.","2 × ⟨2 2/3⟩ = 2 × ⟨8/3⟩ = ⟨16/3⟩ = ⟨5 1/3⟩이에요.","둘로 갈라도 2 × 2 + 2 × ⟨2/3⟩ = ⟨5 1/3⟩로 같아요."]},{"stem":"5 × ⟨1 2/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/7⟩","correct":true},{"t":"⟨5 2/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 3/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/7⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/7⟩ = ⟨9/7⟩예요.","5 × ⟨1 2/7⟩ = 5 × ⟨9/7⟩ = ⟨45/7⟩ = ⟨6 3/7⟩이에요.","둘로 갈라도 5 × 1 + 5 × ⟨2/7⟩ = ⟨6 3/7⟩으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#13','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',2,'mc','auto','⟨2/3⟩ × ⟨4/5⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":13,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨2/3⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨10/12⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이에요.","전체 15칸 가운데 8칸이라고 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨5/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/21⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨15/7⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨5/7⟩ × ⟨1/3⟩ = ⟨5/21⟩예요.","전체 21칸 가운데 5칸이라고 볼 수 있어요."]},{"stem":"⟨3/4⟩ × ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/9⟩","mis":"M5-2-u2-X09"},{"t":"⟨27/8⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3/4⟩ × ⟨2/9⟩ = ⟨6/36⟩ = ⟨1/6⟩이에요.","전체 36칸 가운데 6칸이라고 볼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#14','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',2,'mc','auto','⟨1 1/2⟩ × ⟨2 2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04','M5-2-u2-X12']::text[],true,'{"seq":14,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨1 1/2⟩ × ⟨2 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"},{"t":"5","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 1/2⟩ = ⟨3/2⟩, ⟨2 2/3⟩ = ⟨8/3⟩.","분모끼리, 분자끼리 곱해요.","⟨1 1/2⟩ × ⟨2 2/3⟩ = ⟨3/2⟩ × ⟨8/3⟩ = ⟨24/6⟩ = 4예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ × ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 1/12⟩","mis":"M5-2-u2-X11"},{"t":"1","mis":"M5-2-u2-X04"},{"t":"4","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩, ⟨1 1/3⟩ = ⟨4/3⟩.","분모끼리, 분자끼리 곱해요.","⟨2 1/4⟩ × ⟨1 1/3⟩ = ⟨9/4⟩ × ⟨4/3⟩ = ⟨36/12⟩ = 3이에요."]},{"stem":"⟨1 2/5⟩ × ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 19/30⟩","correct":true},{"t":"⟨1 1/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨7/10⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 19/30⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 2/5⟩ = ⟨7/5⟩, ⟨1 1/6⟩ = ⟨7/6⟩.","분모끼리, 분자끼리 곱해요.","⟨1 2/5⟩ × ⟨1 1/6⟩ = ⟨7/5⟩ × ⟨7/6⟩ = ⟨49/30⟩ = ⟨1 19/30⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#15','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C8',2,'sa','auto','서연이네 마을 전체 주민은 60명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 33명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"서연이네 마을 전체 주민은 60명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 33명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 60 × ⟨2/3⟩ = 40(명)이에요.","② 지금까지 33명이 동의했으니 40 − 33 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 70명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 35명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 70 × ⟨3/5⟩ = 42(명)이에요.","② 지금까지 35명이 동의했으니 42 − 35 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]},{"stem":"하린이네 마을 전체 주민은 64명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 40명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["① 최소로 동의해야 하는 수: 64 × ⟨3/4⟩ = 48(명)이에요.","② 지금까지 40명이 동의했으니 48 − 40 = 8(명)이에요.","적어도 8명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#16','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C1',2,'mc','auto','⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12','M5-2-u2-X15']::text[],true,'{"seq":16,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨8/44⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/11⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/11⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ = ⟨8/11⟩이에요.","⟨8/11⟩ — 분모까지 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩을 계산하면 얼마인가요?","options":[{"t":"⟨9/13⟩","correct":true},{"t":"⟨9/39⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 9/13⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/13⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩ = ⟨9/13⟩예요.","⟨9/13⟩ — 분모까지 더하면 안 돼요."]},{"stem":"⟨4/15⟩ + ⟨4/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/30⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/15⟩","mis":"M5-2-u2-X12"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨4/15⟩ + ⟨4/15⟩ = ⟨8/15⟩이에요.","⟨8/15⟩ — 분모까지 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#17','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',3,'error','auto','⟨3/8⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":17,"concept":"M5-2-u2-C2","difficulty":3,"kind":"error","stem":"⟨3/8⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨3/8⟩ × 2 = ⟨6/16⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"도윤 — 「⟨3/8⟩ × 2 = ⟨6/8⟩」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨3/8⟩ × 2 = ⟨3/4⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨3/8⟩ × 2 = ⟨6/8⟩ = ⟨3/4⟩이에요.","수아는 분모에도 2를 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨2/9⟩ × 3 = ⟨6/27⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"서연 — 「⟨2/9⟩ × 3 = ⟨6/9⟩」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨2/9⟩ × 3 = ⟨2/3⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨2/9⟩ × 3 = ⟨6/9⟩ = ⟨2/3⟩예요.","민준은 분모에도 3을 곱해서 틀렸어요."]},{"stem":"⟨4/7⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨4/7⟩ × 2 = ⟨8/14⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"나린 — 「⟨4/7⟩ × 2 = ⟨8/7⟩」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨4/7⟩ × 2 = ⟨1 1/7⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 2 = ⟨8/7⟩ = ⟨1 1/7⟩이에요.","가온은 분모에도 2를 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#18','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',3,'mc','auto','어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X02','M5-2-u2-X12']::text[],true,'{"seq":18,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 1/6⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 1/6⟩ = ⟨7/6⟩.","바르게 하면 ⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 친구가 ⟨1 3/8⟩ × 4를 「8과 4를 먼저 약분해 ⟨1 3/2⟩ × 1」로 고쳐 ⟨2 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 3/8⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 3/8⟩ = ⟨11/8⟩.","바르게 하면 ⟨1 3/8⟩ × 4 = ⟨11/8⟩ × 4 = ⟨44/8⟩ = ⟨11/2⟩ = ⟨5 1/2⟩이에요."]},{"stem":"어떤 친구가 ⟨2 1/4⟩ × 6을 「4와 6을 먼저 약분해 ⟨2 1/2⟩ × 3」으로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨2 1/4⟩에서 분모만 약분하면 자연수 부분 2가 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩.","바르게 하면 ⟨2 1/4⟩ × 6 = ⟨9/4⟩ × 6 = ⟨54/4⟩ = ⟨27/2⟩ = ⟨13 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#19','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',3,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":19,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 6보다 큰 것은 어느 것인가요?","options":[{"t":"6 × ⟨1 1/5⟩","correct":true},{"t":"6 × ⟨3/4⟩","mis":"M5-2-u2-X08"},{"t":"6 × 1","mis":"M5-2-u2-X08"},{"t":"6 × ⟨7/8⟩","mis":"M5-2-u2-X08"}],"explanation":["6에 1보다 작은 수를 곱하면 6보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/5⟩뿐이에요.","그래서 6보다 큰 것은 6 × ⟨1 1/5⟩이에요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 4보다 작은 것은 어느 것인가요?","options":[{"t":"4 × ⟨9/10⟩","correct":true},{"t":"4 × ⟨1 2/3⟩","mis":"M5-2-u2-X08"},{"t":"4 × 1","mis":"M5-2-u2-X08"},{"t":"4 × ⟨1 1/6⟩","mis":"M5-2-u2-X08"}],"explanation":["4에 1보다 작은 수를 곱하면 4보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨9/10⟩뿐이에요.","그래서 4보다 작은 것은 4 × ⟨9/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#20','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',3,'error','auto','⟨2/3⟩ × ⟨4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X17']::text[],true,'{"seq":20,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨2/3⟩ × ⟨4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「분모는 그대로 두고 분자끼리 곱해 ⟨8/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"도윤 — 「⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「전체 15칸 중 8칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이에요.","수아는 분모를 그대로 두어 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「분모는 그대로 두고 분자끼리 곱해 ⟨3/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"서연 — 「⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「전체 20칸 중 3칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이에요.","민준은 분모를 그대로 두어 틀렸어요."]},{"stem":"⟨5/6⟩ × ⟨1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「분모는 그대로 두고 분자끼리 곱해 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"나린 — 「⟨5/6⟩ × ⟨1/3⟩ = ⟨5/18⟩야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「전체 18칸 중 5칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨5/6⟩ × ⟨1/3⟩ = ⟨5/18⟩예요.","가온은 분모를 그대로 두어 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#21','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',3,'error','auto','⟨2 1/2⟩ × ⟨1 1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"⟨2 1/2⟩ × ⟨1 1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/2⟩ × ⟨1/3⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"도윤 — 「가분수로 고쳐 ⟨5/2⟩ × ⟨4/3⟩ = ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨2 1/2⟩ × ⟨1 1/3⟩의 답은 ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/2⟩ × ⟨1 1/3⟩ = ⟨5/2⟩ × ⟨4/3⟩ = ⟨20/6⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","수아는 부분끼리 따로 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨1 1/4⟩ × ⟨2 2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「자연수끼리 1 × 2, 분수끼리 ⟨1/4⟩ × ⟨2/3⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"서연 — 「가분수로 고쳐 ⟨5/4⟩ × ⟨8/3⟩ = ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨1 1/4⟩ × ⟨2 2/3⟩의 답은 ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨1 1/4⟩ × ⟨2 2/3⟩ = ⟨5/4⟩ × ⟨8/3⟩ = ⟨40/12⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","민준은 부분끼리 따로 곱해서 틀렸어요."]},{"stem":"⟨3 1/2⟩ × ⟨1 1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨1/5⟩ 해서 ⟨3 1/10⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"나린 — 「가분수로 고쳐 ⟨7/2⟩ × ⟨6/5⟩ = ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨3 1/2⟩ × ⟨1 1/5⟩의 답은 ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨3 1/2⟩ × ⟨1 1/5⟩ = ⟨7/2⟩ × ⟨6/5⟩ = ⟨42/10⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","가온은 부분끼리 따로 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#22','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C8',3,'mc','auto','서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"준기네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 90 × ⟨2/3⟩ = 60, 60 − 52 = 8(명)이에요.","준기네 마을: 80 × ⟨3/5⟩ = 48, 48 − 39 = 9(명)이에요.","준기네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 60명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"하린이네 마을","correct":true},{"t":"도윤이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["하린이네 마을: 72 × ⟨3/4⟩ = 54, 54 − 47 = 7(명)이에요.","도윤이네 마을: 84 × ⟨3/4⟩ = 63, 63 − 60 = 3(명)이에요.","하린이네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"가온이네 마을은 주민 96명 가운데 ⟨5/8⟩ 이상, 서연이네 마을은 주민 75명 가운데 ⟨4/5⟩ 이상이 동의해야 해요. 지금까지 각각 49명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"가온이네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["가온이네 마을: 96 × ⟨5/8⟩ = 60, 60 − 49 = 11(명)이에요.","서연이네 마을: 75 × ⟨4/5⟩ = 60, 60 − 55 = 5(명)이에요.","가온이네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#23','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',4,'sa','auto','⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C2","difficulty":4,"kind":"sa","stem":"⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로이고 분자만 3에서 15로 바뀌었어요.","분자와 □를 곱해 15가 되어야 해요 — 3 × 5 = 15.","그래서 □는 5예요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"20 × ⟨□/4⟩ = 15일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["20을 똑같이 4로 나누면 한 묶음은 5예요.","3묶음이 15니 □ = 15 ÷ 5 = 3이에요.","20 × ⟨3/4⟩ = 15 — 맞아요."]},{"stem":"⟨1/□⟩ × ⟨1/6⟩ = ⟨1/30⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 6 = 30이어야 해요.","30 ÷ 6 = 5니 □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#24','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',4,'essay','teacher','한 변의 길이가 ⟨3/8⟩ cm인 정삼각형과 한 변의 길이가 ⟨2/7⟩ cm인 정사각형의 둘레를 각각 구하고, 어느 도형의 둘레가 더 긴지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C2","difficulty":4,"kind":"essay","stem":"한 변의 길이가 ⟨3/8⟩ cm인 정삼각형과 한 변의 길이가 ⟨2/7⟩ cm인 정사각형의 둘레를 각각 구하고, 어느 도형의 둘레가 더 긴지 설명해 보세요.","answer_guide":{"answer":"예: 정삼각형의 둘레는 ⟨3/8⟩ × 3 = ⟨9/8⟩ = ⟨1 1/8⟩ cm이고, 정사각형의 둘레는 ⟨2/7⟩ × 4 = ⟨8/7⟩ = ⟨1 1/7⟩ cm이다. ⟨1/8⟩ < ⟨1/7⟩이므로 정사각형의 둘레가 더 길다.","scoring_points":["⟨3/8⟩ × 3 = ⟨1 1/8⟩ cm를 구했는가","⟨2/7⟩ × 4 = ⟨1 1/7⟩ cm를 구했는가","정사각형의 둘레가 더 길다고 바르게 견주었는가"]},"explanation":["정삼각형: ⟨3/8⟩ × 3 = ⟨1 1/8⟩ cm예요.","정사각형: ⟨2/7⟩ × 4 = ⟨1 1/7⟩ cm예요.","⟨1/8⟩ < ⟨1/7⟩ — 정사각형이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_a#25','math',5,2,'u2','','g5_2_math_u2_review_a','unit_review','M5-2-u2-C4',4,'essay','teacher','1시간의 ⟨3/4⟩과 하루의 ⟨1/8⟩은 각각 몇 분, 몇 시간인지 구하는 과정을 쓰고, 두 시간 가운데 어느 쪽이 더 긴지 견주어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C4","difficulty":4,"kind":"essay","stem":"1시간의 ⟨3/4⟩과 하루의 ⟨1/8⟩은 각각 몇 분, 몇 시간인지 구하는 과정을 쓰고, 두 시간 가운데 어느 쪽이 더 긴지 견주어 보세요.","answer_guide":{"answer":"예: 1시간은 60분이므로 60 × ⟨3/4⟩ = 45(분)이다. 하루는 24시간이므로 24 × ⟨1/8⟩ = 3(시간)이다. 3시간은 180분이므로 하루의 ⟨1/8⟩이 1시간의 ⟨3/4⟩보다 더 길다.","scoring_points":["60 × ⟨3/4⟩ = 45(분)을 구했는가","24 × ⟨1/8⟩ = 3(시간)을 구했는가","단위를 맞추어 하루의 ⟨1/8⟩이 더 길다고 견주었는가"]},"explanation":["60 × ⟨3/4⟩ = 45(분)이에요.","24 × ⟨1/8⟩ = 3(시간)이에요.","3시간이 45분보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#1','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C1',1,'mc','auto','⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨3/8⟩ × 4","correct":true},{"t":"⟨3/8⟩ × 5","mis":"M5-2-u2-X17"},{"t":"⟨3/8⟩ + 4","mis":"M5-2-u2-X15"},{"t":"3 × 4","mis":"M5-2-u2-X15"}],"explanation":["⟨3/8⟩을 4번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ = ⟨3/8⟩ × 4예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩ × 5","correct":true},{"t":"⟨1/6⟩ × 6","mis":"M5-2-u2-X17"},{"t":"⟨1/6⟩ + 5","mis":"M5-2-u2-X15"},{"t":"1 × 5","mis":"M5-2-u2-X15"}],"explanation":["⟨1/6⟩을 5번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ = ⟨1/6⟩ × 5예요."]},{"stem":"⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨4/11⟩ × 3","correct":true},{"t":"⟨4/11⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨4/11⟩ + 3","mis":"M5-2-u2-X15"},{"t":"4 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨4/11⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩ = ⟨4/11⟩ × 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#2','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C2',1,'sa','auto','⟨3/10⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C2","difficulty":1,"kind":"sa","stem":"⟨3/10⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 3 × 3 = 9예요.","⟨3/10⟩ × 3 = ⟨9/10⟩예요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨1/8⟩ × 7을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 1 × 7 = 7이에요.","⟨1/8⟩ × 7 = ⟨7/8⟩이에요."]},{"stem":"⟨4/9⟩ × 2를 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 4 × 2 = 8이에요.","⟨4/9⟩ × 2 = ⟨8/9⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#3','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',1,'mc','auto','⟨1 2/7⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/7⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/7⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨7/7⟩이에요 — 1 × 7 = 7.","여기에 ⟨2/7⟩를 더하면 분자는 7 + 2 = 9예요.","⟨1 2/7⟩ = ⟨9/7⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"⟨4/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨3/3⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]},{"stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M5-2-u2-X17"},{"t":"⟨6/6⟩","mis":"M5-2-u2-X04"},{"t":"⟨5/6⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#4','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C4',1,'sa','auto','9의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"9의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9를 똑같이 3으로 나누면 한 묶음은 9 ÷ 3 = 3이에요.","그중의 2니 3 × 2 = 6이에요.","식으로는 9 × ⟨2/3⟩ = ⟨18/3⟩ = 6이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10을 똑같이 5로 나누면 한 묶음은 10 ÷ 5 = 2예요.","그중의 1이니 2 × 1 = 2예요.","식으로는 10 × ⟨1/5⟩ = ⟨10/5⟩ = 2예요."]},{"stem":"12의 ⟨5/6⟩는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["12를 똑같이 6으로 나누면 한 묶음은 12 ÷ 6 = 2예요.","그중의 5니 2 × 5 = 10이에요.","식으로는 12 × ⟨5/6⟩ = ⟨60/6⟩ = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#5','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',1,'mc','auto','8 × ⟨1 2/7⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"8 × ⟨1 2/7⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"8보다 크다","correct":true},{"t":"8보다 작다","mis":"M5-2-u2-X08"},{"t":"8과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 2/7⟩가 1보다 커요.","8 × ⟨1 2/7⟩ = ⟨10 2/7⟩예요.","그래서 「8보다 크다」예요."],"variant_rule":{"alt":[{"stem":"9 × ⟨4/9⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"9보다 작다","correct":true},{"t":"9보다 크다","mis":"M5-2-u2-X08"},{"t":"9와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨4/9⟩가 1보다 작아요.","9 × ⟨4/9⟩ = 4예요.","그래서 「9보다 작다」예요."]},{"stem":"3 × ⟨1 1/6⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"3보다 크다","correct":true},{"t":"3보다 작다","mis":"M5-2-u2-X08"},{"t":"3과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 1/6⟩이 1보다 커요.","3 × ⟨1 1/6⟩ = ⟨3 1/2⟩이에요.","그래서 「3보다 크다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#6','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',1,'mc','auto','⟨1/2⟩ × ⟨1/9⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/2⟩ × ⟨1/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/18⟩","correct":true},{"t":"⟨2/18⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 2등분 한 것 중의 1을 다시 9등분 해요.","전체는 2 × 9 = 18칸이 되고, 그중의 1칸이에요.","⟨1/2⟩ × ⟨1/9⟩ = ⟨1/18⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩ × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/24⟩","correct":true},{"t":"⟨2/24⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 6등분 한 것 중의 1을 다시 4등분 해요.","전체는 6 × 4 = 24칸이 되고, 그중의 1칸이에요.","⟨1/6⟩ × ⟨1/4⟩ = ⟨1/24⟩이에요."]},{"stem":"⟨1/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/21⟩","correct":true},{"t":"⟨2/21⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 7등분 한 것 중의 1을 다시 3등분 해요.","전체는 7 × 3 = 21칸이 되고, 그중의 1칸이에요.","⟨1/7⟩ × ⟨1/3⟩ = ⟨1/21⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#7','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',1,'sa','auto','⟨1 5/6⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨1 5/6⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 1은 ⟨6/6⟩이에요.","분자는 1 × 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨4 1/3⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["자연수 4는 ⟨12/3⟩예요.","분자는 4 × 3 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]},{"stem":"⟨3 2/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 3은 ⟨15/5⟩예요.","분자는 3 × 5 + 2 = 17이에요.","⟨3 2/5⟩ = ⟨17/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#8','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C8',1,'sa','auto','준기네 마을 전체 주민은 70명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"준기네 마을 전체 주민은 70명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["42"],"explanation":["전체 70명의 ⟨3/5⟩ 이상이에요.","70 × ⟨3/5⟩ = 42(명)이에요.","적어도 42명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"하린이네 마을 전체 주민은 64명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["48"],"explanation":["전체 64명의 ⟨3/4⟩ 이상이에요.","64 × ⟨3/4⟩ = 48(명)이에요.","적어도 48명이 동의해야 해요."]},{"stem":"도윤이네 마을 전체 주민은 63명이에요. 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["전체 63명의 ⟨5/7⟩ 이상이에요.","63 × ⟨5/7⟩ = 45(명)이에요.","적어도 45명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#9','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C2',2,'mc','auto','⟨5/9⟩ × 2를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨5/9⟩ × 2를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/9⟩","correct":true},{"t":"⟨10/18⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/18⟩","mis":"M5-2-u2-X02"},{"t":"⟨7/9⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/9⟩ × 2 = ⟨10/9⟩ = ⟨1 1/9⟩이에요.","한 칸의 크기 ⟨1/9⟩은 그대로이고 칸의 수만 2배가 돼요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/3⟩ × 5 = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","한 칸의 크기 ⟨1/3⟩은 그대로이고 칸의 수만 5배가 돼요."]},{"stem":"⟨3/10⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨18/60⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/60⟩","mis":"M5-2-u2-X02"},{"t":"⟨9/10⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/10⟩ × 6 = ⟨18/10⟩ = ⟨9/5⟩ = ⟨1 4/5⟩예요.","한 칸의 크기 ⟨1/10⟩은 그대로이고 칸의 수만 6배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#10','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',2,'mc','auto','⟨2 1/5⟩ × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨2 1/5⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/5⟩","correct":true},{"t":"⟨6 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 3/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/5⟩ = ⟨11/5⟩이에요.","⟨2 1/5⟩ × 3 = ⟨11/5⟩ × 3 = ⟨33/5⟩ = ⟨6 3/5⟩이에요.","자연수 부분으로 갈라도 2 × 3 + ⟨1/5⟩ × 3 = ⟨6 3/5⟩으로 같아요."],"variant_rule":{"alt":[{"stem":"⟨1 1/8⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/4⟩","correct":true},{"t":"⟨6 1/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/8⟩ = ⟨9/8⟩예요.","⟨1 1/8⟩ × 6 = ⟨9/8⟩ × 6 = ⟨54/8⟩ = ⟨27/4⟩ = ⟨6 3/4⟩이에요.","자연수 부분으로 갈라도 1 × 6 + ⟨1/8⟩ × 6 = ⟨6 3/4⟩으로 같아요."]},{"stem":"⟨3 1/2⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨17 1/2⟩","correct":true},{"t":"⟨15 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/2⟩","mis":"M5-2-u2-X05"},{"t":"10","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨3 1/2⟩ × 5 = ⟨7/2⟩ × 5 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","자연수 부분으로 갈라도 3 × 5 + ⟨1/2⟩ × 5 = ⟨17 1/2⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#11','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C4',2,'mc','auto','3 × ⟨4/7⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X07']::text[],true,'{"seq":11,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"3 × ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/21⟩","mis":"M5-2-u2-X02"},{"t":"12","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨4/7⟩ = ⟨12/7⟩ = ⟨1 5/7⟩예요.","3을 똑같이 7로 나눈 것 중의 4만큼이에요."],"variant_rule":{"alt":[{"stem":"6 × ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨30/48⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/48⟩","mis":"M5-2-u2-X02"},{"t":"30","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","6 × ⟨5/8⟩ = ⟨30/8⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","6을 똑같이 8로 나눈 것 중의 5만큼이에요."]},{"stem":"4 × ⟨7/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 1/9⟩","correct":true},{"t":"⟨28/36⟩","mis":"M5-2-u2-X01"},{"t":"⟨7/36⟩","mis":"M5-2-u2-X02"},{"t":"28","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","4 × ⟨7/9⟩ = ⟨28/9⟩ = ⟨3 1/9⟩이에요.","4를 똑같이 9로 나눈 것 중의 7만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#12','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',2,'mc','auto','2 × ⟨2 2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":12,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"2 × ⟨2 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 2/3⟩ = ⟨8/3⟩이에요.","2 × ⟨2 2/3⟩ = 2 × ⟨8/3⟩ = ⟨16/3⟩ = ⟨5 1/3⟩이에요.","둘로 갈라도 2 × 2 + 2 × ⟨2/3⟩ = ⟨5 1/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"5 × ⟨1 2/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/7⟩","correct":true},{"t":"⟨5 2/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 3/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/7⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/7⟩ = ⟨9/7⟩예요.","5 × ⟨1 2/7⟩ = 5 × ⟨9/7⟩ = ⟨45/7⟩ = ⟨6 3/7⟩이에요.","둘로 갈라도 5 × 1 + 5 × ⟨2/7⟩ = ⟨6 3/7⟩으로 같아요."]},{"stem":"4 × ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨4 1/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/6⟩ = ⟨7/6⟩이에요.","4 × ⟨1 1/6⟩ = 4 × ⟨7/6⟩ = ⟨28/6⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","둘로 갈라도 4 × 1 + 4 × ⟨1/6⟩ = ⟨4 2/3⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#13','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',2,'mc','auto','⟨5/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":13,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨5/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/21⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨15/7⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨5/7⟩ × ⟨1/3⟩ = ⟨5/21⟩예요.","전체 21칸 가운데 5칸이라고 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/9⟩","mis":"M5-2-u2-X09"},{"t":"⟨27/8⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3/4⟩ × ⟨2/9⟩ = ⟨6/36⟩ = ⟨1/6⟩이에요.","전체 36칸 가운데 6칸이라고 볼 수 있어요."]},{"stem":"⟨7/8⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨28/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨28/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨35/32⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨7/8⟩ × ⟨4/5⟩ = ⟨28/40⟩ = ⟨7/10⟩이에요.","전체 40칸 가운데 28칸이라고 볼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#14','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',2,'mc','auto','⟨2 1/4⟩ × ⟨1 1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04','M5-2-u2-X12']::text[],true,'{"seq":14,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨2 1/4⟩ × ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 1/12⟩","mis":"M5-2-u2-X11"},{"t":"1","mis":"M5-2-u2-X04"},{"t":"4","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩, ⟨1 1/3⟩ = ⟨4/3⟩.","분모끼리, 분자끼리 곱해요.","⟨2 1/4⟩ × ⟨1 1/3⟩ = ⟨9/4⟩ × ⟨4/3⟩ = ⟨36/12⟩ = 3이에요."],"variant_rule":{"alt":[{"stem":"⟨1 2/5⟩ × ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 19/30⟩","correct":true},{"t":"⟨1 1/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨7/10⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 19/30⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 2/5⟩ = ⟨7/5⟩, ⟨1 1/6⟩ = ⟨7/6⟩.","분모끼리, 분자끼리 곱해요.","⟨1 2/5⟩ × ⟨1 1/6⟩ = ⟨7/5⟩ × ⟨7/6⟩ = ⟨49/30⟩ = ⟨1 19/30⟩예요."]},{"stem":"⟨3 1/3⟩ × ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨3 1/6⟩","mis":"M5-2-u2-X11"},{"t":"2","mis":"M5-2-u2-X04"},{"t":"6","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨3 1/3⟩ = ⟨10/3⟩, ⟨1 1/2⟩ = ⟨3/2⟩.","분모끼리, 분자끼리 곱해요.","⟨3 1/3⟩ × ⟨1 1/2⟩ = ⟨10/3⟩ × ⟨3/2⟩ = ⟨30/6⟩ = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#15','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C8',2,'sa','auto','준기네 마을 전체 주민은 70명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 35명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"준기네 마을 전체 주민은 70명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 35명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 70 × ⟨3/5⟩ = 42(명)이에요.","② 지금까지 35명이 동의했으니 42 − 35 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"하린이네 마을 전체 주민은 64명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 40명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["① 최소로 동의해야 하는 수: 64 × ⟨3/4⟩ = 48(명)이에요.","② 지금까지 40명이 동의했으니 48 − 40 = 8(명)이에요.","적어도 8명이 더 동의해야 해요."]},{"stem":"도윤이네 마을 전체 주민은 63명이고, 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 38명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 63 × ⟨5/7⟩ = 45(명)이에요.","② 지금까지 38명이 동의했으니 45 − 38 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#16','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C1',2,'mc','auto','⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12','M5-2-u2-X15']::text[],true,'{"seq":16,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩을 계산하면 얼마인가요?","options":[{"t":"⟨9/13⟩","correct":true},{"t":"⟨9/39⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 9/13⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/13⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩ = ⟨9/13⟩예요.","⟨9/13⟩ — 분모까지 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨4/15⟩ + ⟨4/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/30⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/15⟩","mis":"M5-2-u2-X12"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨4/15⟩ + ⟨4/15⟩ = ⟨8/15⟩이에요.","⟨8/15⟩ — 분모까지 더하면 안 돼요."]},{"stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨6/27⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X12"},{"t":"⟨5/9⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨6/9⟩이에요.","⟨6/9⟩ = ⟨2/3⟩ — 분모까지 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#17','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C2',3,'error','auto','⟨2/9⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":17,"concept":"M5-2-u2-C2","difficulty":3,"kind":"error","stem":"⟨2/9⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨2/9⟩ × 3 = ⟨6/27⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"서연 — 「⟨2/9⟩ × 3 = ⟨6/9⟩」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨2/9⟩ × 3 = ⟨2/3⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨2/9⟩ × 3 = ⟨6/9⟩ = ⟨2/3⟩예요.","민준은 분모에도 3을 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨4/7⟩ × 2 = ⟨8/14⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"나린 — 「⟨4/7⟩ × 2 = ⟨8/7⟩」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨4/7⟩ × 2 = ⟨1 1/7⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 2 = ⟨8/7⟩ = ⟨1 1/7⟩이에요.","가온은 분모에도 2를 곱해서 틀렸어요."]},{"stem":"⟨5/12⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨5/12⟩ × 3 = ⟨15/36⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"라온 — 「⟨5/12⟩ × 3 = ⟨15/12⟩」","mis":"M5-2-u2-X17"},{"t":"예준 — 「⟨5/12⟩ × 3 = ⟨1 1/4⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨5/12⟩ × 3 = ⟨15/12⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","여울은 분모에도 3을 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#18','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',3,'mc','auto','어떤 친구가 ⟨1 3/8⟩ × 4를 「8과 4를 먼저 약분해 ⟨1 3/2⟩ × 1」로 고쳐 ⟨2 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X02','M5-2-u2-X12']::text[],true,'{"seq":18,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"어떤 친구가 ⟨1 3/8⟩ × 4를 「8과 4를 먼저 약분해 ⟨1 3/2⟩ × 1」로 고쳐 ⟨2 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 3/8⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 3/8⟩ = ⟨11/8⟩.","바르게 하면 ⟨1 3/8⟩ × 4 = ⟨11/8⟩ × 4 = ⟨44/8⟩ = ⟨11/2⟩ = ⟨5 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 친구가 ⟨2 1/4⟩ × 6을 「4와 6을 먼저 약분해 ⟨2 1/2⟩ × 3」으로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨2 1/4⟩에서 분모만 약분하면 자연수 부분 2가 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩.","바르게 하면 ⟨2 1/4⟩ × 6 = ⟨9/4⟩ × 6 = ⟨54/4⟩ = ⟨27/2⟩ = ⟨13 1/2⟩이에요."]},{"stem":"어떤 친구가 ⟨1 2/9⟩ × 6을 「9와 6을 먼저 약분해 ⟨1 2/3⟩ × 2」로 고쳐 ⟨2 1/3⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 2/9⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 2/9⟩ = ⟨11/9⟩.","바르게 하면 ⟨1 2/9⟩ × 6 = ⟨11/9⟩ × 6 = ⟨66/9⟩ = ⟨22/3⟩ = ⟨7 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#19','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',3,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 6보다 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":19,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 6보다 큰 것은 어느 것인가요?","options":[{"t":"6 × ⟨1 1/5⟩","correct":true},{"t":"6 × ⟨3/4⟩","mis":"M5-2-u2-X08"},{"t":"6 × 1","mis":"M5-2-u2-X08"},{"t":"6 × ⟨7/8⟩","mis":"M5-2-u2-X08"}],"explanation":["6에 1보다 작은 수를 곱하면 6보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/5⟩뿐이에요.","그래서 6보다 큰 것은 6 × ⟨1 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 4보다 작은 것은 어느 것인가요?","options":[{"t":"4 × ⟨9/10⟩","correct":true},{"t":"4 × ⟨1 2/3⟩","mis":"M5-2-u2-X08"},{"t":"4 × 1","mis":"M5-2-u2-X08"},{"t":"4 × ⟨1 1/6⟩","mis":"M5-2-u2-X08"}],"explanation":["4에 1보다 작은 수를 곱하면 4보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨9/10⟩뿐이에요.","그래서 4보다 작은 것은 4 × ⟨9/10⟩예요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 7보다 작은 것은 어느 것인가요?","options":[{"t":"7 × ⟨5/6⟩","correct":true},{"t":"7 × ⟨1 1/4⟩","mis":"M5-2-u2-X08"},{"t":"7 × 1","mis":"M5-2-u2-X08"},{"t":"7 × ⟨1 2/5⟩","mis":"M5-2-u2-X08"}],"explanation":["7에 1보다 작은 수를 곱하면 7보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨5/6⟩뿐이에요.","그래서 7보다 작은 것은 7 × ⟨5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#20','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',3,'error','auto','⟨3/4⟩ × ⟨1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X17']::text[],true,'{"seq":20,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨3/4⟩ × ⟨1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「분모는 그대로 두고 분자끼리 곱해 ⟨3/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"서연 — 「⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「전체 20칸 중 3칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이에요.","민준은 분모를 그대로 두어 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ × ⟨1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「분모는 그대로 두고 분자끼리 곱해 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"나린 — 「⟨5/6⟩ × ⟨1/3⟩ = ⟨5/18⟩야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「전체 18칸 중 5칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨5/6⟩ × ⟨1/3⟩ = ⟨5/18⟩예요.","가온은 분모를 그대로 두어 틀렸어요."]},{"stem":"⟨2/7⟩ × ⟨3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「분모는 그대로 두고 분자끼리 곱해 ⟨6/7⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"라온 — 「⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩이야.」","mis":"M5-2-u2-X17"},{"t":"예준 — 「약분하면 ⟨3/14⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩ = ⟨3/14⟩이에요.","여울은 분모를 그대로 두어 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#21','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',3,'error','auto','⟨1 1/4⟩ × ⟨2 2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"⟨1 1/4⟩ × ⟨2 2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「자연수끼리 1 × 2, 분수끼리 ⟨1/4⟩ × ⟨2/3⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"서연 — 「가분수로 고쳐 ⟨5/4⟩ × ⟨8/3⟩ = ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨1 1/4⟩ × ⟨2 2/3⟩의 답은 ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨1 1/4⟩ × ⟨2 2/3⟩ = ⟨5/4⟩ × ⟨8/3⟩ = ⟨40/12⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","민준은 부분끼리 따로 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3 1/2⟩ × ⟨1 1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨1/5⟩ 해서 ⟨3 1/10⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"나린 — 「가분수로 고쳐 ⟨7/2⟩ × ⟨6/5⟩ = ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨3 1/2⟩ × ⟨1 1/5⟩의 답은 ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨3 1/2⟩ × ⟨1 1/5⟩ = ⟨7/2⟩ × ⟨6/5⟩ = ⟨42/10⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","가온은 부분끼리 따로 곱해서 틀렸어요."]},{"stem":"⟨2 1/3⟩ × ⟨1 3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/3⟩ × ⟨3/4⟩ 해서 ⟨2 1/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"라온 — 「가분수로 고쳐 ⟨7/3⟩ × ⟨7/4⟩ = ⟨4 1/12⟩이야.」","mis":"M5-2-u2-X17"},{"t":"예준 — 「⟨2 1/3⟩ × ⟨1 3/4⟩의 답은 ⟨4 1/12⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/3⟩ × ⟨1 3/4⟩ = ⟨7/3⟩ × ⟨7/4⟩ = ⟨49/12⟩ = ⟨4 1/12⟩이에요.","여울은 부분끼리 따로 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#22','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C8',3,'mc','auto','하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 60명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 60명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"하린이네 마을","correct":true},{"t":"도윤이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["하린이네 마을: 72 × ⟨3/4⟩ = 54, 54 − 47 = 7(명)이에요.","도윤이네 마을: 84 × ⟨3/4⟩ = 63, 63 − 60 = 3(명)이에요.","하린이네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"가온이네 마을은 주민 96명 가운데 ⟨5/8⟩ 이상, 서연이네 마을은 주민 75명 가운데 ⟨4/5⟩ 이상이 동의해야 해요. 지금까지 각각 49명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"가온이네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["가온이네 마을: 96 × ⟨5/8⟩ = 60, 60 − 49 = 11(명)이에요.","서연이네 마을: 75 × ⟨4/5⟩ = 60, 60 − 55 = 5(명)이에요.","가온이네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"도윤이네 마을","correct":true},{"t":"준기네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["준기네 마을: 85 × ⟨3/5⟩ = 51, 51 − 44 = 7(명)이에요.","도윤이네 마을: 96 × ⟨2/3⟩ = 64, 64 − 55 = 9(명)이에요.","도윤이네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#23','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C4',4,'sa','auto','20 × ⟨□/4⟩ = 15일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C4","difficulty":4,"kind":"sa","stem":"20 × ⟨□/4⟩ = 15일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["20을 똑같이 4로 나누면 한 묶음은 5예요.","3묶음이 15니 □ = 15 ÷ 5 = 3이에요.","20 × ⟨3/4⟩ = 15 — 맞아요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"⟨1/□⟩ × ⟨1/6⟩ = ⟨1/30⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 6 = 30이어야 해요.","30 ÷ 6 = 5니 □는 5예요."]},{"stem":"5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["남학생은 96 × ⟨3/4⟩ = 72명이에요.","그 가운데 ⟨5/8⟩니 72 × ⟨5/8⟩ = 45명이에요.","한 번에 96 × ⟨3/4⟩ × ⟨5/8⟩ = 45로 구해도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#24','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',4,'essay','teacher','⟨2 1/3⟩ × 5를 두 가지 방법(자연수 부분과 분수 부분으로 가르기, 가분수로 고치기)으로 계산하고 두 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C3","difficulty":4,"kind":"essay","stem":"⟨2 1/3⟩ × 5를 두 가지 방법(자연수 부분과 분수 부분으로 가르기, 가분수로 고치기)으로 계산하고 두 답이 같은지 확인해 보세요.","answer_guide":{"answer":"예: 가르기 — 2 × 5 + ⟨1/3⟩ × 5 = 10 + ⟨5/3⟩ = ⟨11 2/3⟩이다. 가분수 — ⟨2 1/3⟩ = ⟨7/3⟩이므로 ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩이다. 두 방법의 답이 ⟨11 2/3⟩로 같다.","scoring_points":["가르기로 ⟨11 2/3⟩를 구했는가","가분수로 고쳐 ⟨35/3⟩를 구했는가","두 답이 같다고 확인했는가"]},"explanation":["2 × 5 + ⟨1/3⟩ × 5 = ⟨11 2/3⟩예요.","⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","두 답이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_b#25','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',4,'essay','teacher','⟨9/10⟩ × ⟨5/6⟩를 「곱한 뒤 약분하기」와 「곱하기 전에 약분하기」 두 가지로 계산하고, 곱하기 전에 약분할 때 어떤 수끼리 약분해야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C6","difficulty":4,"kind":"essay","stem":"⟨9/10⟩ × ⟨5/6⟩를 「곱한 뒤 약분하기」와 「곱하기 전에 약분하기」 두 가지로 계산하고, 곱하기 전에 약분할 때 어떤 수끼리 약분해야 하는지 쓰세요.","answer_guide":{"answer":"예: 곱한 뒤 약분 — ⟨9/10⟩ × ⟨5/6⟩ = ⟨45/60⟩ = ⟨3/4⟩이다. 곱하기 전 약분 — 분자 9와 분모 6을 3으로, 분자 5와 분모 10을 5로 약분하면 ⟨3/2⟩ × ⟨1/2⟩ = ⟨3/4⟩이다. 약분은 분자와 분모 사이에서만 해야 하고, 분자끼리나 분모끼리는 약분하면 안 된다.","scoring_points":["곱한 뒤 약분해 ⟨3/4⟩을 구했는가","곱하기 전 약분해 ⟨3/4⟩을 구했는가","분자와 분모 사이에서만 약분한다고 썼는가"]},"explanation":["⟨45/60⟩ = ⟨3/4⟩이에요.","⟨3/2⟩ × ⟨1/2⟩ = ⟨3/4⟩이에요.","약분은 분자와 분모 사이에서만 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#1','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C1',1,'mc','auto','⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩ × 5","correct":true},{"t":"⟨1/6⟩ × 6","mis":"M5-2-u2-X17"},{"t":"⟨1/6⟩ + 5","mis":"M5-2-u2-X15"},{"t":"1 × 5","mis":"M5-2-u2-X15"}],"explanation":["⟨1/6⟩을 5번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ + ⟨1/6⟩ = ⟨1/6⟩ × 5예요."],"variant_rule":{"alt":[{"stem":"⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨4/11⟩ × 3","correct":true},{"t":"⟨4/11⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨4/11⟩ + 3","mis":"M5-2-u2-X15"},{"t":"4 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨4/11⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩ = ⟨4/11⟩ × 3이에요."]},{"stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨2/9⟩ × 3","correct":true},{"t":"⟨2/9⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨2/9⟩ + 3","mis":"M5-2-u2-X15"},{"t":"2 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨2/9⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨2/9⟩ × 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#2','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C2',1,'sa','auto','⟨1/8⟩ × 7을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C2","difficulty":1,"kind":"sa","stem":"⟨1/8⟩ × 7을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 1 × 7 = 7이에요.","⟨1/8⟩ × 7 = ⟨7/8⟩이에요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨4/9⟩ × 2를 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 4 × 2 = 8이에요.","⟨4/9⟩ × 2 = ⟨8/9⟩이에요."]},{"stem":"⟨2/7⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 2 × 3 = 6이에요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#3','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C3',1,'mc','auto','⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"⟨4/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨3/3⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M5-2-u2-X17"},{"t":"⟨6/6⟩","mis":"M5-2-u2-X04"},{"t":"⟨5/6⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]},{"stem":"⟨2 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/4⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨1/4⟩을 더하면 분자는 8 + 1 = 9예요.","⟨2 1/4⟩ = ⟨9/4⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#4','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C4',1,'sa','auto','10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10을 똑같이 5로 나누면 한 묶음은 10 ÷ 5 = 2예요.","그중의 1이니 2 × 1 = 2예요.","식으로는 10 × ⟨1/5⟩ = ⟨10/5⟩ = 2예요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"12의 ⟨5/6⟩는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["12를 똑같이 6으로 나누면 한 묶음은 12 ÷ 6 = 2예요.","그중의 5니 2 × 5 = 10이에요.","식으로는 12 × ⟨5/6⟩ = ⟨60/6⟩ = 10이에요."]},{"stem":"8의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["8을 똑같이 4로 나누면 한 묶음은 8 ÷ 4 = 2예요.","그중의 3이니 2 × 3 = 6이에요.","식으로는 8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#5','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',1,'mc','auto','9 × ⟨4/9⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"9 × ⟨4/9⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"9보다 작다","correct":true},{"t":"9보다 크다","mis":"M5-2-u2-X08"},{"t":"9와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨4/9⟩가 1보다 작아요.","9 × ⟨4/9⟩ = 4예요.","그래서 「9보다 작다」예요."],"variant_rule":{"alt":[{"stem":"3 × ⟨1 1/6⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"3보다 크다","correct":true},{"t":"3보다 작다","mis":"M5-2-u2-X08"},{"t":"3과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 1/6⟩이 1보다 커요.","3 × ⟨1 1/6⟩ = ⟨3 1/2⟩이에요.","그래서 「3보다 크다」예요."]},{"stem":"4 × ⟨3/5⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"4보다 작다","correct":true},{"t":"4보다 크다","mis":"M5-2-u2-X08"},{"t":"4와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨3/5⟩이 1보다 작아요.","4 × ⟨3/5⟩ = ⟨2 2/5⟩예요.","그래서 「4보다 작다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#6','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',1,'mc','auto','⟨1/6⟩ × ⟨1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/6⟩ × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/24⟩","correct":true},{"t":"⟨2/24⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 6등분 한 것 중의 1을 다시 4등분 해요.","전체는 6 × 4 = 24칸이 되고, 그중의 1칸이에요.","⟨1/6⟩ × ⟨1/4⟩ = ⟨1/24⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/21⟩","correct":true},{"t":"⟨2/21⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 7등분 한 것 중의 1을 다시 3등분 해요.","전체는 7 × 3 = 21칸이 되고, 그중의 1칸이에요.","⟨1/7⟩ × ⟨1/3⟩ = ⟨1/21⟩이에요."]},{"stem":"⟨1/3⟩ × ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/15⟩","correct":true},{"t":"⟨2/15⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/8⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 3등분 한 것 중의 1을 다시 5등분 해요.","전체는 3 × 5 = 15칸이 되고, 그중의 1칸이에요.","⟨1/3⟩ × ⟨1/5⟩ = ⟨1/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#7','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',1,'sa','auto','⟨4 1/3⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨4 1/3⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["자연수 4는 ⟨12/3⟩예요.","분자는 4 × 3 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨3 2/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 3은 ⟨15/5⟩예요.","분자는 3 × 5 + 2 = 17이에요.","⟨3 2/5⟩ = ⟨17/5⟩이에요."]},{"stem":"⟨2 3/4⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 2는 ⟨8/4⟩이에요.","분자는 2 × 4 + 3 = 11이에요.","⟨2 3/4⟩ = ⟨11/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#8','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C8',1,'sa','auto','하린이네 마을 전체 주민은 64명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"하린이네 마을 전체 주민은 64명이에요. 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["48"],"explanation":["전체 64명의 ⟨3/4⟩ 이상이에요.","64 × ⟨3/4⟩ = 48(명)이에요.","적어도 48명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"도윤이네 마을 전체 주민은 63명이에요. 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["전체 63명의 ⟨5/7⟩ 이상이에요.","63 × ⟨5/7⟩ = 45(명)이에요.","적어도 45명이 동의해야 해요."]},{"stem":"서연이네 마을 전체 주민은 60명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 60명의 ⟨2/3⟩ 이상이에요.","60 × ⟨2/3⟩ = 40(명)이에요.","적어도 40명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#9','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C2',2,'mc','auto','⟨2/3⟩ × 5를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨2/3⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/3⟩ × 5 = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","한 칸의 크기 ⟨1/3⟩은 그대로이고 칸의 수만 5배가 돼요."],"variant_rule":{"alt":[{"stem":"⟨3/10⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨18/60⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/60⟩","mis":"M5-2-u2-X02"},{"t":"⟨9/10⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/10⟩ × 6 = ⟨18/10⟩ = ⟨9/5⟩ = ⟨1 4/5⟩예요.","한 칸의 크기 ⟨1/10⟩은 그대로이고 칸의 수만 6배가 돼요."]},{"stem":"⟨3/7⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/28⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/28⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/7⟩ × 4 = ⟨12/7⟩ = ⟨1 5/7⟩예요.","한 칸의 크기 ⟨1/7⟩은 그대로이고 칸의 수만 4배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#10','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C3',2,'mc','auto','⟨1 1/8⟩ × 6을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨1 1/8⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/4⟩","correct":true},{"t":"⟨6 1/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/8⟩ = ⟨9/8⟩예요.","⟨1 1/8⟩ × 6 = ⟨9/8⟩ × 6 = ⟨54/8⟩ = ⟨27/4⟩ = ⟨6 3/4⟩이에요.","자연수 부분으로 갈라도 1 × 6 + ⟨1/8⟩ × 6 = ⟨6 3/4⟩으로 같아요."],"variant_rule":{"alt":[{"stem":"⟨3 1/2⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨17 1/2⟩","correct":true},{"t":"⟨15 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/2⟩","mis":"M5-2-u2-X05"},{"t":"10","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨3 1/2⟩ × 5 = ⟨7/2⟩ × 5 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","자연수 부분으로 갈라도 3 × 5 + ⟨1/2⟩ × 5 = ⟨17 1/2⟩로 같아요."]},{"stem":"⟨1 2/3⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨6 2/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 2/3⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨1 2/3⟩ × 4 = ⟨5/3⟩ × 4 = ⟨20/3⟩ = ⟨6 2/3⟩예요.","자연수 부분으로 갈라도 1 × 4 + ⟨2/3⟩ × 4 = ⟨6 2/3⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#11','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C4',2,'mc','auto','6 × ⟨5/8⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X07']::text[],true,'{"seq":11,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"6 × ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨30/48⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/48⟩","mis":"M5-2-u2-X02"},{"t":"30","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","6 × ⟨5/8⟩ = ⟨30/8⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","6을 똑같이 8로 나눈 것 중의 5만큼이에요."],"variant_rule":{"alt":[{"stem":"4 × ⟨7/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 1/9⟩","correct":true},{"t":"⟨28/36⟩","mis":"M5-2-u2-X01"},{"t":"⟨7/36⟩","mis":"M5-2-u2-X02"},{"t":"28","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","4 × ⟨7/9⟩ = ⟨28/9⟩ = ⟨3 1/9⟩이에요.","4를 똑같이 9로 나눈 것 중의 7만큼이에요."]},{"stem":"5 × ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"10","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","5를 똑같이 3으로 나눈 것 중의 2만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#12','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',2,'mc','auto','5 × ⟨1 2/7⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":12,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"5 × ⟨1 2/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/7⟩","correct":true},{"t":"⟨5 2/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 3/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/7⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/7⟩ = ⟨9/7⟩예요.","5 × ⟨1 2/7⟩ = 5 × ⟨9/7⟩ = ⟨45/7⟩ = ⟨6 3/7⟩이에요.","둘로 갈라도 5 × 1 + 5 × ⟨2/7⟩ = ⟨6 3/7⟩으로 같아요."],"variant_rule":{"alt":[{"stem":"4 × ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨4 1/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/6⟩ = ⟨7/6⟩이에요.","4 × ⟨1 1/6⟩ = 4 × ⟨7/6⟩ = ⟨28/6⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","둘로 갈라도 4 × 1 + 4 × ⟨1/6⟩ = ⟨4 2/3⟩로 같아요."]},{"stem":"3 × ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/4⟩ = ⟨5/4⟩예요.","3 × ⟨1 1/4⟩ = 3 × ⟨5/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","둘로 갈라도 3 × 1 + 3 × ⟨1/4⟩ = ⟨3 3/4⟩으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#13','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',2,'mc','auto','⟨3/4⟩ × ⟨2/9⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":13,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨3/4⟩ × ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/9⟩","mis":"M5-2-u2-X09"},{"t":"⟨27/8⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3/4⟩ × ⟨2/9⟩ = ⟨6/36⟩ = ⟨1/6⟩이에요.","전체 36칸 가운데 6칸이라고 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨7/8⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨28/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨28/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨35/32⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨7/8⟩ × ⟨4/5⟩ = ⟨28/40⟩ = ⟨7/10⟩이에요.","전체 40칸 가운데 28칸이라고 볼 수 있어요."]},{"stem":"⟨2/3⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨10/12⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이에요.","전체 15칸 가운데 8칸이라고 볼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#14','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',2,'mc','auto','⟨1 2/5⟩ × ⟨1 1/6⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04','M5-2-u2-X12']::text[],true,'{"seq":14,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨1 2/5⟩ × ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 19/30⟩","correct":true},{"t":"⟨1 1/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨7/10⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 19/30⟩","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 2/5⟩ = ⟨7/5⟩, ⟨1 1/6⟩ = ⟨7/6⟩.","분모끼리, 분자끼리 곱해요.","⟨1 2/5⟩ × ⟨1 1/6⟩ = ⟨7/5⟩ × ⟨7/6⟩ = ⟨49/30⟩ = ⟨1 19/30⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3 1/3⟩ × ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨3 1/6⟩","mis":"M5-2-u2-X11"},{"t":"2","mis":"M5-2-u2-X04"},{"t":"6","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨3 1/3⟩ = ⟨10/3⟩, ⟨1 1/2⟩ = ⟨3/2⟩.","분모끼리, 분자끼리 곱해요.","⟨3 1/3⟩ × ⟨1 1/2⟩ = ⟨10/3⟩ × ⟨3/2⟩ = ⟨30/6⟩ = 5예요."]},{"stem":"⟨1 1/2⟩ × ⟨2 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"},{"t":"5","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 1/2⟩ = ⟨3/2⟩, ⟨2 2/3⟩ = ⟨8/3⟩.","분모끼리, 분자끼리 곱해요.","⟨1 1/2⟩ × ⟨2 2/3⟩ = ⟨3/2⟩ × ⟨8/3⟩ = ⟨24/6⟩ = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#15','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C8',2,'sa','auto','하린이네 마을 전체 주민은 64명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 40명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"하린이네 마을 전체 주민은 64명이고, 전체 주민의 ⟨3/4⟩ 이상이 동의해야 작은 체육관을 만들 수 있어요. 지금까지 40명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["① 최소로 동의해야 하는 수: 64 × ⟨3/4⟩ = 48(명)이에요.","② 지금까지 40명이 동의했으니 48 − 40 = 8(명)이에요.","적어도 8명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"도윤이네 마을 전체 주민은 63명이고, 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 38명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 63 × ⟨5/7⟩ = 45(명)이에요.","② 지금까지 38명이 동의했으니 45 − 38 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]},{"stem":"서연이네 마을 전체 주민은 60명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 33명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 60 × ⟨2/3⟩ = 40(명)이에요.","② 지금까지 33명이 동의했으니 40 − 33 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#16','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C1',2,'mc','auto','⟨4/15⟩ + ⟨4/15⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12','M5-2-u2-X15']::text[],true,'{"seq":16,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"⟨4/15⟩ + ⟨4/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/30⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/15⟩","mis":"M5-2-u2-X12"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨4/15⟩ + ⟨4/15⟩ = ⟨8/15⟩이에요.","⟨8/15⟩ — 분모까지 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨6/27⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X12"},{"t":"⟨5/9⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨6/9⟩이에요.","⟨6/9⟩ = ⟨2/3⟩ — 분모까지 더하면 안 돼요."]},{"stem":"⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨8/44⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/11⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/11⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ = ⟨8/11⟩이에요.","⟨8/11⟩ — 분모까지 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#17','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C2',3,'error','auto','⟨4/7⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":17,"concept":"M5-2-u2-C2","difficulty":3,"kind":"error","stem":"⟨4/7⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨4/7⟩ × 2 = ⟨8/14⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"나린 — 「⟨4/7⟩ × 2 = ⟨8/7⟩」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨4/7⟩ × 2 = ⟨1 1/7⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 2 = ⟨8/7⟩ = ⟨1 1/7⟩이에요.","가온은 분모에도 2를 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨5/12⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨5/12⟩ × 3 = ⟨15/36⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"라온 — 「⟨5/12⟩ × 3 = ⟨15/12⟩」","mis":"M5-2-u2-X17"},{"t":"예준 — 「⟨5/12⟩ × 3 = ⟨1 1/4⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨5/12⟩ × 3 = ⟨15/12⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","여울은 분모에도 3을 곱해서 틀렸어요."]},{"stem":"⟨3/8⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨3/8⟩ × 2 = ⟨6/16⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"도윤 — 「⟨3/8⟩ × 2 = ⟨6/8⟩」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨3/8⟩ × 2 = ⟨3/4⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨3/8⟩ × 2 = ⟨6/8⟩ = ⟨3/4⟩이에요.","수아는 분모에도 2를 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#18','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C3',3,'mc','auto','어떤 친구가 ⟨2 1/4⟩ × 6을 「4와 6을 먼저 약분해 ⟨2 1/2⟩ × 3」으로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X02','M5-2-u2-X12']::text[],true,'{"seq":18,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"어떤 친구가 ⟨2 1/4⟩ × 6을 「4와 6을 먼저 약분해 ⟨2 1/2⟩ × 3」으로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨2 1/4⟩에서 분모만 약분하면 자연수 부분 2가 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩.","바르게 하면 ⟨2 1/4⟩ × 6 = ⟨9/4⟩ × 6 = ⟨54/4⟩ = ⟨27/2⟩ = ⟨13 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 친구가 ⟨1 2/9⟩ × 6을 「9와 6을 먼저 약분해 ⟨1 2/3⟩ × 2」로 고쳐 ⟨2 1/3⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 2/9⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 2/9⟩ = ⟨11/9⟩.","바르게 하면 ⟨1 2/9⟩ × 6 = ⟨11/9⟩ × 6 = ⟨66/9⟩ = ⟨22/3⟩ = ⟨7 1/3⟩이에요."]},{"stem":"어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 1/6⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 1/6⟩ = ⟨7/6⟩.","바르게 하면 ⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#19','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',3,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 4보다 작은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":19,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 4보다 작은 것은 어느 것인가요?","options":[{"t":"4 × ⟨9/10⟩","correct":true},{"t":"4 × ⟨1 2/3⟩","mis":"M5-2-u2-X08"},{"t":"4 × 1","mis":"M5-2-u2-X08"},{"t":"4 × ⟨1 1/6⟩","mis":"M5-2-u2-X08"}],"explanation":["4에 1보다 작은 수를 곱하면 4보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨9/10⟩뿐이에요.","그래서 4보다 작은 것은 4 × ⟨9/10⟩예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 7보다 작은 것은 어느 것인가요?","options":[{"t":"7 × ⟨5/6⟩","correct":true},{"t":"7 × ⟨1 1/4⟩","mis":"M5-2-u2-X08"},{"t":"7 × 1","mis":"M5-2-u2-X08"},{"t":"7 × ⟨1 2/5⟩","mis":"M5-2-u2-X08"}],"explanation":["7에 1보다 작은 수를 곱하면 7보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨5/6⟩뿐이에요.","그래서 7보다 작은 것은 7 × ⟨5/6⟩예요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#20','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',3,'error','auto','⟨5/6⟩ × ⟨1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X17']::text[],true,'{"seq":20,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨5/6⟩ × ⟨1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「분모는 그대로 두고 분자끼리 곱해 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"나린 — 「⟨5/6⟩ × ⟨1/3⟩ = ⟨5/18⟩야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「전체 18칸 중 5칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨5/6⟩ × ⟨1/3⟩ = ⟨5/18⟩예요.","가온은 분모를 그대로 두어 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩ × ⟨3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「분모는 그대로 두고 분자끼리 곱해 ⟨6/7⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"라온 — 「⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩이야.」","mis":"M5-2-u2-X17"},{"t":"예준 — 「약분하면 ⟨3/14⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩ = ⟨3/14⟩이에요.","여울은 분모를 그대로 두어 틀렸어요."]},{"stem":"⟨2/3⟩ × ⟨4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「분모는 그대로 두고 분자끼리 곱해 ⟨8/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"도윤 — 「⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「전체 15칸 중 8칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이에요.","수아는 분모를 그대로 두어 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#21','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',3,'error','auto','⟨3 1/2⟩ × ⟨1 1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"⟨3 1/2⟩ × ⟨1 1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"가온 — 「자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨1/5⟩ 해서 ⟨3 1/10⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"나린 — 「가분수로 고쳐 ⟨7/2⟩ × ⟨6/5⟩ = ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"},{"t":"유진 — 「⟨3 1/2⟩ × ⟨1 1/5⟩의 답은 ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨3 1/2⟩ × ⟨1 1/5⟩ = ⟨7/2⟩ × ⟨6/5⟩ = ⟨42/10⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","가온은 부분끼리 따로 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × ⟨1 3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/3⟩ × ⟨3/4⟩ 해서 ⟨2 1/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"라온 — 「가분수로 고쳐 ⟨7/3⟩ × ⟨7/4⟩ = ⟨4 1/12⟩이야.」","mis":"M5-2-u2-X17"},{"t":"예준 — 「⟨2 1/3⟩ × ⟨1 3/4⟩의 답은 ⟨4 1/12⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/3⟩ × ⟨1 3/4⟩ = ⟨7/3⟩ × ⟨7/4⟩ = ⟨49/12⟩ = ⟨4 1/12⟩이에요.","여울은 부분끼리 따로 곱해서 틀렸어요."]},{"stem":"⟨2 1/2⟩ × ⟨1 1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/2⟩ × ⟨1/3⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"도윤 — 「가분수로 고쳐 ⟨5/2⟩ × ⟨4/3⟩ = ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨2 1/2⟩ × ⟨1 1/3⟩의 답은 ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/2⟩ × ⟨1 1/3⟩ = ⟨5/2⟩ × ⟨4/3⟩ = ⟨20/6⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","수아는 부분끼리 따로 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#22','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C8',3,'mc','auto','가온이네 마을은 주민 96명 가운데 ⟨5/8⟩ 이상, 서연이네 마을은 주민 75명 가운데 ⟨4/5⟩ 이상이 동의해야 해요. 지금까지 각각 49명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"가온이네 마을은 주민 96명 가운데 ⟨5/8⟩ 이상, 서연이네 마을은 주민 75명 가운데 ⟨4/5⟩ 이상이 동의해야 해요. 지금까지 각각 49명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"가온이네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["가온이네 마을: 96 × ⟨5/8⟩ = 60, 60 − 49 = 11(명)이에요.","서연이네 마을: 75 × ⟨4/5⟩ = 60, 60 − 55 = 5(명)이에요.","가온이네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"도윤이네 마을","correct":true},{"t":"준기네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["준기네 마을: 85 × ⟨3/5⟩ = 51, 51 − 44 = 7(명)이에요.","도윤이네 마을: 96 × ⟨2/3⟩ = 64, 64 − 55 = 9(명)이에요.","도윤이네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"준기네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 90 × ⟨2/3⟩ = 60, 60 − 52 = 8(명)이에요.","준기네 마을: 80 × ⟨3/5⟩ = 48, 48 − 39 = 9(명)이에요.","준기네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#23','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',4,'sa','auto','⟨1/□⟩ × ⟨1/6⟩ = ⟨1/30⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C6","difficulty":4,"kind":"sa","stem":"⟨1/□⟩ × ⟨1/6⟩ = ⟨1/30⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 6 = 30이어야 해요.","30 ÷ 6 = 5니 □는 5예요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["남학생은 96 × ⟨3/4⟩ = 72명이에요.","그 가운데 ⟨5/8⟩니 72 × ⟨5/8⟩ = 45명이에요.","한 번에 96 × ⟨3/4⟩ × ⟨5/8⟩ = 45로 구해도 같아요."]},{"stem":"⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로이고 분자만 3에서 15로 바뀌었어요.","분자와 □를 곱해 15가 되어야 해요 — 3 × 5 = 15.","그래서 □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#24','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',4,'essay','teacher','⟨4/5⟩ × ⟨2/3⟩를 직사각형 그림으로 설명하려고 해요. 전체를 어떻게 자르는지, 전체 칸과 빗금 친 칸이 몇 개인지 쓰고, 분모끼리·분자끼리 곱하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C6","difficulty":4,"kind":"essay","stem":"⟨4/5⟩ × ⟨2/3⟩를 직사각형 그림으로 설명하려고 해요. 전체를 어떻게 자르는지, 전체 칸과 빗금 친 칸이 몇 개인지 쓰고, 분모끼리·분자끼리 곱하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 전체를 가로로 5등분, 세로로 3등분 하면 전체 칸은 5 × 3 = 15칸이다. ⟨4/5⟩만큼(가로 4칸) 중에서 ⟨2/3⟩만큼(세로 2칸)을 빗금 치면 4 × 2 = 8칸이다. 그래서 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이다. 가로와 세로로 모두 잘랐기 때문에 전체 칸은 분모끼리의 곱, 빗금 친 칸은 분자끼리의 곱이 된다.","scoring_points":["가로 5등분·세로 3등분으로 전체 15칸을 구했는가","빗금 친 칸 8칸을 구했는가","⟨8/15⟩을 구하고 분모끼리·분자끼리 곱하는 까닭을 썼는가"]},"explanation":["전체는 5 × 3 = 15칸이에요.","빗금 친 칸은 4 × 2 = 8칸이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_c#25','math',5,2,'u2','','g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',4,'essay','teacher','5학년 학생 160명 가운데 ⟨5/8⟩가 남학생이고, 남학생 가운데 ⟨3/5⟩이 야구를 좋아해요. 야구를 좋아하는 남학생 수를 두 단계로 나누어 구하고, 세 수의 곱셈 한 식으로도 나타내 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C7","difficulty":4,"kind":"essay","stem":"5학년 학생 160명 가운데 ⟨5/8⟩가 남학생이고, 남학생 가운데 ⟨3/5⟩이 야구를 좋아해요. 야구를 좋아하는 남학생 수를 두 단계로 나누어 구하고, 세 수의 곱셈 한 식으로도 나타내 보세요.","answer_guide":{"answer":"예: 남학생은 160 × ⟨5/8⟩ = 100(명)이다. 그중 야구를 좋아하는 남학생은 100 × ⟨3/5⟩ = 60(명)이다. 한 식으로는 160 × ⟨5/8⟩ × ⟨3/5⟩ = 60(명)이고, 160을 ⟨160/1⟩으로 보면 분모끼리·분자끼리 곱하는 한 규칙으로 계산할 수 있다.","scoring_points":["160 × ⟨5/8⟩ = 100(명)을 구했는가","100 × ⟨3/5⟩ = 60(명)을 구했는가","160 × ⟨5/8⟩ × ⟨3/5⟩ 한 식으로 나타냈는가"]},"explanation":["160 × ⟨5/8⟩ = 100(명)이에요.","100 × ⟨3/5⟩ = 60(명)이에요.","160 × ⟨5/8⟩ × ⟨3/5⟩ = 60이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#1','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C1',1,'mc','auto','⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨4/11⟩ × 3","correct":true},{"t":"⟨4/11⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨4/11⟩ + 3","mis":"M5-2-u2-X15"},{"t":"4 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨4/11⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨4/11⟩ + ⟨4/11⟩ + ⟨4/11⟩ = ⟨4/11⟩ × 3이에요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨2/9⟩ × 3","correct":true},{"t":"⟨2/9⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨2/9⟩ + 3","mis":"M5-2-u2-X15"},{"t":"2 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨2/9⟩를 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨2/9⟩ × 3이에요."]},{"stem":"⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨3/8⟩ × 4","correct":true},{"t":"⟨3/8⟩ × 5","mis":"M5-2-u2-X17"},{"t":"⟨3/8⟩ + 4","mis":"M5-2-u2-X15"},{"t":"3 × 4","mis":"M5-2-u2-X15"}],"explanation":["⟨3/8⟩을 4번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ + ⟨3/8⟩ = ⟨3/8⟩ × 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#2','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C2',1,'sa','auto','⟨4/9⟩ × 2를 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u2-C2","difficulty":1,"kind":"sa","stem":"⟨4/9⟩ × 2를 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 4 × 2 = 8이에요.","⟨4/9⟩ × 2 = ⟨8/9⟩이에요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨2/7⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 2 × 3 = 6이에요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요."]},{"stem":"⟨3/10⟩ × 3을 분모는 그대로 두고 계산했을 때, 약분하기 전 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","분자는 3 × 3 = 9예요.","⟨3/10⟩ × 3 = ⟨9/10⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#3','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C3',1,'mc','auto','⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M5-2-u2-X17"},{"t":"⟨6/6⟩","mis":"M5-2-u2-X04"},{"t":"⟨5/6⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/4⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨1/4⟩을 더하면 분자는 8 + 1 = 9예요.","⟨2 1/4⟩ = ⟨9/4⟩예요."]},{"stem":"⟨1 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/7⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/7⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨7/7⟩이에요 — 1 × 7 = 7.","여기에 ⟨2/7⟩를 더하면 분자는 7 + 2 = 9예요.","⟨1 2/7⟩ = ⟨9/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#4','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',1,'sa','auto','12의 ⟨5/6⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"12의 ⟨5/6⟩는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["12를 똑같이 6으로 나누면 한 묶음은 12 ÷ 6 = 2예요.","그중의 5니 2 × 5 = 10이에요.","식으로는 12 × ⟨5/6⟩ = ⟨60/6⟩ = 10이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"8의 ⟨3/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["8을 똑같이 4로 나누면 한 묶음은 8 ÷ 4 = 2예요.","그중의 3이니 2 × 3 = 6이에요.","식으로는 8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요."]},{"stem":"9의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9를 똑같이 3으로 나누면 한 묶음은 9 ÷ 3 = 3이에요.","그중의 2니 3 × 2 = 6이에요.","식으로는 9 × ⟨2/3⟩ = ⟨18/3⟩ = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#5','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',1,'mc','auto','3 × ⟨1 1/6⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"3 × ⟨1 1/6⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"3보다 크다","correct":true},{"t":"3보다 작다","mis":"M5-2-u2-X08"},{"t":"3과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 1/6⟩이 1보다 커요.","3 × ⟨1 1/6⟩ = ⟨3 1/2⟩이에요.","그래서 「3보다 크다」예요."],"variant_rule":{"alt":[{"stem":"4 × ⟨3/5⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"4보다 작다","correct":true},{"t":"4보다 크다","mis":"M5-2-u2-X08"},{"t":"4와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨3/5⟩이 1보다 작아요.","4 × ⟨3/5⟩ = ⟨2 2/5⟩예요.","그래서 「4보다 작다」예요."]},{"stem":"8 × ⟨1 2/7⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"8보다 크다","correct":true},{"t":"8보다 작다","mis":"M5-2-u2-X08"},{"t":"8과 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 2/7⟩가 1보다 커요.","8 × ⟨1 2/7⟩ = ⟨10 2/7⟩예요.","그래서 「8보다 크다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#6','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',1,'mc','auto','⟨1/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/21⟩","correct":true},{"t":"⟨2/21⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 7등분 한 것 중의 1을 다시 3등분 해요.","전체는 7 × 3 = 21칸이 되고, 그중의 1칸이에요.","⟨1/7⟩ × ⟨1/3⟩ = ⟨1/21⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ × ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/15⟩","correct":true},{"t":"⟨2/15⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/8⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 3등분 한 것 중의 1을 다시 5등분 해요.","전체는 3 × 5 = 15칸이 되고, 그중의 1칸이에요.","⟨1/3⟩ × ⟨1/5⟩ = ⟨1/15⟩이에요."]},{"stem":"⟨1/2⟩ × ⟨1/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/18⟩","correct":true},{"t":"⟨2/18⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 2등분 한 것 중의 1을 다시 9등분 해요.","전체는 2 × 9 = 18칸이 되고, 그중의 1칸이에요.","⟨1/2⟩ × ⟨1/9⟩ = ⟨1/18⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#7','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',1,'sa','auto','⟨3 2/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨3 2/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 3은 ⟨15/5⟩예요.","분자는 3 × 5 + 2 = 17이에요.","⟨3 2/5⟩ = ⟨17/5⟩이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨2 3/4⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 2는 ⟨8/4⟩이에요.","분자는 2 × 4 + 3 = 11이에요.","⟨2 3/4⟩ = ⟨11/4⟩이에요."]},{"stem":"⟨1 5/6⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["자연수 1은 ⟨6/6⟩이에요.","분자는 1 × 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#8','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C8',1,'sa','auto','도윤이네 마을 전체 주민은 63명이에요. 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"도윤이네 마을 전체 주민은 63명이에요. 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["전체 63명의 ⟨5/7⟩ 이상이에요.","63 × ⟨5/7⟩ = 45(명)이에요.","적어도 45명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"서연이네 마을 전체 주민은 60명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 60명의 ⟨2/3⟩ 이상이에요.","60 × ⟨2/3⟩ = 40(명)이에요.","적어도 40명이 동의해야 해요."]},{"stem":"준기네 마을 전체 주민은 70명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["42"],"explanation":["전체 70명의 ⟨3/5⟩ 이상이에요.","70 × ⟨3/5⟩ = 42(명)이에요.","적어도 42명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#9','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C2',2,'mc','auto','⟨3/10⟩ × 6을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨3/10⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨18/60⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/60⟩","mis":"M5-2-u2-X02"},{"t":"⟨9/10⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/10⟩ × 6 = ⟨18/10⟩ = ⟨9/5⟩ = ⟨1 4/5⟩예요.","한 칸의 크기 ⟨1/10⟩은 그대로이고 칸의 수만 6배가 돼요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/28⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/28⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/7⟩ × 4 = ⟨12/7⟩ = ⟨1 5/7⟩예요.","한 칸의 크기 ⟨1/7⟩은 그대로이고 칸의 수만 4배가 돼요."]},{"stem":"⟨5/9⟩ × 2를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/9⟩","correct":true},{"t":"⟨10/18⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/18⟩","mis":"M5-2-u2-X02"},{"t":"⟨7/9⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/9⟩ × 2 = ⟨10/9⟩ = ⟨1 1/9⟩이에요.","한 칸의 크기 ⟨1/9⟩은 그대로이고 칸의 수만 2배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#10','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C3',2,'mc','auto','⟨3 1/2⟩ × 5를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨3 1/2⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨17 1/2⟩","correct":true},{"t":"⟨15 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/2⟩","mis":"M5-2-u2-X05"},{"t":"10","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨3 1/2⟩ × 5 = ⟨7/2⟩ × 5 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","자연수 부분으로 갈라도 3 × 5 + ⟨1/2⟩ × 5 = ⟨17 1/2⟩로 같아요."],"variant_rule":{"alt":[{"stem":"⟨1 2/3⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨6 2/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 2/3⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨1 2/3⟩ × 4 = ⟨5/3⟩ × 4 = ⟨20/3⟩ = ⟨6 2/3⟩예요.","자연수 부분으로 갈라도 1 × 4 + ⟨2/3⟩ × 4 = ⟨6 2/3⟩로 같아요."]},{"stem":"⟨2 1/5⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/5⟩","correct":true},{"t":"⟨6 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 3/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 1/5⟩ = ⟨11/5⟩이에요.","⟨2 1/5⟩ × 3 = ⟨11/5⟩ × 3 = ⟨33/5⟩ = ⟨6 3/5⟩이에요.","자연수 부분으로 갈라도 2 × 3 + ⟨1/5⟩ × 3 = ⟨6 3/5⟩으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#11','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',2,'mc','auto','4 × ⟨7/9⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X07']::text[],true,'{"seq":11,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"4 × ⟨7/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 1/9⟩","correct":true},{"t":"⟨28/36⟩","mis":"M5-2-u2-X01"},{"t":"⟨7/36⟩","mis":"M5-2-u2-X02"},{"t":"28","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","4 × ⟨7/9⟩ = ⟨28/9⟩ = ⟨3 1/9⟩이에요.","4를 똑같이 9로 나눈 것 중의 7만큼이에요."],"variant_rule":{"alt":[{"stem":"5 × ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X02"},{"t":"10","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","5를 똑같이 3으로 나눈 것 중의 2만큼이에요."]},{"stem":"3 × ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/21⟩","mis":"M5-2-u2-X02"},{"t":"12","mis":"M5-2-u2-X07"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨4/7⟩ = ⟨12/7⟩ = ⟨1 5/7⟩예요.","3을 똑같이 7로 나눈 것 중의 4만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#12','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',2,'mc','auto','4 × ⟨1 1/6⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":12,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"4 × ⟨1 1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨4 1/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/6⟩ = ⟨7/6⟩이에요.","4 × ⟨1 1/6⟩ = 4 × ⟨7/6⟩ = ⟨28/6⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","둘로 갈라도 4 × 1 + 4 × ⟨1/6⟩ = ⟨4 2/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"3 × ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨1 1/4⟩ = ⟨5/4⟩예요.","3 × ⟨1 1/4⟩ = 3 × ⟨5/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","둘로 갈라도 3 × 1 + 3 × ⟨1/4⟩ = ⟨3 3/4⟩으로 같아요."]},{"stem":"2 × ⟨2 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 고치면 ⟨2 2/3⟩ = ⟨8/3⟩이에요.","2 × ⟨2 2/3⟩ = 2 × ⟨8/3⟩ = ⟨16/3⟩ = ⟨5 1/3⟩이에요.","둘로 갈라도 2 × 2 + 2 × ⟨2/3⟩ = ⟨5 1/3⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#13','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',2,'mc','auto','⟨7/8⟩ × ⟨4/5⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":13,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨7/8⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨28/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨28/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨35/32⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨7/8⟩ × ⟨4/5⟩ = ⟨28/40⟩ = ⟨7/10⟩이에요.","전체 40칸 가운데 28칸이라고 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩ × ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨10/12⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이에요.","전체 15칸 가운데 8칸이라고 볼 수 있어요."]},{"stem":"⟨5/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/21⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨15/7⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨5/7⟩ × ⟨1/3⟩ = ⟨5/21⟩예요.","전체 21칸 가운데 5칸이라고 볼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#14','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',2,'mc','auto','⟨3 1/3⟩ × ⟨1 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04','M5-2-u2-X12']::text[],true,'{"seq":14,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨3 1/3⟩ × ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨3 1/6⟩","mis":"M5-2-u2-X11"},{"t":"2","mis":"M5-2-u2-X04"},{"t":"6","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨3 1/3⟩ = ⟨10/3⟩, ⟨1 1/2⟩ = ⟨3/2⟩.","분모끼리, 분자끼리 곱해요.","⟨3 1/3⟩ × ⟨1 1/2⟩ = ⟨10/3⟩ × ⟨3/2⟩ = ⟨30/6⟩ = 5예요."],"variant_rule":{"alt":[{"stem":"⟨1 1/2⟩ × ⟨2 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"},{"t":"5","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨1 1/2⟩ = ⟨3/2⟩, ⟨2 2/3⟩ = ⟨8/3⟩.","분모끼리, 분자끼리 곱해요.","⟨1 1/2⟩ × ⟨2 2/3⟩ = ⟨3/2⟩ × ⟨8/3⟩ = ⟨24/6⟩ = 4예요."]},{"stem":"⟨2 1/4⟩ × ⟨1 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 1/12⟩","mis":"M5-2-u2-X11"},{"t":"1","mis":"M5-2-u2-X04"},{"t":"4","mis":"M5-2-u2-X12"}],"explanation":["대분수는 가분수로 고쳐요 — ⟨2 1/4⟩ = ⟨9/4⟩, ⟨1 1/3⟩ = ⟨4/3⟩.","분모끼리, 분자끼리 곱해요.","⟨2 1/4⟩ × ⟨1 1/3⟩ = ⟨9/4⟩ × ⟨4/3⟩ = ⟨36/12⟩ = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#15','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C8',2,'sa','auto','도윤이네 마을 전체 주민은 63명이고, 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 38명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"도윤이네 마을 전체 주민은 63명이고, 전체 주민의 ⟨5/7⟩ 이상이 동의해야 마을 텃밭을 만들 수 있어요. 지금까지 38명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 63 × ⟨5/7⟩ = 45(명)이에요.","② 지금까지 38명이 동의했으니 45 − 38 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"서연이네 마을 전체 주민은 60명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 33명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 60 × ⟨2/3⟩ = 40(명)이에요.","② 지금까지 33명이 동의했으니 40 − 33 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]},{"stem":"준기네 마을 전체 주민은 70명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 어린이 놀이 공간을 만들 수 있어요. 지금까지 35명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["① 최소로 동의해야 하는 수: 70 × ⟨3/5⟩ = 42(명)이에요.","② 지금까지 35명이 동의했으니 42 − 35 = 7(명)이에요.","적어도 7명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#16','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C1',2,'mc','auto','⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12','M5-2-u2-X15']::text[],true,'{"seq":16,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨6/27⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X12"},{"t":"⟨5/9⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/9⟩ + ⟨2/9⟩ + ⟨2/9⟩ = ⟨6/9⟩이에요.","⟨6/9⟩ = ⟨2/3⟩ — 분모까지 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨8/44⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 8/11⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/11⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ + ⟨2/11⟩ = ⟨8/11⟩이에요.","⟨8/11⟩ — 분모까지 더하면 안 돼요."]},{"stem":"⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩을 계산하면 얼마인가요?","options":[{"t":"⟨9/13⟩","correct":true},{"t":"⟨9/39⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 9/13⟩","mis":"M5-2-u2-X12"},{"t":"⟨6/13⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자끼리 더해요.","⟨3/13⟩ + ⟨3/13⟩ + ⟨3/13⟩ = ⟨9/13⟩예요.","⟨9/13⟩ — 분모까지 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#17','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C2',3,'error','auto','⟨5/12⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":17,"concept":"M5-2-u2-C2","difficulty":3,"kind":"error","stem":"⟨5/12⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨5/12⟩ × 3 = ⟨15/36⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"라온 — 「⟨5/12⟩ × 3 = ⟨15/12⟩」","mis":"M5-2-u2-X17"},{"t":"예준 — 「⟨5/12⟩ × 3 = ⟨1 1/4⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨5/12⟩ × 3 = ⟨15/12⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","여울은 분모에도 3을 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ × 2를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨3/8⟩ × 2 = ⟨6/16⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"도윤 — 「⟨3/8⟩ × 2 = ⟨6/8⟩」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨3/8⟩ × 2 = ⟨3/4⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨3/8⟩ × 2 = ⟨6/8⟩ = ⟨3/4⟩이에요.","수아는 분모에도 2를 곱해서 틀렸어요."]},{"stem":"⟨2/9⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨2/9⟩ × 3 = ⟨6/27⟩」","correct":true,"mis_target":"M5-2-u2-X01"},{"t":"서연 — 「⟨2/9⟩ × 3 = ⟨6/9⟩」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨2/9⟩ × 3 = ⟨2/3⟩」","mis":"M5-2-u2-X17"}],"explanation":["(진분수)×(자연수)는 분모를 그대로 두고 분자와 자연수를 곱해요.","⟨2/9⟩ × 3 = ⟨6/9⟩ = ⟨2/3⟩예요.","민준은 분모에도 3을 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#18','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C3',3,'mc','auto','어떤 친구가 ⟨1 2/9⟩ × 6을 「9와 6을 먼저 약분해 ⟨1 2/3⟩ × 2」로 고쳐 ⟨2 1/3⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X02','M5-2-u2-X12']::text[],true,'{"seq":18,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"어떤 친구가 ⟨1 2/9⟩ × 6을 「9와 6을 먼저 약분해 ⟨1 2/3⟩ × 2」로 고쳐 ⟨2 1/3⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 2/9⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 2/9⟩ = ⟨11/9⟩.","바르게 하면 ⟨1 2/9⟩ × 6 = ⟨11/9⟩ × 6 = ⟨66/9⟩ = ⟨22/3⟩ = ⟨7 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨3 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 1/6⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 1/6⟩ = ⟨7/6⟩.","바르게 하면 ⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이에요."]},{"stem":"어떤 친구가 ⟨1 3/8⟩ × 4를 「8과 4를 먼저 약분해 ⟨1 3/2⟩ × 1」로 고쳐 ⟨2 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 3/8⟩에서 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","먼저 가분수로 고쳐요 — ⟨1 3/8⟩ = ⟨11/8⟩.","바르게 하면 ⟨1 3/8⟩ × 4 = ⟨11/8⟩ × 4 = ⟨44/8⟩ = ⟨11/2⟩ = ⟨5 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#19','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',3,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 7보다 작은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":19,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 7보다 작은 것은 어느 것인가요?","options":[{"t":"7 × ⟨5/6⟩","correct":true},{"t":"7 × ⟨1 1/4⟩","mis":"M5-2-u2-X08"},{"t":"7 × 1","mis":"M5-2-u2-X08"},{"t":"7 × ⟨1 2/5⟩","mis":"M5-2-u2-X08"}],"explanation":["7에 1보다 작은 수를 곱하면 7보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 작은 수는 ⟨5/6⟩뿐이에요.","그래서 7보다 작은 것은 7 × ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 6보다 큰 것은 어느 것인가요?","options":[{"t":"6 × ⟨1 1/5⟩","correct":true},{"t":"6 × ⟨3/4⟩","mis":"M5-2-u2-X08"},{"t":"6 × 1","mis":"M5-2-u2-X08"},{"t":"6 × ⟨7/8⟩","mis":"M5-2-u2-X08"}],"explanation":["6에 1보다 작은 수를 곱하면 6보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/5⟩뿐이에요.","그래서 6보다 큰 것은 6 × ⟨1 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#20','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',3,'error','auto','⟨2/7⟩ × ⟨3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X17']::text[],true,'{"seq":20,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨2/7⟩ × ⟨3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「분모는 그대로 두고 분자끼리 곱해 ⟨6/7⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"라온 — 「⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩이야.」","mis":"M5-2-u2-X17"},{"t":"예준 — 「약분하면 ⟨3/14⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨2/7⟩ × ⟨3/4⟩ = ⟨6/28⟩ = ⟨3/14⟩이에요.","여울은 분모를 그대로 두어 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩ × ⟨4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「분모는 그대로 두고 분자끼리 곱해 ⟨8/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"도윤 — 「⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「전체 15칸 중 8칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨2/3⟩ × ⟨4/5⟩ = ⟨8/15⟩이에요.","수아는 분모를 그대로 두어 틀렸어요."]},{"stem":"⟨3/4⟩ × ⟨1/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「분모는 그대로 두고 분자끼리 곱해 ⟨3/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"서연 — 「⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「전체 20칸 중 3칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이에요.","민준은 분모를 그대로 두어 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#21','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',3,'error','auto','⟨2 1/3⟩ × ⟨1 3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"⟨2 1/3⟩ × ⟨1 3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/3⟩ × ⟨3/4⟩ 해서 ⟨2 1/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"라온 — 「가분수로 고쳐 ⟨7/3⟩ × ⟨7/4⟩ = ⟨4 1/12⟩이야.」","mis":"M5-2-u2-X17"},{"t":"예준 — 「⟨2 1/3⟩ × ⟨1 3/4⟩의 답은 ⟨4 1/12⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/3⟩ × ⟨1 3/4⟩ = ⟨7/3⟩ × ⟨7/4⟩ = ⟨49/12⟩ = ⟨4 1/12⟩이에요.","여울은 부분끼리 따로 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2 1/2⟩ × ⟨1 1/3⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「자연수끼리 2 × 1, 분수끼리 ⟨1/2⟩ × ⟨1/3⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"도윤 — 「가분수로 고쳐 ⟨5/2⟩ × ⟨4/3⟩ = ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"하린 — 「⟨2 1/2⟩ × ⟨1 1/3⟩의 답은 ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 1/2⟩ × ⟨1 1/3⟩ = ⟨5/2⟩ × ⟨4/3⟩ = ⟨20/6⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","수아는 부분끼리 따로 곱해서 틀렸어요."]},{"stem":"⟨1 1/4⟩ × ⟨2 2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「자연수끼리 1 × 2, 분수끼리 ⟨1/4⟩ × ⟨2/3⟩ 해서 ⟨2 1/6⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"서연 — 「가분수로 고쳐 ⟨5/4⟩ × ⟨8/3⟩ = ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"지호 — 「⟨1 1/4⟩ × ⟨2 2/3⟩의 답은 ⟨3 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨1 1/4⟩ × ⟨2 2/3⟩ = ⟨5/4⟩ × ⟨8/3⟩ = ⟨40/12⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","민준은 부분끼리 따로 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#22','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C8',3,'mc','auto','준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"도윤이네 마을","correct":true},{"t":"준기네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["준기네 마을: 85 × ⟨3/5⟩ = 51, 51 − 44 = 7(명)이에요.","도윤이네 마을: 96 × ⟨2/3⟩ = 64, 64 − 55 = 9(명)이에요.","도윤이네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"준기네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 90 × ⟨2/3⟩ = 60, 60 − 52 = 8(명)이에요.","준기네 마을: 80 × ⟨3/5⟩ = 48, 48 − 39 = 9(명)이에요.","준기네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 60명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"하린이네 마을","correct":true},{"t":"도윤이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["하린이네 마을: 72 × ⟨3/4⟩ = 54, 54 − 47 = 7(명)이에요.","도윤이네 마을: 84 × ⟨3/4⟩ = 63, 63 − 60 = 3(명)이에요.","하린이네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#23','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',4,'sa','auto','5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C7","difficulty":4,"kind":"sa","stem":"5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["남학생은 96 × ⟨3/4⟩ = 72명이에요.","그 가운데 ⟨5/8⟩니 72 × ⟨5/8⟩ = 45명이에요.","한 번에 96 × ⟨3/4⟩ × ⟨5/8⟩ = 45로 구해도 같아요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로이고 분자만 3에서 15로 바뀌었어요.","분자와 □를 곱해 15가 되어야 해요 — 3 × 5 = 15.","그래서 □는 5예요."]},{"stem":"20 × ⟨□/4⟩ = 15일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["20을 똑같이 4로 나누면 한 묶음은 5예요.","3묶음이 15니 □ = 15 ÷ 5 = 3이에요.","20 × ⟨3/4⟩ = 15 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#24','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',4,'essay','teacher','가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭의 넓이를 세로를 둘로 갈라 구하는 방법으로 설명하고, 가분수로 고쳐 구한 값과 같은지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C5","difficulty":4,"kind":"essay","stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭의 넓이를 세로를 둘로 갈라 구하는 방법으로 설명하고, 가분수로 고쳐 구한 값과 같은지 확인해 보세요.","answer_guide":{"answer":"예: 세로 ⟨1 2/5⟩ m를 1 m와 ⟨2/5⟩ m로 가르면, 세로 1 m인 부분은 2 × 1 = 2 m², 세로 ⟨2/5⟩ m인 부분은 2 × ⟨2/5⟩ = ⟨4/5⟩ m²이다. 둘을 더하면 2 + ⟨4/5⟩ = ⟨2 4/5⟩ m²이다. 가분수로 고치면 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ m²로 같다.","scoring_points":["세로를 1과 ⟨2/5⟩로 갈라 두 넓이를 구했는가","⟨2 4/5⟩ m²를 구했는가","가분수로 고쳐 구한 값과 같음을 확인했는가"]},"explanation":["2 × 1 = 2, 2 × ⟨2/5⟩ = ⟨4/5⟩예요.","2 + ⟨4/5⟩ = ⟨2 4/5⟩ m²예요.","2 × ⟨7/5⟩ = ⟨2 4/5⟩ — 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u2_review_d#25','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C1',4,'essay','teacher','여울이, 순달이, 달곰이가 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유의 양을 덧셈식과 곱셈식으로 각각 나타내고, 모두 몇 L인지 구해 보세요. 그리고 20명이 남겼다면 어떤 식이 더 편한지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C1","difficulty":4,"kind":"essay","stem":"여울이, 순달이, 달곰이가 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유의 양을 덧셈식과 곱셈식으로 각각 나타내고, 모두 몇 L인지 구해 보세요. 그리고 20명이 남겼다면 어떤 식이 더 편한지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 덧셈식은 ⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩이고 곱셈식은 ⟨3/10⟩ × 3이다. 분모는 그대로 두고 분자끼리 더하면 ⟨9/10⟩ L이다. 20명이 남겼다면 ⟨3/10⟩을 20번 더해야 해서 덧셈식이 너무 길어지므로, ⟨3/10⟩ × 20처럼 곱셈식으로 적는 것이 한 줄로 끝나 더 편하다.","scoring_points":["덧셈식과 곱셈식 ⟨3/10⟩ × 3을 모두 썼는가","⟨9/10⟩ L를 구했는가","여러 번 더할 때는 곱셈식이 짧아 편하다고 설명했는가"]},"explanation":["⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨3/10⟩ × 3이에요.","분자끼리 더하면 ⟨9/10⟩ L예요.","20번이면 곱셈식이 한 줄로 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
